window.ETSDATA=window.ETSDATA||{};window.ETSDATA[6]={"lc":{"p1":[{"n":1,"opts":["A restaurant buffet is filled with food.","Cups are sitting in a sink.","A dining area is empty.","Some candles have been lit."],"vi":["Quầy buffet của nhà hàng được bày đầy thức ăn.","Các cốc đang được đặt trong bồn rửa.","Khu vực ăn uống thì trống trơn.","Một vài cây nến đã được thắp sáng."],"ans":"C","a":"E26-T06-01.mp3","img":"q1.jpg"},{"n":2,"opts":["He’s facing a machine.","He’s lifting up a machine.","He’s wiping down a machine.","He’s repairing a machine with a tool."],"vi":["Người đàn ông đang đứng đối diện một cái máy.","Người đàn ông đang nâng một cái máy lên.","Người đàn ông đang lau chùi một cái máy.","Người đàn ông đang sửa chữa một cái máy bằng dụng cụ."],"ans":"A","a":"E26-T06-02.mp3","img":"q2.jpg"},{"n":3,"opts":["A man is tying his shoe.","A woman is looking through her purse.","They’re boarding a bus.","They’re walking past a bench."],"vi":["Một người đàn ông đang buộc dây giày.","Một người phụ nữ đang lục túi xách của mình.","Họ đang lên xe buýt.","Họ đang đi ngang qua một chiếc ghế dài (ghế băng)."],"ans":"D","a":"E26-T06-03.mp3","img":"q3.jpg"},{"n":4,"opts":["She’s organizing a workstation.","She’s holding a water bottle.","She’s removing a book from a shelf.","She’s reaching for a pen."],"vi":["Cô ấy đang sắp xếp khu vực làm việc.","Cô ấy đang cầm một chai nước.","Cô ấy đang lấy một cuốn sách khỏi kệ.","Cô ấy đang với tay lấy một cây bút."],"ans":"B","a":"E26-T06-04.mp3","img":"q4.jpg"},{"n":5,"opts":["A woman is lifting a suitcase onto a counter.","A woman is writing on a piece of paper.","A woman is leaning against a glass door.","A woman is talking to a worker at a desk."],"vi":["Một người phụ nữ đang nhấc vali lên quầy.","Một người phụ nữ đang viết trên một tờ giấy.","Một người phụ nữ đang tựa vào cửa kính.","Một người phụ nữ đang nói chuyện với một nhân viên tại bàn làm việc."],"ans":"D","a":"E26-T06-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some paintings have been hung above a sofa.","Some wooden chairs are stacked in a corner.","There are lamps lighting some seating areas.","There are curtains framing a doorway."],"vi":["Một số bức tranh đã được treo phía trên ghế sofa.","Một số ghế gỗ được xếp chồng ở góc phòng.","Có những chiếc đèn đang chiếu sáng một số khu vực ghế ngồi.","Có rèm cửa bao quanh khung cửa ra vào."],"ans":"C","a":"E26-T06-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"How long will the renovations take?","qvi":"Việc cải tạo sẽ mất bao lâu?","opts":["About a month.","Mostly the roof.","I finished that book."],"vi":["Khoảng một tháng.","Chủ yếu là phần mái nhà.","Tôi đã đọc xong cuốn sách đó rồi."],"ans":"A","a":"E26-T06-07.mp3"},{"n":8,"q":"What is the factory's inspection process like?","qvi":"Quy trình kiểm tra của nhà máy như thế nào?","opts":["It's quite thorough.","I didn't bring any.","He likes working nights."],"vi":["Nó khá là kỹ lưỡng.","Tôi đã không mang theo cái nào cả.","Anh ấy thích làm việc ca đêm."],"ans":"A","a":"E26-T06-08.mp3"},{"n":9,"q":"Hasn't our merchandise arrived yet?","qvi":"Hàng hóa của chúng ta vẫn chưa đến sao?","opts":["Handmade clothing.","I can drive you there.","No, it was just shipped yesterday."],"vi":["Quần áo may thủ công.","Tôi có thể lái xe đưa bạn đến đó.","Chưa, nó vừa mới được gửi đi vào ngày hôm qua."],"ans":"C","a":"E26-T06-09.mp3"},{"n":10,"q":"Who's buying beverages for the retreat?","qvi":"Ai sẽ mua đồ uống cho chuyến nghỉ dưỡng/buổi họp mặt?","opts":["At the café.","I parked the car by the tree.","Carlos and I are."],"vi":["Tại quán cà phê.","Tôi đã đỗ xe ở cạnh cái cây.","Carlos và tôi sẽ mua."],"ans":"C","a":"E26-T06-10.mp3"},{"n":11,"q":"Why is the reception at a different location?","qvi":"Tại sao buổi tiệc chiêu đãi lại ở một địa điểm khác?","opts":["Sure, let's go greet the guests.","Because the conference room wasn't big enough.","Yes, I can hear you very well—thank you."],"vi":["Chắc chắn rồi, hãy đi chào đón khách thôi.","Bởi vì phòng hội nghị đã không đủ lớn.","Vâng, tôi có thể nghe bạn rất rõ—cảm ơn bạn."],"ans":"B","a":"E26-T06-11.mp3"},{"n":12,"q":"Would you like me to process your travel voucher?","qvi":"Bạn có muốn tôi xử lý phiếu thanh toán chi phí đi lại của bạn không?","opts":["I didn’t know that.","A much larger convention center.","Yes, if you have time."],"vi":["Tôi đã không biết điều đó.","Một trung tâm hội nghị lớn hơn nhiều.","Vâng, nếu bạn có thời gian."],"ans":"C","a":"E26-T06-12.mp3"},{"n":13,"q":"How far away is Azuma’s Dry Cleaning Company?","qvi":"Công ty Giặt khô Azuma cách đây bao xa?","opts":["No, not until I’ve seen it.","Oh, it’s only a few minutes’ walk from here.","Five dollars per shirt."],"vi":["Không, cho đến khi tôi nhìn thấy nó.","Ồ, chỉ mất vài phút đi bộ từ đây thôi.","Năm đô la cho mỗi chiếc sơ mi."],"ans":"B","a":"E26-T06-13.mp3"},{"n":14,"q":"Do we have the registration forms ready for the students?","qvi":"Chúng ta đã chuẩn bị sẵn các mẫu đơn đăng ký cho sinh viên chưa?","opts":["The manager’s signature.","Yes, I printed them.","We require uniforms."],"vi":["Chữ ký của quản lý.","Rồi, tôi đã in chúng rồi.","Chúng tôi yêu cầu đồng phục."],"ans":"B","a":"E26-T06-14.mp3"},{"n":15,"q":"I could provide you with a copy of the lease.","qvi":"Tôi có thể cung cấp cho bạn một bản sao của hợp đồng thuê nhà.","opts":["Great—I need it for my records.","At least another week.","Why don’t we offer a discount?"],"vi":["Tuyệt quá—tôi cần nó để lưu hồ sơ.","Ít nhất là một tuần nữa.","Tại sao chúng ta không đưa ra chương trình giảm giá nhỉ?"],"ans":"A","a":"E26-T06-15.mp3"},{"n":16,"q":"How many oil changes are scheduled for this afternoon?","qvi":"Có bao nhiêu lịch thay dầu được sắp xếp vào chiều nay?","opts":["A few replacement pieces.","Right now, there are five.","Can you change the channel?"],"vi":["Một vài phụ tùng thay thế.","Hiện tại thì có năm xe.","Bạn có thể chuyển kênh không?"],"ans":"B","a":"E26-T06-16.mp3"},{"n":17,"q":"When was the last time you traveled for business?","qvi":"Lần cuối cùng bạn đi công tác là khi nào?","opts":["About three years ago.","It’s the black briefcase.","I have some stamps."],"vi":["Khoảng ba năm trước.","Đó là chiếc cặp tài liệu màu đen.","Tôi có một vài con tem."],"ans":"A","a":"E26-T06-17.mp3"},{"n":18,"q":"Should I order the parts online or over the phone?","qvi":"Tôi nên đặt hàng các linh kiện qua mạng hay qua điện thoại?","opts":["Just half—thank you.","No, I’ve never been there.","By phone is best."],"vi":["Chỉ một nửa thôi—cảm ơn bạn.","Không, tôi chưa từng đến đó.","Qua điện thoại là tốt nhất."],"ans":"C","a":"E26-T06-18.mp3"},{"n":19,"q":"Where should I pick up my conference badge?","qvi":"Tôi nên lấy thẻ tham dự hội nghị ở đâu?","opts":["We signed the lease.","About 10,000 units per week.","There are three tables in the lobby."],"vi":["Chúng tôi đã ký hợp đồng thuê.","Khoảng 10.000 đơn vị mỗi tuần.","Có ba chiếc bàn ở sảnh đợi."],"ans":"C","a":"E26-T06-19.mp3"},{"n":20,"q":"Isn’t the computer network running a bit slow?","qvi":"Mạng máy tính đang chạy hơi chậm đúng không?","opts":["To an upgraded service.","Actually, I prefer to walk.","A technician’s on the way."],"vi":["Đến một dịch vụ đã được nâng cấp.","Thực ra, tôi thích đi bộ hơn.","Nhân viên kỹ thuật đang trên đường đến rồi."],"ans":"C","a":"E26-T06-20.mp3"},{"n":21,"q":"How do you like this office space?","qvi":"Bạn thích không gian văn phòng này như thế nào?","opts":["An afternoon appointment.","I'd rather have a window.","On page five of the contract."],"vi":["Một cuộc hẹn buổi chiều.","Tôi muốn có một cửa sổ hơn.","Ở trang năm của hợp đồng."],"ans":"B","a":"E26-T06-21.mp3"},{"n":22,"q":"You can use the company van to make your deliveries.","qvi":"Bạn có thể sử dụng xe tải của công ty để giao hàng.","opts":["OK, I'll go get the key.","A clothing manufacturer.","It's on Market Street."],"vi":["OK, tôi sẽ đi lấy chìa khóa.","Một nhà sản xuất quần áo.","Nó nằm trên phố Market."],"ans":"A","a":"E26-T06-22.mp3"},{"n":23,"q":"Isn't the city council meeting tonight?","qvi":"Tối nay không phải là cuộc họp hội đồng thành phố sao?","opts":["Thanks—that would be great.","He's the recently elected mayor.","Did you check their Web site?"],"vi":["Cảm ơn—điều đó thật tuyệt vời.","Ông ấy là thị trưởng mới đắc cử.","Bạn đã kiểm tra trang web của họ chưa?"],"ans":"C","a":"E26-T06-23.mp3"},{"n":24,"q":"Could you look at the revised logo tomorrow?","qvi":"Bạn có thể xem lại logo đã sửa đổi vào ngày mai không?","opts":["A color printer.","The score was tied.","I have time now."],"vi":["Một máy in màu.","Tỷ số đã hòa.","Bây giờ tôi có thời gian."],"ans":"C","a":"E26-T06-24.mp3"},{"n":25,"q":"Is the business local or national?","qvi":"Doanh nghiệp này mang tính địa phương hay quốc gia?","opts":["At the community center nearby.","We have stores in every province.","The flight's in two hours."],"vi":["Tại trung tâm cộng đồng gần đó.","Chúng tôi có các cửa hàng ở mọi tỉnh thành.","Chuyến bay sẽ khởi hành sau hai giờ nữa."],"ans":"B","a":"E26-T06-25.mp3"},{"n":26,"q":"How do you make sure your products will sell well?","qvi":"Làm sao để bạn đảm bảo sản phẩm của mình sẽ bán chạy?","opts":["No, I bought it last month.","I conduct market research.","OK, I'll bring it."],"vi":["Không, tôi đã mua nó tháng trước.","Tôi tiến hành nghiên cứu thị trường.","OK, tôi sẽ mang nó đến."],"ans":"B","a":"E26-T06-26.mp3"},{"n":27,"q":"Who will fill the open manager position?","qvi":"Ai sẽ đảm nhận vị trí quản lý đang bỏ trống?","opts":["Interviews will take place next week.","I'd like a refill on my coffee, please.","The desk should be in the corner."],"vi":["Các cuộc phỏng vấn sẽ diễn ra vào tuần tới.","Tôi muốn được rót thêm cà phê.","Chiếc bàn nên ở trong góc."],"ans":"A","a":"E26-T06-27.mp3"},{"n":28,"q":"Where do you want to store the extra brochures?","qvi":"Bạn muốn cất những cuốn tài liệu quảng cáo bổ sung ở đâu?","opts":["The price lists for new products.","I think that's right.","There are none left."],"vi":["Bảng giá cho các sản phẩm mới.","Tôi nghĩ điều đó đúng.","Không còn cái nào cả."],"ans":"C","a":"E26-T06-28.mp3"},{"n":29,"q":"The new bottling machine's been installed, hasn't it?","qvi":"Máy đóng chai mới đã được lắp đặt rồi, phải không?","opts":["We'll have two packs, please.","No, I didn't drive here.","We're expecting delivery this afternoon."],"vi":["Làm ơn cho chúng tôi hai gói.","Không, tôi không lái xe đến đây.","Chúng tôi đang mong đợi việc giao hàng vào chiều nay."],"ans":"C","a":"E26-T06-29.mp3"},{"n":30,"q":"Shouldn't we update our security protocol?","qvi":"Chúng ta không nên cập nhật giao thức bảo mật của mình sao?","opts":["About an hour.","We have a good plan in place.","No, it wasn't."],"vi":["Khoảng một giờ.","Chúng tôi đã có một kế hoạch tốt sẵn sàng.","Không, nó không phải."],"ans":"B","a":"E26-T06-30.mp3"},{"n":31,"q":"The engineering team would like to meet sometime today.","qvi":"Đội ngũ kỹ thuật muốn gặp nhau vào lúc nào đó trong hôm nay.","opts":["Yes, Mr. Tamura is from Kyoto.","Before or after the company-wide meeting?","That was a long baseball game."],"vi":["Vâng, ông Tamura đến từ Kyoto.","Trước hay sau cuộc họp toàn công ty?","Đó là một trận đấu bóng chày dài."],"ans":"B","a":"E26-T06-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","I saw one of the new commercials about our business on television last week. I guess the advertising campaign has already launched.","Tuần trước tôi thấy một trong những quảng cáo mới về công ty chúng ta trên truyền hình. Tôi đoán chiến dịch quảng cáo đã bắt đầu rồi."],["M","This ad campaign's coming out at a great time for us. It's our busy season—people are starting to book our tours for their vacations.","Chiến dịch quảng cáo này ra mắt vào thời điểm tuyệt vời cho chúng ta. Đây là mùa cao điểm—mọi người đang bắt đầu đặt tour cho kỳ nghỉ của họ."],["W","There's still some money in the budget. We should use it to advertise our most recent package—a guided exploration of the theater district, including tickets to a performance.","Vẫn còn một chút tiền trong ngân sách. Chúng ta nên dùng nó để quảng cáo gói dịch vụ mới nhất—một chuyến khám phá khu vực nhà hát có hướng dẫn, bao gồm vé xem biểu diễn."],["M","That's a good idea. Let me check how much it would cost to add that information to our current commercials.","Ý hay đấy. Để tôi kiểm tra xem chi phí thêm thông tin đó vào quảng cáo hiện tại là bao nhiêu."]],"qs":[{"n":32,"q":"According to the woman, what happened last week?","qvi":"Theo người phụ nữ, chuyện gì xảy ra tuần trước?","opts":["A new product was launched.","A new location opened.","An advertising campaign started.","A budget was approved."],"vi":["Một sản phẩm mới được ra mắt.","Một địa điểm mới mở cửa.","Chiến dịch quảng cáo bắt đầu.","Ngân sách được phê duyệt."],"ans":"C"},{"n":33,"q":"What industry do the speakers work in?","qvi":"Những người nói làm việc trong ngành nào?","opts":["Finance","Retail","Energy","Tourism"],"vi":["Tài chính","Bán lẻ","Năng lượng","Du lịch"],"ans":"D"},{"n":34,"q":"What does the man say he will check on?","qvi":"Người đàn ông nói sẽ kiểm tra gì?","opts":["Transportation","Tickets","Some prices","Some contracts"],"vi":["Phương tiện di chuyển","Vé","Một số giá cả","Một số hợp đồng"],"ans":"C"}],"a":"E26-T06-32-34.mp3"},{"ns":[35,37],"script":[["W","Marcel, we've been getting some complaints from our guests when they check out. Some people think the parking garage fee is included in the room reservation. They don't know they have to pay when they exit.","Marcel, chúng ta đang nhận được một số khiếu nại từ khách khi họ check out. Một số người nghĩ phí đỗ xe đã bao gồm trong đặt phòng. Họ không biết phải trả tiền khi rời đi."],["M","Oh. Well, it's written on the confirmation they receive. But I'll start reminding our guests at check-in as well.","Ồ. Nó được ghi trên xác nhận họ nhận được. Nhưng tôi sẽ bắt đầu nhắc nhở khách lúc check-in nữa."],["W","Great, thank you. Also, remember the landscaping crew is coming by next week to plant some spring flowers by the entrance of the lobby. It's starting to feel a bit warmer outside.","Tuyệt, cảm ơn. Ngoài ra, nhớ là đội làm cảnh quan sẽ đến tuần sau để trồng hoa mùa xuân ở lối vào sảnh. Ngoài trời bắt đầu ấm hơn rồi."]],"qs":[{"n":35,"q":"Where do the speakers most likely work?","qvi":"Những người nói có lẽ làm việc ở đâu?","opts":["At a hotel","At a beauty salon","At a gym","At a shopping mall"],"vi":["Tại khách sạn","Tại tiệm làm đẹp","Tại phòng gym","Tại trung tâm mua sắm"],"ans":"A"},{"n":36,"q":"How does the man plan to address a problem?","qvi":"Người đàn ông dự định giải quyết vấn đề như thế nào?","opts":["By resending a confirmation e-mail","By giving a verbal reminder","By extending hours of operation","By discounting the price of a service"],"vi":["Bằng cách gửi lại email xác nhận","Bằng cách nhắc miệng","Bằng cách kéo dài giờ hoạt động","Bằng cách giảm giá dịch vụ"],"ans":"B"},{"n":37,"q":"Why will landscapers come next week?","qvi":"Tại sao đội làm cảnh quan sẽ đến tuần sau?","opts":["To install a water fountain","To cut down some tree branches","To plant some flowers","To cut the grass"],"vi":["Để lắp đặt đài phun nước","Để cắt cành cây","Để trồng hoa","Để cắt cỏ"],"ans":"C"}],"a":"E26-T06-35-37.mp3"},{"ns":[38,40],"script":[["M","Polina, congratulations on being voted Nurse of the Year for our hospital. You really deserve the honor!","Polina, chúc mừng bạn được bình chọn là Y tá của Năm tại bệnh viện chúng ta. Bạn thực sự xứng đáng với vinh dự này!"],["W","Thanks! I'm a little embarrassed by all the attention, though.","Cảm ơn! Nhưng tôi hơi ngại với tất cả sự chú ý này."],["M","Well, you shouldn't be. After all, your patients and colleagues all felt you should be recognized for your outstanding efforts. Actually, I'm hoping you'll help me update the training materials for new nurses.","Ồ, bạn không nên thế. Sau tất cả, bệnh nhân và đồng nghiệp của bạn đều cảm thấy bạn nên được công nhận vì những nỗ lực xuất sắc. Thực ra, tôi hy vọng bạn sẽ giúp tôi cập nhật tài liệu đào tạo cho y tá mới."],["W","I'd be happy to help! And by the way, will you be at the awards ceremony next week? All the hospital's winners will be celebrated.","Tôi rất vui được giúp! Nhân tiện, bạn có tham dự lễ trao giải tuần sau không? Tất cả người thắng cuộc của bệnh viện sẽ được chúc mừng."],["M","Of course! I'm looking forward to it.","Tất nhiên! Tôi đang mong chờ đây."]],"qs":[{"n":38,"q":"What is the woman’s job?","qvi":"Công việc của người phụ nữ là gì?","opts":["School administrator","Reporter","Laboratory technician","Nurse"],"vi":["Quản lý trường học","Phóng viên","Kỹ thuật viên phòng thí nghiệm","Y tá"],"ans":"D"},{"n":39,"q":"What does the man ask the woman to help with?","qvi":"Người đàn ông yêu cầu người phụ nữ giúp gì?","opts":["Updating training materials","Recording an interview","Ordering some supplies","Designing a Web page"],"vi":["Cập nhật tài liệu đào tạo","Ghi âm phỏng vấn","Đặt hàng một số vật tư","Thiết kế trang web"],"ans":"A"},{"n":40,"q":"What will take place next week?","qvi":"Chuyện gì sẽ diễn ra tuần sau?","opts":["A press conference","An awards ceremony","A facility inspection","A board meeting"],"vi":["Họp báo","Lễ trao giải","Kiểm tra cơ sở vật chất","Họp hội đồng"],"ans":"B"}],"a":"E26-T06-38-40.mp3"},{"ns":[41,43],"script":[["M1","Hello. I'm looking for a book that's listed in your library's catalog, but I can't find it on the shelves. Could you help me?","Xin chào. Tôi đang tìm một cuốn sách được liệt kê trong danh mục thư viện của quý vị, nhưng không tìm thấy trên kệ. Quý vị có thể giúp không?"],["W","Sorry, I'm helping another patron on the phone right now. Let me get one of my coworkers for you.","Xin lỗi, tôi đang giúp một khách khác qua điện thoại. Để tôi gọi một đồng nghiệp cho anh."],["M2","Hi. How can I help you?","Chào. Tôi có thể giúp gì?"],["M1","I'm looking for a book about abstract art called Night Canvases.","Tôi đang tìm sách về nghệ thuật trừu tượng tên Night Canvases."],["M2","Oh! We just received several copies of that, but they're still packed in the box. If you come back tomorrow, they'll be ready to borrow.","Ồ! Chúng tôi vừa nhận vài bản sao, nhưng vẫn còn trong hộp. Nếu anh quay lại ngày mai, chúng sẽ sẵn sàng để mượn."]],"qs":[{"n":41,"q":"Where most likely are the speakers?","qvi":"Những người nói có lẽ đang ở đâu?","opts":["At a café","At a museum","At a public library","At a community center"],"vi":["Tại quán cà phê","Tại bảo tàng","Tại thư viện công cộng","Tại trung tâm cộng đồng"],"ans":"C"},{"n":42,"q":"Why is the woman unable to help?","qvi":"Tại sao người phụ nữ không giúp được?","opts":["She is new to the job.","She is busy with another task.","She needs to attend a workshop.","She will be leaving for the day."],"vi":["Cô ấy mới vào làm.","Cô ấy đang bận việc khác.","Cô ấy cần tham dự hội thảo.","Cô ấy sắp về."],"ans":"B"},{"n":43,"q":"Why is an item unavailable?","qvi":"Tại sao món hàng không sẵn sàng?","opts":["It is sold out.","It has not been unpacked yet.","A shipment has been lost.","A repair has not been made yet."],"vi":["Đã bán hết.","Chưa được mở hộp.","Lô hàng bị mất.","Chưa được sửa."],"ans":"B"}],"a":"E26-T06-41-43.mp3"},{"ns":[44,46],"script":[["M","Silvia, I just heard the city mayor will hold a press conference this afternoon. Can you cover it? I'll be at the opening of the new train station.","Silvia, tôi vừa nghe thị trưởng sẽ tổ chức họp báo chiều nay. Bạn có thể đưa tin không? Tôi sẽ ở lễ khai trương ga tàu mới."],["W","OK, I'll get a camera crew together right away. I hope the mayor will provide details about the proposal to build an offshore wind farm.","OK, tôi sẽ tập hợp đội quay phim ngay. Hy vọng thị trưởng sẽ cung cấp chi tiết về đề xuất xây dựng trang trại gió ngoài khơi."],["M","Yes, that's what I heard he'll discuss. There's a lot of interest in wind energy, so this will likely be the lead story on tonight's news.","Vâng, tôi nghe ông ấy sẽ thảo luận về đó. Có nhiều quan tâm đến năng lượng gió, nên có lẽ đây sẽ là tin chính tối nay."],["W","Perfect. I'm going to ask the mayor about funding for the project. The city residents will want to know where the finances will come from.","Hoàn hảo. Tôi sẽ hỏi thị trưởng về nguồn tài trợ cho dự án. Dân cư thành phố sẽ muốn biết tiền từ đâu."]],"qs":[{"n":44,"q":"Who most likely are the speakers?","qvi":"Những người nói có lẽ là ai?","opts":["Repair technicians","News reporters","Business owners","Construction engineers"],"vi":["Kỹ thuật viên sửa chữa","Phóng viên tin tức","Chủ doanh nghiệp","Kỹ sư xây dựng"],"ans":"B"},{"n":45,"q":"What project is being proposed?","qvi":"Dự án nào đang được đề xuất?","opts":["A wind farm","A road expansion","A tourism initiative","A building expansion"],"vi":["Trang trại gió","Mở rộng đường","Sáng kiến du lịch","Mở rộng tòa nhà"],"ans":"A"},{"n":46,"q":"What does the woman plan to inquire about?","qvi":"Người phụ nữ dự định hỏi về gì?","opts":["Architectural specifications","Staffing arrangements","A funding source","A project timeline"],"vi":["Đặc tả kiến trúc","Sắp xếp nhân sự","Nguồn tài trợ","Lịch trình dự án"],"ans":"C"}],"a":"E26-T06-44-46.mp3"},{"ns":[47,49],"script":[["W","Koji, you weren't at the team meeting this morning. Is everything OK?","Koji, anh không ở cuộc họp đội sáng nay. Mọi thứ ổn chứ?"],["M","I had to take my car to the mechanic for repairs. What did I miss?","Tôi phải đưa xe đến thợ sửa. Tôi bỏ lỡ gì?"],["W","Well, we received some good news. Our firm is planning to hire more accountants!","Ồ, chúng ta nhận tin tốt. Công ty dự định thuê thêm kế toán!"],["M","That's great! We've been busier than ever since we started working with True Valley Industries.","Hay quá! Chúng ta bận rộn hơn bao giờ hết kể từ khi làm việc với True Valley Industries."],["W","Yes. By the way, there's an article on our Web site about the founder of True Valley. I'd suggest reading it.","Vâng. Nhân tiện, có bài báo trên web về người sáng lập True Valley. Tôi khuyên nên đọc."],["M","I'll be sure to check it out.","Tôi chắc chắn sẽ kiểm tra."]],"qs":[{"n":47,"q":"Why did the man miss a meeting?","qvi":"Tại sao người đàn ông bỏ lỡ cuộc họp?","opts":["His train was late.","His car was being repaired.","He had a medical appointment.","He was meeting with some clients."],"vi":["Tàu muộn.","Xe đang sửa.","Có hẹn khám bệnh.","Đang gặp khách."],"ans":"B"},{"n":48,"q":"What good news does the woman mention?","qvi":"Tin tốt nào người phụ nữ đề cập?","opts":["More employees will be hired.","A facility will be remodeled.","Some equipment will be upgraded.","A permit has been approved."],"vi":["Thuê thêm nhân viên.","Cải tạo cơ sở.","Nâng cấp thiết bị.","Phê duyệt giấy phép."],"ans":"A"},{"n":49,"q":"What does the man say he will do?","qvi":"Người đàn ông nói sẽ làm gì?","opts":["Speak to a manager","Present at a conference","Read an article","Sign up for a training course"],"vi":["Nói với quản lý.","Trình bày hội nghị.","Đọc bài báo.","Đăng ký khóa đào tạo."],"ans":"C"}],"a":"E26-T06-47-49.mp3"},{"ns":[50,52],"script":[["W1","Let's discuss the upcoming retreat for the architects at our firm. How's the planning going, Hongtai and Raya?","Hãy thảo luận về chuyến dã ngoại sắp tới cho các kiến trúc sư tại công ty chúng ta. Việc lập kế hoạch thế nào rồi, Hongtai và Raya?"],["M","Well, the Evans Nature Reserve said they can organize a two-day expedition for us.","Ừm, Khu bảo tồn Thiên nhiên Evans nói họ có thể tổ chức chuyến thám hiểm hai ngày cho chúng ta."],["W2","Yes, they're even offering a wildlife photography workshop on the second day. I'm excited about that.","Vâng, họ thậm chí còn cung cấp hội thảo nhiếp ảnh động vật hoang dã vào ngày thứ hai. Tôi rất hào hứng về điều đó."],["W1","Oh, that is exciting! Do you know if we'll be able to camp in the reserve overnight?","Ồ, nghe thú vị đấy! Bạn có biết chúng ta có thể cắm trại qua đêm trong khu bảo tồn không?"],["M","Yes, that's an option. But I don't know if all our staff have tents and camping equipment. I'm sure we can rent enough for everybody, though. Let me look into it.","Có, đó là lựa chọn. Nhưng tôi không biết liệu tất cả nhân viên có lều và thiết bị cắm trại không. Dù sao, tôi chắc chúng ta có thể thuê đủ cho mọi người. Để tôi kiểm tra."]],"qs":[{"n":50,"q":"What are the speakers planning?","qvi":"Hai người đang lên kế hoạch cho việc gì?","opts":["A company retreat","An industry conference","A retirement party","A grand opening celebration"],"vi":["Chuyến đi nghỉ của công ty","Hội nghị ngành","Tiệc hưu trí","Lễ khai trương lớn"],"ans":"A"},{"n":51,"q":"What are the women excited about?","qvi":"Những người phụ nữ hào hứng về điều gì?","opts":["Traveling to a new city","Giving a product demonstration","Meeting a guest speaker","Attending a workshop"],"vi":["Đi đến một thành phố mới","Trình diễn sản phẩm","Gặp diễn giả khách mời","Tham dự hội thảo"],"ans":"D"},{"n":52,"q":"What will the man research?","qvi":"Người đàn ông sẽ tìm hiểu điều gì?","opts":["Driving directions","Weather conditions","Equipment rentals","Dining options"],"vi":["Đường đi","Thời tiết","Thuê thiết bị","Quán ăn"],"ans":"C"}],"a":"E26-T06-50-52.mp3"},{"ns":[53,55],"script":[["M","Hi, Ms. Espinoza. This is Malik calling from ACC Internet Providers. I'm here at your residence at 88 Glassbury Avenue to set up your Internet.","Chào bà Espinoza. Tôi là Malik từ ACC Internet Providers. Tôi đang ở nhà bà tại 88 Glassbury Avenue để lắp đặt internet."],["W","Oh! I'm sorry, but I'm still on my way home from work. There's a lot of traffic right now.","Ồ! Xin lỗi, nhưng tôi vẫn đang trên đường về nhà từ chỗ làm. Lúc này giao thông rất đông."],["M","I see. Well, my next client's house isn't too far away. I could be back in about an hour. Does that sound OK?","Tôi hiểu rồi. Ừm, nhà khách hàng tiếp theo của tôi không xa lắm. Tôi có thể quay lại sau khoảng một giờ. Nghe ổn chứ?"],["W","Yes, that'd be great. Thank you so much.","Vâng, thế thì tốt quá. Cảm ơn rất nhiều."]],"qs":[{"n":53,"q":"Who most likely is the man?","qvi":"Người đàn ông có khả năng là ai?","opts":["A service technician","A salesperson","A delivery driver","A real estate agent"],"vi":["Kỹ thuật viên dịch vụ","Nhân viên bán hàng","Tài xế giao hàng","Môi giới bất động sản"],"ans":"A"},{"n":54,"q":"Why does the woman say, “There’s a lot of traffic right now”?","qvi":"Tại sao người phụ nữ nói: “Bây giờ đang rất đông xe”?","opts":["To request time off work","To explain a delay","To disagree with a plan","To recommend another route"],"vi":["Xin nghỉ phép","Giải thích sự chậm trễ","Không đồng ý với kế hoạch","Gợi ý đi đường khác"],"ans":"B"},{"n":55,"q":"What will the man most likely do next?","qvi":"Người đàn ông có khả năng sẽ làm gì tiếp theo?","opts":["Listen to a news report","Go to another client’s home","Cancel an Internet subscription","Consult a handbook"],"vi":["Nghe bản tin","Đến nhà khách hàng khác","Hủy gói Internet","Tham khảo sổ tay"],"ans":"B"}],"a":"E26-T06-53-55.mp3"},{"ns":[56,58],"script":[["W","Klaus, you were on the research team that went to the Arctic last month, right? For the new project?","Klaus, anh là thành viên đội nghiên cứu đến Bắc Cực tháng trước phải không? Cho dự án mới?"],["M","Yes, I'll be going again next month. Are you joining?","Vâng, tôi sẽ đi lại tháng sau. Bạn tham gia à?"],["W","Yeah—Sabine can't make it, so the project coordinator asked me to take her place.","Vâng—Sabine không đi được, nên điều phối viên dự án yêu cầu tôi thay thế."],["M","Great, but prepare for the freezing temperatures! I'd recommend getting a heated jacket. The one I have is battery-operated, and there are heating elements inside the fabric. I'll send you a link to the online store. The jacket didn't cost too much.","Hay đấy, nhưng hãy chuẩn bị cho nhiệt độ lạnh giá! Tôi khuyên nên mua áo khoác sưởi ấm. Cái tôi có dùng pin, và có các yếu tố sưởi ấm bên trong vải. Tôi sẽ gửi link cửa hàng trực tuyến. Áo không đắt lắm đâu."]],"qs":[{"n":56,"q":"What did the man do last month?","qvi":"Người đàn ông đã làm gì tháng trước?","opts":["He managed a trade show booth.","He attended a company picnic.","He participated in a research project.","He met with overseas clients."],"vi":["Quản lý gian hàng triển lãm","Dự tiệc công ty","Tham gia dự án nghiên cứu","Gặp khách nước ngoài"],"ans":"C"},{"n":57,"q":"Why will the woman be joining the man next month?","qvi":"Vì sao người phụ nữ sẽ đi cùng người đàn ông vào tháng tới?","opts":["Her job title has changed.","Her colleague is unavailable.","She has more experience than the man.","She will be needed to translate documents."],"vi":["Chức vụ thay đổi","Đồng nghiệp cô ấy bận","Cô có kinh nghiệm hơn","Cần dịch tài liệu"],"ans":"B"},{"n":58,"q":"What will the man send the woman a link to?","qvi":"Người đàn ông sẽ gửi liên kết gì cho cô ấy?","opts":["An itinerary","A magazine article","An online store","A list of hotels"],"vi":["Lịch trình","Bài báo","Cửa hàng trực tuyến","Danh sách khách sạn"],"ans":"C"}],"a":"E26-T06-56-58.mp3"},{"ns":[59,61],"script":[["W","We just got a rush order from Great Fitness. They need T-shirts with their business name and logo printed on the front—1,000, to be exact.","Chúng ta vừa nhận đơn hàng gấp từ Great Fitness. Họ cần áo thun in tên và logo công ty ở mặt trước—chính xác 1.000 cái."],["M","That's an unusually large order.","Đó là đơn hàng lớn bất thường."],["W","We're definitely going to need some employees to work overtime on it.","Chúng ta chắc chắn cần một số nhân viên làm thêm giờ cho nó."],["M","Hmm, I don't know how easy that's going to be. It's the summer, and a lot of employees were hoping to take time off.","Ừm, tôi không biết sẽ dễ dàng thế nào. Giờ là hè, và nhiều nhân viên hy vọng nghỉ phép."],["W","Well, OK. We could offer them an additional day off next month.","Ừm, OK. Chúng ta có thể cho họ thêm một ngày nghỉ tháng sau."],["M","I'm still worried about the three other orders we need to complete this week.","Tôi vẫn lo về ba đơn hàng khác cần hoàn thành tuần này."],["W","I know, but Great Fitness orders from us all the time.","Tôi biết, nhưng Great Fitness luôn đặt hàng từ chúng ta."]],"qs":[{"n":59,"q":"What type of product are the speakers discussing?","qvi":"Hai người đang bàn về loại sản phẩm nào?","opts":["T-shirts","Stickers","Water bottles","Tote bags"],"vi":["Áo thun","Sticker","Bình nước","Túi vải"],"ans":"A"},{"n":60,"q":"What does the woman propose offering to some employees?","qvi":"Người phụ nữ đề xuất tặng gì cho một số nhân viên?","opts":["A gym membership","A restaurant voucher","A salary bonus","An extra vacation day"],"vi":["Thẻ tập gym","Phiếu ăn nhà hàng","Thưởng lương","Thêm ngày nghỉ"],"ans":"D"},{"n":61,"q":"What does the woman mean when she says, “Great Fitness orders from us all the time”?","qvi":"Ý người phụ nữ khi nói: “Great Fitness đặt hàng của mình suốt ấy mà”?","opts":["An invoice contains an error.","More staff should be hired.","Great Fitness’s order is the priority.","Great Fitness has complained about a delivery."],"vi":["Hóa đơn sai","Cần tuyển thêm người","Xử lý đơn của Great Fitness trước","Great Fitness phàn nàn về giao hàng"],"ans":"C"}],"a":"E26-T06-59-61.mp3"},{"ns":[62,64],"script":[["M","I'm looking forward to our anniversary banquet, Shreya. It's hard to believe we've been in business for ten years!","Tôi mong chờ buổi tiệc kỷ niệm, Shreya. Khó tin là chúng ta kinh doanh được mười năm rồi!"],["W","I know. I was looking through old company photos last night. I found some from when we had just started and were a team of only three people.","Tôi biết. Tối qua tôi xem qua ảnh công ty cũ. Tôi tìm thấy vài cái từ khi chúng ta mới bắt đầu và chỉ có đội ba người."],["M","Wow. Those would be great to use for our slideshow during the welcome speech.","Ồ. Những cái đó sẽ tuyệt để dùng cho slideshow trong lời chào mừng."],["W","I agree. And by the way, since I'll be getting up a few times to make announcements, I'd like to sit at the table closest to the stage.","Đồng ý. Nhân tiện, vì tôi sẽ đứng dậy vài lần để thông báo, tôi muốn ngồi bàn gần sân khấu nhất."],["M","I'll make sure to reserve a seat for you there.","Tôi sẽ đảm bảo giữ chỗ cho bạn ở đó."]],"qs":[{"n":62,"q":"Why is the company hosting a banquet?","qvi":"Tại sao công ty tổ chức buổi tiệc?","opts":["To open a new facility","To celebrate an anniversary","To announce a merger","To honor a retiring colleague"],"vi":["Khai trương cơ sở mới","Kỷ niệm ngày thành lập","Công bố sáp nhập","Vinh danh đồng nghiệp nghỉ hưu"],"ans":"B"},{"n":63,"q":"What does the man say should be included in a presentation?","qvi":"Người đàn ông nói bản thuyết trình nên gồm gì?","opts":["A summary of a company’s profits","A preview of a company’s new product","Some survey results","Some photographs"],"vi":["Tóm tắt lợi nhuận công ty","Giới thiệu sản phẩm mới","Một số kết quả khảo sát","Một vài ảnh"],"ans":"D"},{"n":64,"q":"Look at the graphic. Where will the woman be seated?","qvi":"Nhìn vào sơ đồ. Người phụ nữ sẽ ngồi ở đâu?","opts":["Table 1","Table 2","Table 3","Table 4"],"vi":["Bàn 1","Bàn 2","Bàn 3","Bàn 4"],"ans":"B"}],"a":"E26-T06-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["W","Thank you for holding. This is Bianca. How can I help you?","Cảm ơn đã chờ. Tôi là Bianca. Tôi có thể giúp gì?"],["M","Hi. I have a ticket for the bus to Springdale this morning, but my plans have changed and I need to switch my destination.","Chào. Tôi có vé xe buýt đến Springdale sáng nay, nhưng kế hoạch thay đổi và tôi cần đổi điểm đến."],["W","Sure. I can help you with that.","Chắc chắn. Tôi có thể giúp."],["M","Thanks very much. I need the bus to Centerton instead.","Cảm ơn nhiều. Tôi cần xe đến Centerton thay vì vậy."],["W","No problem. If you purchased your bus ticket electronically, I just need your confirmation number.","Không vấn đề. Nếu bạn mua vé xe buýt điện tử, tôi chỉ cần số xác nhận."],["M","OK, let me just find the e-mail that has it.","OK, để tôi tìm email có nó."]],"qs":[{"n":65,"q":"Where does the woman most likely work?","qvi":"Người phụ nữ có khả năng làm việc ở đâu?","opts":["At a bus station","At a train station","At a ferry terminal","At an airport"],"vi":["Trạm xe buýt","Ga tàu","Bến phà","Sân bay"],"ans":"A"},{"n":66,"q":"Look at the graphic. What is the man’s new departure time?","qvi":"Nhìn vào bảng. Giờ khởi hành mới của người đàn ông là mấy giờ?","opts":["10:34 A.M.","10:57 A.M.","11:15 A.M.","11:41 A.M."],"vi":["10:34 sáng","10:57 sáng","11:15 sáng","11:41 sáng"],"ans":"C"},{"n":67,"q":"What does the woman ask the man for?","qvi":"Người phụ nữ hỏi người đàn ông điều gì?","opts":["His date of travel","His seat preference","A form of payment","A confirmation number"],"vi":["Ngày đi","Ghế ngồi ưu tiên","Hình thức thanh toán","Mã xác nhận"],"ans":"D"}],"a":"E26-T06-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Henderson's Electricians. How can I help you?","Henderson's Electricians. Tôi có thể giúp gì?"],["W","Hello. I'm calling because I purchased a clothes dryer a few days ago. But I have a problem. I'm not sure if my home's electric system can support it.","Chào. Tôi gọi vì tôi mua máy sấy quần áo vài ngày trước. Nhưng có vấn đề. Tôi không chắc hệ thống điện nhà tôi có hỗ trợ không."],["M","Well, let's see. Could you take a look at your electric panel? There should be a series of switches on it.","Ừm, để xem. Bà có thể xem bảng điện không? Nên có loạt công tắc trên đó."],["W","Sure. Hold on. OK. I'm looking at it.","Chắc chắn. Chờ chút. OK. Tôi đang xem."],["M","OK. Do you see any unused spaces where additional switches could be installed?","OK. Bà có thấy không gian chưa dùng nào để lắp công tắc thêm không?"],["W","Just one.","Chỉ một."],["M","I see. Well, a clothes dryer requires two spaces. So most likely, we'd need to install something called a subpanel. The good news is that you'd only need a 60-amp electrical switch to fix the problem.","Tôi hiểu. Ừm, máy sấy quần áo cần hai không gian. Nên có lẽ cần lắp bảng phụ. Tin tốt là bà chỉ cần công tắc điện 60-amp để sửa vấn đề."]],"qs":[{"n":68,"q":"What has the woman recently purchased?","qvi":"Người phụ nữ mới mua gì gần đây?","opts":["A dishwasher","A toaster oven","A refrigerator","A clothes dryer"],"vi":["Máy rửa chén","Lò nướng nhỏ","Tủ lạnh","Máy sấy quần áo"],"ans":"D"},{"n":69,"q":"What does the man ask the woman to do?","qvi":"Người đàn ông nhờ người phụ nữ làm gì?","opts":["Check a warranty","Visit a Web site","Examine some equipment","Take some photographs"],"vi":["Kiểm tra bảo hành","Truy cập trang Web","Kiểm tra thiết bị","Chụp một số ảnh"],"ans":"C"},{"n":70,"q":"Look at the graphic. How much will the woman probably pay for an electrical switch?","qvi":"Nhìn vào bảng. Cô ấy có khả năng trả bao nhiêu cho công tắc điện?","opts":["$25","$30","$38","$46"],"vi":["$25","$30","$38","$46"],"ans":"A"}],"a":"E26-T06-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Good morning, and welcome to the Third Annual Robotics Trade Show. Please note that in order to accommodate the large number of guests who signed up for the afternoon panel discussion, that event has been moved to Exhibit Hall B. That's on the lower level, to the left of the elevators. And will the person who left a backpack at the information desk please return to the desk to claim your item? It's a silver Rugged Hiker model with a blue strap.","Chào buổi sáng và chào mừng quý vị đến với Triển lãm Thương mại Robot thường niên lần thứ ba. Xin lưu ý rằng để đáp ứng số lượng lớn khách đã đăng ký tham gia buổi thảo luận chuyên đề vào buổi chiều, sự kiện đó đã được chuyển sang Phòng trưng bày B. Phòng này nằm ở tầng dưới, bên trái thang máy. Và xin người đã để quên một chiếc ba lô tại quầy thông tin quay lại quầy để nhận lại đồ của mình. Đó là một chiếc ba lô hiệu Rugged Hiker màu bạc với dây đeo màu xanh."]],"qs":[{"n":71,"q":"Where most likely is the announcement being made?","qvi":"Thông báo khả năng được phát ở đâu?","opts":["At an art gallery","At a trade show","At a shopping mall","At a sporting event"],"vi":["Phòng trưng bày nghệ thuật","Hội chợ thương mại","Trung tâm mua sắm","Sự kiện thể thao"],"ans":"B"},{"n":72,"q":"What does the speaker say has changed?","qvi":"Người nói cho biết điều gì đã thay đổi?","opts":["Opening hours","A location","An entry fee","A policy"],"vi":["Giờ mở cửa","Địa điểm","Phí vào cửa","Chính sách"],"ans":"B","note":"File đáp án của sách ghi (D), nhưng lời thoại cho thấy đáp án đúng là (B); web chấm theo (B)."},{"n":73,"q":"What does the speaker say is available at the information desk?","qvi":"Người nói cho biết bàn thông tin có gì?","opts":["A discount coupon","A parking pass","A lost item","A map"],"vi":["Phiếu giảm giá","Thẻ đỗ xe","Đồ thất lạc","Bản đồ"],"ans":"C"}],"a":"E26-T06-71-73.mp3"},{"ns":[74,76],"script":[["","Welcome to this course about computer programming. I'm Jin-Ah Jeong. Unfortunately, the regular instructor, Mr. Ramirez, is sick today, so I'll be filling in. Although I've never taught this course before, I've been a computer programmer for seven years. Now, to begin, let's go over some terms that are often used in the field of computer programming. I'll write them on the board—if you know any of their meanings, please raise your hand and I'll call on you.","Chào mừng các bạn đến với khóa học về lập trình máy tính. Tôi là Jin-Ah Jeong. Rất tiếc, giảng viên chính là ông Ramirez hôm nay bị ốm nên tôi sẽ dạy thay. Mặc dù tôi chưa từng dạy khóa học này trước đây, nhưng tôi đã làm lập trình viên máy tính được bảy năm. Bây giờ, để bắt đầu, chúng ta sẽ xem qua một số thuật ngữ thường được sử dụng trong lĩnh vực lập trình máy tính. Tôi sẽ viết chúng lên bảng — nếu bạn biết nghĩa của thuật ngữ nào, hãy giơ tay và tôi sẽ gọi bạn."]],"qs":[{"n":74,"q":"Who most likely are the listeners?","qvi":"Người nghe có khả năng là ai?","opts":["Students","Professional athletes","Business investors","News reporters"],"vi":["Sinh viên","Vận động viên chuyên nghiệp","Nhà đầu tư","Phóng viên"],"ans":"A"},{"n":75,"q":"Why does the speaker say, “I’ve been a computer programmer for seven years”?","qvi":"Người nói nói: “Tôi là lập trình viên 7 năm rồi” để làm gì?","opts":["To indicate that she is well qualified for a role","To express appreciation for her employer","To correct some inaccurate information","To give a reason for a change in profession"],"vi":["Chứng minh bản thân đủ năng lực","Thể hiện sự trân trọng công ty","Sửa thông tin chưa chính xác","Giải thích lý do đổi nghề"],"ans":"A"},{"n":76,"q":"According to the speaker, why should the listeners raise their hands?","qvi":"Theo người nói, tại sao người nghe nên giơ tay?","opts":["To make a suggestion","To request a booklet","To provide a definition","To ask a question"],"vi":["Đưa ra gợi ý","Xin tài liệu","Đưa định nghĩa","Đặt câu hỏi"],"ans":"C"}],"a":"E26-T06-74-76.mp3"},{"ns":[77,79],"script":[["","Hi, Min-Jee. This is Anil Gupta from Jeremy's Family Restaurants calling about the application you sent in. I was very impressed with your résumé and your successful completion of the managerial training program when you worked at Harry's Bistros. I understand the program included training in using bookkeeping software. That would be useful in our company. Also, your supervisor at Harry's spoke very highly of your performance as a manager. So, I hope you haven't accepted any offers yet! Please call me at your earliest convenience at 555-0187.","Chào Min-Jee. Tôi là Anil Gupta từ chuỗi nhà hàng gia đình Jeremy’s, gọi điện liên quan đến đơn xin việc bạn đã gửi. Tôi rất ấn tượng với sơ yếu lý lịch của bạn và việc bạn hoàn thành xuất sắc chương trình đào tạo quản lý khi làm việc tại Harry’s Bistros. Tôi được biết chương trình đó bao gồm đào tạo sử dụng phần mềm kế toán, điều này sẽ rất hữu ích cho công ty chúng tôi. Ngoài ra, người giám sát của bạn tại Harry’s cũng đánh giá rất cao năng lực làm việc của bạn với tư cách là quản lý. Vì vậy, tôi hy vọng bạn vẫn chưa nhận lời mời làm việc nào! Vui lòng gọi lại cho tôi sớm nhất có thể theo số 555-0187."]],"qs":[{"n":77,"q":"What industry does the speaker work in?","qvi":"Người nói làm trong ngành nào?","opts":["Technology","Travel","Agriculture","Food service"],"vi":["Công nghệ","Du lịch","Nông nghiệp","Dịch vụ ăn uống"],"ans":"D"},{"n":78,"q":"According to the speaker, what would be useful?","qvi":"Theo người nói, điều gì sẽ hữu ích?","opts":["Knowledge of specialized software","An understanding of consumer trends","Customer-service training","Team-building skills"],"vi":["Biết phần mềm chuyên dụng","Hiểu xu hướng tiêu dùng","Đào tạo dịch vụ khách hàng","Kỹ năng làm việc nhóm"],"ans":"A"},{"n":79,"q":"What does the speaker imply when he says, “I hope you haven’t accepted any offers yet”?","qvi":"Người nói ám chỉ điều gì khi nói: “Hy vọng bạn chưa nhận lời chỗ nào”?","opts":["He thinks the listener deserves a promotion.","He would like to hire the listener.","A company would not be good to work for.","A salary offer is too low."],"vi":["Nghĩ người nghe xứng đáng thăng chức","Muốn tuyển người nghe","Công ty kia không tốt","Mức lương họ đưa ra quá thấp"],"ans":"B"}],"a":"E26-T06-77-79.mp3"},{"ns":[80,82],"script":[["","Welcome to another segment of Belmack City Business News. Belmack City has one of the biggest ports in the country. The port receives and distributes thousands of containers full of cargo each day. Goods from the ships are usually distributed throughout the region by train or by truck. However, sometimes the goods need to wait for days before they are transported, which can cause problems due to lack of affordable storage space. Unfortunately, lease costs for storage space in the area are too high for many shipping companies to afford. After the break, we'll hear from Pablo Alvarez, owner of Alva Shipping, about this issue. So stay tuned!","Chào mừng quý vị đến với một chuyên mục khác của Bản tin Kinh doanh Thành phố Belmack. Thành phố Belmack có một trong những cảng lớn nhất cả nước. Mỗi ngày, cảng tiếp nhận và phân phối hàng nghìn container chứa hàng hóa. Hàng từ các con tàu thường được vận chuyển khắp khu vực bằng tàu hỏa hoặc xe tải. Tuy nhiên, đôi khi hàng hóa phải chờ nhiều ngày trước khi được vận chuyển, điều này có thể gây ra vấn đề do thiếu không gian lưu trữ với chi phí hợp lý. Đáng tiếc là chi phí thuê kho bãi trong khu vực quá cao đối với nhiều công ty vận tải. Sau giờ giải lao, chúng ta sẽ nghe ý kiến của ông Pablo Alvarez, chủ công ty Alva Shipping, về vấn đề này. Hãy tiếp tục theo dõi nhé!"]],"qs":[{"n":80,"q":"What is the news segment about?","qvi":"Bản tin nói về điều gì?","opts":["The restoration of historic ships","The distribution of goods","A shortage of city housing","The construction of a new port"],"vi":["Khôi phục tàu cổ","Phân phối hàng hóa","Thiếu nhà ở thành phố","Xây cảng mới"],"ans":"B"},{"n":81,"q":"What problem does the speaker mention?","qvi":"Người nói đề cập vấn đề gì?","opts":["Storage space is not affordable.","Trained workers are difficult to find.","There is a shortage of supplies.","Poor road conditions are causing delays."],"vi":["Chi phí kho bãi cao","Khó tìm nhân công tay nghề","Thiếu nguồn cung","Đường xá kém gây chậm trễ"],"ans":"A"},{"n":82,"q":"Who is Pablo Alvarez?","qvi":"Pablo Alvarez là ai?","opts":["A real estate agent","A city official","A business owner","An accountant"],"vi":["Môi giới nhà đất","Quan chức thành phố","Chủ doanh nghiệp","Kế toán"],"ans":"C"}],"a":"E26-T06-80-82.mp3"},{"ns":[83,85],"script":[["","Welcome. I'm delighted to be leading another outdoor workshop here in the botanical gardens. The paintings that participants produced last time were extraordinary—there's nothing like being surrounded by flowers to inspire creativity. Now, remember that your participation fee does include a light lunch. I see you've all found spots to set up your easels and you all have your own canvas and paints. That's perfect, since we don't provide painting supplies. Before we get started, let's take a moment to have everyone tell us their names and why they signed up.","Chào mừng mọi người. Tôi rất vui được dẫn dắt một buổi hội thảo ngoài trời nữa tại khu vườn thực vật này. Những bức tranh mà các học viên thực hiện trong lần trước thật sự rất xuất sắc — không gì tuyệt vời hơn việc được bao quanh bởi hoa lá để khơi nguồn sáng tạo. Bây giờ, xin nhắc lại rằng phí tham gia của các bạn đã bao gồm một bữa ăn trưa nhẹ. Tôi thấy mọi người đã tìm được chỗ để dựng giá vẽ và ai cũng có sẵn toan và màu vẽ của riêng mình. Điều đó rất tốt vì chúng tôi không cung cấp dụng cụ vẽ. Trước khi bắt đầu, hãy dành một chút thời gian để mỗi người giới thiệu tên mình và lý do đăng ký tham gia."]],"qs":[{"n":83,"q":"What is the focus of the workshop?","qvi":"Nội dung chính của buổi workshop là gì?","opts":["Flower arranging","Photography","Painting","Creative writing"],"vi":["Cắm hoa","Nhiếp ảnh","Vẽ tranh","Viết sáng tạo"],"ans":"C"},{"n":84,"q":"What does the speaker say is included in a workshop fee?","qvi":"Phí workshop bao gồm gì?","opts":["A museum membership","A potted plant","Some supplies","A meal"],"vi":["Thẻ thành viên bảo tàng","Cây cảnh","Dụng cụ","Suất ăn"],"ans":"D"},{"n":85,"q":"What will most likely happen next?","qvi":"Điều gì có khả năng xảy ra tiếp theo?","opts":["The listeners will sign some forms.","The listeners will introduce themselves.","The speaker will give a demonstration.","The speaker will lead a tour."],"vi":["Người nghe ký giấy tờ","Người nghe giới thiệu bản thân","Người nói làm demo","Người nói dẫn đi tham quan"],"ans":"B"}],"a":"E26-T06-83-85.mp3"},{"ns":[86,88],"script":[["","Currently, you’re all working on our design project for Takanashi Systems. They like the suggestions you’ve made so far, such as how to update their logo to make it more modern. That’s welcome news because they have high standards. They mentioned they’ll be in the area this Friday and expressed interest in visiting our office, so I’ve invited them. But as I was walking by the workstation area, I noticed a lot of clutter. Please remember that making a good impression is important.","Hiện tại, tất cả các bạn đang làm việc trong dự án thiết kế của chúng ta cho công ty Takanashi Systems. Họ rất thích những đề xuất mà các bạn đã đưa ra cho đến nay, chẳng hạn như cách cập nhật logo của họ để trông hiện đại hơn. Đây là một tin vui vì họ có tiêu chuẩn rất cao. Họ cho biết sẽ có mặt trong khu vực này vào thứ Sáu tuần này và bày tỏ mong muốn được đến thăm văn phòng của chúng ta, nên tôi đã mời họ. Tuy nhiên, khi đi ngang qua khu vực làm việc, tôi nhận thấy có khá nhiều đồ đạc bừa bộn. Xin hãy nhớ rằng việc tạo ấn tượng tốt là rất quan trọng."]],"qs":[{"n":86,"q":"What service does the company provide?","qvi":"Công ty cung cấp dịch vụ gì?","opts":["Legal","Architectural","Graphic design","Artificial intelligence"],"vi":["Pháp lý","Kiến trúc","Thiết kế đồ họa","Trí tuệ nhân tạo"],"ans":"C"},{"n":87,"q":"What does the speaker say about Friday?","qvi":"Người nói nói gì về thứ Sáu?","opts":["A client will visit.","Interviews will be conducted.","An office will close early.","Bonuses will be announced."],"vi":["Có khách đến thăm","Tổ chức phỏng vấn","Văn phòng đóng sớm","Công bố thưởng"],"ans":"A"},{"n":88,"q":"What does the speaker imply when she says, “making a good impression is important”?","qvi":"Người nói ám chỉ gì khi nói: “tạo ấn tượng tốt rất quan trọng”?","opts":["She will be providing her business card.","She does not want employees to be late.","She expects workstations to be clean.","She is unsatisfied with some potential job candidates."],"vi":["Cô sẽ đưa danh thiếp","Không muốn nhân viên đi trễ","Mong không gian làm việc sạch sẽ","Chưa hài lòng một số ứng viên"],"ans":"C"}],"a":"E26-T06-86-88.mp3"},{"ns":[89,91],"script":[["","Good morning, everyone. I appreciate you all getting here early before your assembly-line shift starts. I have a major announcement to make. Remember our new injection mold machine was acting up yesterday? A technician came at the end of the day, and it turns out the hydraulic safety switch is turning itself off randomly. A part needs to be replaced, but that won’t happen until later this week. In the meantime, please use our older machine only, which, as you know, is not as fast as the new one. I’ll need you to start working as soon as possible.","Chào buổi sáng, mọi người. Tôi rất cảm kích vì tất cả đã đến sớm trước khi ca làm việc trên dây chuyền lắp ráp bắt đầu. Tôi có một thông báo quan trọng. Mọi người còn nhớ chiếc máy ép khuôn mới của chúng ta hôm qua bị trục trặc không? Một kỹ thuật viên đã đến vào cuối ngày và phát hiện rằng công tắc an toàn thủy lực tự động tắt một cách ngẫu nhiên. Một bộ phận cần được thay thế, nhưng việc đó sẽ chưa thể thực hiện cho đến cuối tuần này. Trong thời gian chờ đợi, xin vui lòng chỉ sử dụng máy cũ của chúng ta, máy này như các bạn đã biết là không nhanh bằng máy mới. Tôi cần mọi người bắt đầu làm việc càng sớm càng tốt."]],"qs":[{"n":89,"q":"Where do the listeners most likely work?","qvi":"Người nghe có khả năng làm việc ở đâu?","opts":["At a hospital","At a factory","At a bank","At an auto repair shop"],"vi":["Bệnh viện","Nhà máy","Ngân hàng","Tiệm sửa xe"],"ans":"B"},{"n":90,"q":"Who visited the business yesterday?","qvi":"Ai đã đến cơ sở kinh doanh hôm qua?","opts":["A journalist","A safety inspector","A politician","A repair person"],"vi":["Nhà báo","Thanh tra an toàn","Chính trị gia","Nhân viên sửa chữa"],"ans":"D"},{"n":91,"q":"Why are the listeners asked to start working right away?","qvi":"Tại sao người nghe được yêu cầu làm việc ngay?","opts":["A large order was placed.","Several employees are on vacation.","A task will take longer than usual.","An inspection will be conducted in the afternoon."],"vi":["Đơn hàng lớn","Nhiều nhân viên nghỉ phép","Công việc sẽ tốn nhiều thời gian","Buổi kiểm tra diễn ra chiều nay"],"ans":"C"}],"a":"E26-T06-89-91.mp3"},{"ns":[92,94],"script":[["","Hi, Mr. Rossi. I work at Cullom Studios, and I’m a production assistant for a new film that’ll be set in seventeenth-century France. I’m calling because we’d like to hire you as a consultant for our film. I recently came across the book you wrote on the history of French fashion and found it fascinating. Since you’re an expert on French clothing and lifestyle trends of that time, your knowledge would be valuable as we develop costume and set designs. We’d be thrilled to work with you, and we’re offering a generous compensation package. I can send you the details—I’ll use the e-mail address you have on your Web site.","Xin chào ông Rossi. Tôi làm việc tại Cullom Studios và hiện là trợ lý sản xuất cho một bộ phim mới lấy bối cảnh nước Pháp thế kỷ XVII. Tôi gọi điện vì chúng tôi muốn mời ông làm cố vấn cho bộ phim này. Gần đây tôi tình cờ đọc được cuốn sách ông viết về lịch sử thời trang Pháp và thấy nó vô cùng hấp dẫn. Vì ông là chuyên gia về trang phục và xu hướng lối sống của Pháp trong giai đoạn đó, kiến thức của ông sẽ rất có giá trị khi chúng tôi phát triển thiết kế trang phục và bối cảnh phim. Chúng tôi sẽ rất vinh dự được hợp tác cùng ông và đang đề nghị một gói thù lao hậu hĩnh. Tôi có thể gửi cho ông các thông tin chi tiết qua địa chỉ email trên trang web của ông."]],"qs":[{"n":92,"q":"Why is the speaker calling?","qvi":"Người nói gọi để làm gì?","opts":["To ask the listener to donate to a charity","To offer the listener a job","To explain a publishing delay","To request an interview for an article"],"vi":["Kêu gọi quyên góp","Mời nhận việc","Giải thích việc xuất bản chậm","Xin phỏng vấn cho một bài báo"],"ans":"B"},{"n":93,"q":"How did the speaker first learn about the listener?","qvi":"Người nói biết về người nghe lần đầu bằng cách nào?","opts":["She read one of his books.","She attended a workshop he led.","She saw his comment on a social media post.","She watched a documentary about his work."],"vi":["Đọc sách của anh ấy","Tham dự workshop anh ấy dẫn","Thấy bình luận trên mạng","Xem phim tài liệu về anh ấy"],"ans":"A"},{"n":94,"q":"What will the speaker most likely do next?","qvi":"Người nói sẽ làm gì tiếp theo?","opts":["Print and sign a contract","Send some information","Reserve a meeting room","Contact a talent agent"],"vi":["In và ký hợp đồng","Gửi thêm thông tin","Đặt phòng họp","Liên hệ quản lý tài năng"],"ans":"B"}],"a":"E26-T06-92-94.mp3"},{"ns":[95,97],"script":[["","Are you looking for a convenient way to get around the city? The city of Lakepoint offers on-demand transportation in several of our neighborhoods. Just download the Lakepoint City application onto your mobile phone. Once you make an appointment on the app, a shuttle will arrive within fifteen minutes. This easy-to-use service will take you to any destination within the service area, like your doctor’s office or the library. And we’ve recently expanded service to Westbrook, so residents can take the shuttle to the soccer stadium.","Bạn đang tìm kiếm một cách thuận tiện để di chuyển trong thành phố sao? Thành phố Lakepoint cung cấp dịch vụ vận chuyển theo yêu cầu tại một số khu dân cư. Chỉ cần tải ứng dụng Lakepoint City về điện thoại di động của bạn. Khi bạn đặt lịch hẹn trên ứng dụng, xe trung chuyển sẽ đến trong vòng mười lăm phút. Dịch vụ dễ sử dụng này sẽ đưa bạn đến bất kỳ điểm đến nào trong khu vực phục vụ, như phòng khám bác sĩ hay thư viện. Ngoài ra, gần đây chúng tôi đã mở rộng dịch vụ đến khu Westbrook, vì vậy cư dân có thể đi xe trung chuyển đến sân vận động bóng đá."]],"qs":[{"n":95,"q":"What type of service is being advertised?","qvi":"Loại dịch vụ nào đang được quảng cáo?","opts":["Recycling","Transportation","Grocery delivery","Exercise classes"],"vi":["Tái chế","Vận chuyển","Giao hàng tạp hóa","Lớp thể dục"],"ans":"B"},{"n":96,"q":"According to the speaker, how can the listeners use a new service?","qvi":"Theo người nói, người nghe dùng dịch vụ mới bằng cách nào?","opts":["By entering payment information","By placing a phone call","By visiting a community center","By using a mobile application"],"vi":["Nhập thông tin thanh toán","Gọi điện","Đến trung tâm cộng đồng","Dùng ứng dụng"],"ans":"D","note":"File đáp án của sách ghi (A), nhưng lời thoại cho thấy đáp án đúng là (D); web chấm theo (D)."},{"n":97,"q":"Look at the graphic. Which area was recently added?","qvi":"Nhìn vào sơ đồ. Khu vực nào mới thêm vào?","opts":["Area 1","Area 2","Area 3","Area 4"],"vi":["Khu 1","Khu 2","Khu 3","Khu 4"],"ans":"B","note":"File đáp án của sách ghi (C), nhưng lời thoại cho thấy đáp án đúng là (B); web chấm theo (B)."}],"a":"E26-T06-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","And our last news item today is the Greenchester Archaeological Festival taking place this weekend. Greenchester is home to some rich prehistoric findings. If you’ve ever wondered what goes into excavating a site, here’s your chance to find out. There’ll be a special workshop where you can get hands-on experience practicing excavation skills. The workshop will be held on the grounds in front of the historical society building. As for getting here, I recommend that you simply walk over—many streets will be blocked off for the festival, and it will take longer to drive.","Và bản tin cuối cùng của ngày hôm nay là Lễ hội Khảo cổ học Greenchester sẽ diễn ra vào cuối tuần này. Greenchester là nơi có nhiều phát hiện khảo cổ tiền sử quan trọng. Nếu bạn từng thắc mắc việc khai quật một địa điểm khảo cổ diễn ra như thế nào, thì đây chính là cơ hội để tìm hiểu. Sẽ có một buổi hội thảo đặc biệt, nơi bạn có thể trực tiếp thực hành các kỹ năng khai quật. Buổi hội thảo sẽ được tổ chức tại khuôn viên phía trước tòa nhà hội lịch sử. Về việc di chuyển đến đây, tôi khuyên bạn nên đi bộ — nhiều tuyến đường sẽ bị chặn để phục vụ lễ hội và việc lái xe sẽ mất nhiều thời gian hơn."]],"qs":[{"n":98,"q":"What event is the speaker mainly discussing?","qvi":"Sự kiện người nói đang nói đến là gì?","opts":["An archaeology festival","A museum opening","A gardening fair","An outdoor concert"],"vi":["Lễ hội khảo cổ","Lễ khai trương bảo tàng","Hội chợ làm vườn","Buổi hòa nhạc ngoài trời"],"ans":"A"},{"n":99,"q":"Look at the graphic. Where will a workshop take place?","qvi":"Nhìn vào hình. Workshop sẽ tổ chức ở đâu?","opts":["In The Rose Garden","In Maple Courtyard","In Tanry Park","In Riverside Nature Preserve"],"vi":["Vườn Hoa Hồng","Sân Maple","Công viên Tanry","Khu bảo tồn thiên nhiên Riverside"],"ans":"C"},{"n":100,"q":"What does the speaker recommend?","qvi":"Người nói khuyên điều gì?","opts":["Arriving early","Walking","Volunteering","Bringing a jacket"],"vi":["Đến sớm","Đi bộ","Tình nguyện","Mang áo khoác"],"ans":"B"}],"a":"E26-T06-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"On Saturday, the Edbridge Orchestra will ------- a new work by local composer Nina Borstein.","opts":["make","operate","perform","fulfill"],"ans":"C","xp":"perform a work = biểu diễn tác phẩm âm nhạc / nghệ thuật\nmake: không dùng với tác phẩm âm nhạc\noperate: vận hành (máy móc, hệ thống)\nfulfill: fulfill a duty / obligation: không dùng cho âm nhạc\n→ Chọn (C)\nDịch: Vào thứ Bảy, dàn nhạc Edbridge sẽ biểu diễn một tác phẩm mới của nhà soạn nhạc địa phương Nina Borstein."},{"n":102,"q":"It is important to be especially ------- when in the company of new clients.","opts":["polite","politely","politest","politeness"],"ans":"A","xp":"polite: tính từ = sau to be để miêu tả trạng thái\npolitely: trạng từ\npolitest: so sánh nhất\npoliteness: danh từ\n→ Chọn (A)\nDịch: Điều quan trọng là phải đặc biệt lịch sự khi ở cùng các khách hàng mới."},{"n":103,"q":"Although Ms. Endou was not chosen for an award, ------- achievements were praised.","opts":["she","her","hers","herself"],"ans":"B","xp":"she: đại từ chủ ngữ\nher: tính từ sở hữu → đứng trước danh từ “achievements”\nhers: đại từ sở hữu → không đi kèm danh từ\nherself: đại từ phản thân → sai cấu trúc\n→ Chọn (B)\nDịch: Mặc dù cô Endou không được chọn nhận giải thưởng, những thành tựu của cô vẫn được khen ngợi."},{"n":104,"q":"At the end of the year, organizations face pressure to achieve their financial -------.","opts":["procedure","goals","season","bills"],"ans":"B","xp":"financial goals = mục tiêu tài chính\nprocedure: quy trình\nseason: mùa\nbills: hóa đơn\n→ Chọn (B)\nDịch: Vào cuối năm, các tổ chức phải đối mặt với áp lực để đạt được các mục tiêu tài chính của họ."},{"n":105,"q":"Online ordering is ------- on Naito Café’s Web site.","opts":["called","printed","capable","available"],"ans":"D","xp":"(A) called: được gọi là\n(B) printed: được in ra\n(C) capable: có khả năng\n(D) available: có sẵn/có hiệu lực\nGiải thích: Cụm \"available on a website\" (có sẵn trên trang web) là cách dùng phổ biến nhất.\n→ Chọn (D)\nDịch: Việc đặt hàng trực tuyến hiện đã có sẵn trên trang web của Naito Café."},{"n":106,"q":"Mayor Park plans to meet with his campaign staff ------- the televised debate.","opts":["following","beside","from","under"],"ans":"A","xp":"(A) following: sau khi\n(B) beside: bên cạnh\n(C) from: từ\n(D) under: dưới\nGiải thích: \"Following\" ở đây đóng vai trò như một giới từ mang nghĩa là \"sau khi\".\n→ Chọn (A)\nDịch: Thị trưởng Park dự định gặp gỡ đội ngũ nhân viên chiến dịch của mình sau cuộc tranh luận trên truyền hình."},{"n":107,"q":"Mr. Suh has requested that a more ------- copy machine be purchased for the finance department.","opts":["reliably","relying","relied","reliable"],"ans":"D","xp":"Giải thích: Đây là câu hỏi về từ loại. Cần một tính từ đứng trước cụm danh từ \"copy machine\".\n(A) reliably: trạng từ\n(B) relying: V-ing\n(C) relied: P2\n(D) reliable: tính từ (đáng tin cậy)\n→ Chọn (D)\nDịch: Ông Suh đã yêu cầu mua một chiếc máy photocopy đáng tin cậy hơn cho bộ phận tài chính."},{"n":108,"q":"Mr. Aponte’s photograph of the autumn foliage will be featured on the front ------- of Outward Expansion Magazine.","opts":["cover","coverage","covered","coverable"],"ans":"A","xp":"(A) cover: trang bìa\n(B) coverage: việc đưa tin/độ bao phủ\n(C) covered: được che phủ (P2)\n(D) coverable: có thể che phủ được (adj)\nGiải thích: Cụm \"front cover\" nghĩa là trang bìa trước của tạp chí.\n→ Chọn (A)\nDịch: Bức ảnh về những tán lá mùa thu của ông Aponte sẽ được đăng nổi bật trên trang bìa trước của Tạp chí Outward Expansion."},{"n":109,"q":"Handi Office Supplies’ new desk organizers serve ------- practical and stylish additions to any office workstation.","opts":["of","as","out","until"],"ans":"B","xp":"(B) as: như là\nGiải thích: Cấu trúc \"serve as something\" nghĩa là đóng vai trò như là cái gì.\n→ Chọn (B)\nDịch: Những khay sắp xếp bàn làm việc mới của Handi Office Supplies đóng vai trò như những phụ kiện bổ sung thiết thực và thời trang cho bất kỳ chỗ làm việc văn phòng nào."},{"n":110,"q":"The efficient redesign of the airline terminal led to ------- flight delays.","opts":["friendlier","accurate","previous","fewer"],"ans":"D","xp":"(A) friendlier: thân thiện hơn\n(B) accurate: chính xác\n(C) previous: trước đó\n(D) fewer: ít hơn\nGiải thích: \"Flight delays\" là danh từ đếm được số nhiều, nên dùng \"fewer\" để chỉ số lượng ít hơn.\n→ Chọn (D)\nDịch: Việc thiết kế lại nhà ga hàng không một cách hiệu quả đã dẫn đến ít sự chậm trễ chuyến bay hơn."},{"n":111,"q":"Mr. Ogbu’s editor appreciated his ability to approach the subject matter -------.","opts":["objects","objectivity","objectively","objected"],"ans":"C","xp":"(C) objectively: một cách khách quan\nGiải thích: Cần một trạng từ để bổ nghĩa cho động từ \"approach\" (tiếp cận).\n(A) objects: danh từ số nhiều / động từ\n(B) objectivity: danh từ\n(D) objected: quá khứ\n→ Chọn (C)\nDịch: Biên tập viên của ông Ogbu đã đánh giá cao khả năng tiếp cận vấn đề một cách khách quan của ông ấy."},{"n":112,"q":"Mr. Nakayama was named Employee of the Year, ------- being new to the company.","opts":["despite","unless","prior to","whether"],"ans":"A","xp":"(A) despite: mặc dù (+ cụm danh từ/V-ing)\n(B) unless: trừ khi (+ mệnh đề)\n(C) prior to: trước khi\n(D) whether: liệu rằng\nGiải thích: Dùng \"despite\" để chỉ sự tương phản (được giải mặc dù mới vào công ty).\n→ Chọn (A)\nDịch: Ông Nakayama đã được vinh danh là Nhân viên của năm, mặc dù chỉ mới gia nhập công ty."},{"n":113,"q":"For the ------- selection of premium paints and art-making supplies anywhere, visit your nearest Painters’ Best store.","opts":["widen","widening","widest","widely"],"ans":"C","xp":"(C) widest: rộng nhất/đa dạng nhất\nGiải thích: Có \"the\" phía trước và cần tính từ bổ nghĩa cho \"selection\", dùng dạng so sánh nhất.\n(A) widen: động từ\n(B) widening: V-ing\n(D) widely: trạng từ\n→ Chọn (C)\nDịch: Để có được sự lựa chọn đa dạng nhất về các loại sơn cao cấp và dụng cụ vẽ tranh ở bất cứ đâu, hãy ghé thăm cửa hàng Painters’ Best gần nhất."},{"n":114,"q":"The Stallmain Corporation’s latest survey was intended to ------- employee satisfaction in several key categories.","opts":["overcome","prolong","deserve","determine"],"ans":"D","xp":"(A) overcome: vượt qua (khó khăn)\n(B) prolong: kéo dài (thời gian)\n(C) deserve: xứng đáng\n(D) determine: xác định/đánh giá\nGiải thích: Cuộc khảo sát nhằm mục đích \"xác định\" mức độ hài lòng.\n→ Chọn (D)\nDịch: Cuộc khảo sát mới nhất của Tập đoàn Stallmain nhằm mục đích xác định mức độ hài lòng của nhân viên trong một vài danh mục chính."},{"n":115,"q":"Garza’s Restaurant is ------- decorated with paintings and photographs of southern Mexico.","opts":["elaborately","elaborating","elaborates","elaboration"],"ans":"A","xp":"(A) elaborately: một cách tỉ mỉ/công phu\nGiải thích: Trạng từ đứng giữa \"is\" và \"decorated\" (P2) để bổ nghĩa.\n(B) elaborating: V-ing\n(C) elaborates: động từ\n(D) elaboration: danh từ\n→ Chọn (A)\nDịch: Nhà hàng của Garza được trang trí một cách công phu với các bức họa và ảnh chụp về vùng miền nam Mexico."},{"n":116,"q":"Mr. Brighton’s first ------- at Glynn Engineering was in the materials testing group.","opts":["assign","assigned","assigning","assignment"],"ans":"D","xp":"(D) assignment: công việc được giao/nhiệm vụ\nGiải thích: Sau số thứ tự \"first\" cần một danh từ.\n(A) assign: giao việc (v)\n(B) assigned / (C) assigning: dạng động từ\n(D) assignment: nhiệm vụ (n)\n→ Chọn (D)\nDịch: Nhiệm vụ đầu tiên của ông Brighton tại Glynn Engineering là ở trong nhóm thử nghiệm vật liệu."},{"n":117,"q":"The installation of new benches throughout Haverford Park will cost ------- €5,000.","opts":["briefly","roughly","correctly","generously"],"ans":"B","xp":"(A) briefly: ngắn gọn\n(B) roughly: khoảng/xấp xỉ\n(C) correctly: một cách chính xác\n(D) generously: một cách hào phóng\nGiải thích: \"Roughly\" thường dùng với con số để ước lượng.\n→ Chọn (B)\nDịch: Việc lắp đặt các băng ghế mới trên khắp công viên Haverford sẽ tiêu tốn khoảng 5.000 Euro."},{"n":118,"q":"------- who is unable to attend the quarterly stakeholder meeting is welcome to appoint a representative.","opts":["Such","Whichever","Anyone","Those"],"ans":"C","xp":"(C) Anyone: bất cứ ai\nGiải thích: \"Anyone who\" là cấu trúc phổ biến để chỉ một người bất kỳ. \"Those\" phải đi với \"who are\".\n→ Chọn (C)\nDịch: Bất kỳ ai không thể tham dự cuộc họp cổ đông hàng quý đều được hoan nghênh chỉ định một người đại diện."},{"n":119,"q":"Singer Maria Stanley ------- today that she is scheduling a world tour.","opts":["reveal","revealed","to reveal","revealing"],"ans":"B","xp":"(B) revealed: đã tiết lộ\nGiải thích: Câu cần động từ chính; chia ở thì quá khứ đơn để thông báo một sự việc đã xảy ra. (C) to reveal và (D) revealing không làm động từ chính; (A) reveal không hợp chủ ngữ số ít.\n→ Chọn (B)\nDịch: Ca sĩ Maria Stanley đã tiết lộ hôm nay rằng cô đang lên lịch cho một chuyến lưu diễn thế giới."},{"n":120,"q":"Biographer Amber Bowen has been recognized for her distinctive writing -------.","opts":["styleless","styled","stylish","style"],"ans":"D","xp":"(D) style: phong cách\nGiải thích: Cần danh từ sau \"writing\". Cụm \"writing style\" (phong cách viết).\n(A) styleless / (C) stylish: tính từ\n(B) styled: P2\n→ Chọn (D)\nDịch: Nhà viết tiểu sử Amber Bowen đã được ghi nhận nhờ phong cách viết riêng biệt của mình."},{"n":121,"q":"The award-winning stationery created by the artists at Paperi Designs is of ------- quality.","opts":["comfortable","exceptional","hospitable","ambitious"],"ans":"B","xp":"(A) comfortable: thoải mái\n(B) exceptional: xuất sắc/đặc biệt tốt\n(C) hospitable: hiếu khách\n(D) ambitious: tham vọng\nGiải thích: \"Exceptional quality\" là cụm từ chỉ chất lượng vượt trội.\n→ Chọn (B)\nDịch: Các sản phẩm văn phòng phẩm đạt giải thưởng được tạo ra bởi các nghệ sĩ tại Paperi Designs có chất lượng xuất sắc."},{"n":122,"q":"During the past quarter, ------- all of Renafy Technology’s sales came from one region.","opts":["between","nearly","somewhat","next to"],"ans":"B","xp":"(A) between: giữa\n(B) nearly: gần như\n(C) somewhat: phần nào đó\n(D) next to: bên cạnh\nGiải thích: \"Nearly all\" nghĩa là gần như tất cả.\n→ Chọn (B)\nDịch: Trong quý vừa qua, gần như toàn bộ doanh số của Renafy Technology đều đến từ một khu vực duy nhất."},{"n":123,"q":"Commercial property insurance covers the ------- associated with repairing or rebuilding a business property after certain events.","opts":["expenses","symptoms","challenges","opportunities"],"ans":"A","xp":"(A) expenses: chi phí\n(B) symptoms: triệu chứng\n(C) challenges: thử thách\n(D) opportunities: cơ hội\nGiải thích: Bảo hiểm chi trả cho các \"chi phí\".\n→ Chọn (A)\nDịch: Bảo hiểm tài sản thương mại chi trả cho các chi phí liên quan đến việc sửa chữa hoặc xây dựng lại tài sản doanh nghiệp sau một số sự kiện nhất định."},{"n":124,"q":"The first-aid class usually fills up quickly, so prompt ------- is recommended.","opts":["registration","detection","information","certification"],"ans":"A","xp":"(A) registration: sự đăng ký\n(B) detection: sự phát hiện\n(C) information: thông tin\n(D) certification: sự cấp chứng chỉ\nGiải thích: Vì lớp nhanh đầy nên cần \"đăng ký\" ngay.\n→ Chọn (A)\nDịch: Lớp sơ cứu thường nhanh chóng kín chỗ, vì vậy bạn nên đăng ký sớm."},{"n":125,"q":"Manufacturing all its products in-house allows Long Bridge Steel Corp. to ------- every aspect of the production process.","opts":["expect","impress","remain","control"],"ans":"D","xp":"(A) expect: kỳ vọng\n(B) impress: gây ấn tượng\n(C) remain: duy trì/còn lại\n(D) control: kiểm soát\nGiải thích: Tự sản xuất giúp công ty \"kiểm soát\" mọi khía cạnh.\n→ Chọn (D)\nDịch: Việc tự sản xuất tất cả các sản phẩm ngay tại nhà máy của mình cho phép Tập đoàn Thép Long Bridge kiểm soát mọi khía cạnh của quy trình sản xuất."},{"n":126,"q":"------- its use on home-cooking shows, consumer demand for Silvershine Cookware has doubled.","opts":["Moreover","For example","Even though","Because of"],"ans":"D","xp":"(A) Moreover: hơn thế nữa (nối 2 mệnh đề)\n(B) For example: ví dụ như\n(C) Even though: mặc dù (+ mệnh đề)\n(D) Because of: bởi vì (+ cụm danh từ)\nGiải thích: Chỉ nguyên nhân dẫn đến việc nhu cầu tăng gấp đôi.\n→ Chọn (D)\nDịch: Nhờ vào việc được sử dụng trên các chương trình nấu ăn gia đình, nhu cầu của người tiêu dùng đối với Đồ dùng nhà bếp Silvershine đã tăng gấp đôi."},{"n":127,"q":"Artists at Cavin Graphics work ------- with clients through all stages of the design process to ensure satisfaction.","opts":["collaborative","collaboratively","collaborates","collaborators"],"ans":"B","xp":"(B) collaboratively: một cách hợp tác\nGiải thích: Trạng từ bổ nghĩa cho động từ \"work\".\n(A) collaborative: tính từ\n(C) collaborates: động từ\n(D) collaborators: danh từ\n→ Chọn (B)\nDịch: Các nghệ sĩ tại Cavin Graphics làm việc cộng tác với khách hàng qua tất cả các giai đoạn của quy trình thiết kế để đảm bảo sự hài lòng."},{"n":128,"q":"Brile Construction’s contract for the mall development project has finally been ------- by the city supervisor.","opts":["verifying","verifiably","verified","verification"],"ans":"C","xp":"(C) verified: được xác nhận/đối soát\nGiải thích: Cấu trúc bị động \"has been + P2\" (có \"by the city supervisor\").\n(A) verifying: V-ing\n(B) verifiably: trạng từ\n(D) verification: danh từ\n→ Chọn (C)\nDịch: Hợp đồng của Brile Construction cho dự án phát triển trung tâm thương mại cuối cùng đã được xác nhận bởi giám sát viên thành phố."},{"n":129,"q":"------- 4,000 Urlvac trash removal systems are in use in the eastern region.","opts":["Always","Quite","Almost","Closely"],"ans":"C","xp":"(A) Always: luôn luôn\n(B) Quite: khá\n(C) Almost: gần như/khoảng\n(D) Closely: một cách chặt chẽ\nGiải thích: \"Almost\" dùng với con số để chỉ mức độ xấp xỉ.\n→ Chọn (C)\nDịch: Gần 4.000 hệ thống xử lý rác thải Urlvac đang được sử dụng ở khu vực phía đông."},{"n":130,"q":"The conference schedule will be posted online ------- mailed to attendees.","opts":["in order that","as soon as","in case","rather than"],"ans":"D","xp":"(A) in order that: để mà\n(B) as soon as: ngay khi\n(C) in case: phòng khi\n(D) rather than: thay vì\nGiải thích: So sánh hai hình thức thực hiện (đăng online thay vì gửi thư).\n→ Chọn (D)\nDịch: Lịch trình hội nghị sẽ được đăng trực tuyến thay vì gửi qua thư cho những người tham dự."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following notice.","passage":"<h3>Bicycles on Buses Program</h3><p>All Travelbee buses are now outfitted with exterior bicycle racks. This <span class=\"blank\" data-n=\"131\">-------</span> has been installed to encourage our passengers to incorporate bicycle riding into their lives for transportation, exercise, and pleasure. <span class=\"blank\" data-n=\"132\">-------</span>. Please note, however, that electric bicycles are not <span class=\"blank\" data-n=\"133\">-------</span>. For more information on our complimentary Bicycles on Buses program, please visit www.travelbee.com/bicyclesonbuses. There you can also learn about great bicycle trails that <span class=\"blank\" data-n=\"134\">-------</span> accessed from our bus routes.</p>","vi":"Chương trình Mang Xe Đạp Lên Xe Buýt\n\nTất cả các xe buýt của Travelbee hiện nay đều được trang bị giá để xe đạp bên ngoài. Thiết bị này đã được lắp đặt nhằm khuyến khích hành khách của chúng tôi đưa việc đi xe đạp vào cuộc sống hằng ngày cho mục đích di chuyển, rèn luyện sức khỏe và giải trí. Không tính thêm phí khi mang theo xe đạp. Tuy nhiên, xin lưu ý rằng xe đạp điện không được phép mang lên. Để biết thêm thông tin về chương trình Mang Xe Đạp Lên Xe Buýt miễn phí của chúng tôi, vui lòng truy cập www.travelbee.com/bicyclesonbuses. Tại đó, bạn cũng có thể tìm hiểu về những tuyến đường dành cho xe đạp rất tuyệt vời mà có thể tiếp cận từ các tuyến xe buýt của chúng tôi.","qs":[{"n":131,"opts":["furniture","exhibition","equipment","application"],"ans":"C","xp":"(C) equipment: thiết bị\nGiải thích: Câu trước đề cập đến \"exterior bicycle racks\" (giá đỡ xe đạp bên ngoài). Trong 4 lựa chọn, equipment (thiết bị) là danh từ phù hợp nhất để thay thế cho \"bicycle racks\".\n(A) furniture: nội thất\n(B) exhibition: cuộc triển lãm\n(D) application: ứng dụng/đơn xin việc\n→ Chọn (C)\nDịch câu: \"Thiết bị này đã được lắp đặt để khuyến khích hành khách kết hợp việc đi xe đạp vào cuộc sống...\""},{"n":132,"opts":["No additional fee will be charged for bringing a bicycle.","Always make sure to exit at the correct bus stop.","Special lanes for bicycles are now found on most highways.","Some passengers qualify for reduced bus fare."],"ans":"A","xp":"(A) No additional fee will be charged for bringing a bicycle. (Không tính thêm phí khi mang theo xe đạp.)\nGiải thích: Câu sau đó có cụm từ \"complimentary Bicycles on Buses program\" (chương trình xe đạp trên xe buýt miễn phí). Do đó, thông tin về việc không tính thêm phí là logic nhất.\n(B) Nhắc nhở xuống đúng trạm (không liên quan trực tiếp đến xe đạp).\n(C) Nói về làn đường xe đạp trên cao tốc (không liên quan đến dịch vụ của xe buýt).\n(D) Nói về giảm giá vé xe buýt (không tập trung vào mục đích của chương trình xe đạp).\n→ Chọn (A)"},{"n":133,"opts":["efficient","common","flexible","permitted"],"ans":"D","xp":"(D) permitted: được cho phép\nGiải thích: Câu này đang đưa ra một lưu ý (Please note, however...). Trong ngữ cảnh các quy định trên phương tiện công cộng, ta dùng permitted (được cho phép).\n(A) efficient: hiệu quả\n(B) common: phổ biến\n(C) flexible: linh hoạt\n→ Chọn (D)\nDịch câu: \"Tuy nhiên, hãy lưu ý rằng xe đạp điện không được cho phép.\""},{"n":134,"opts":["were","can be","had to be","will have been"],"ans":"B","xp":"(B) can be\nGiải thích: Cần cấu trúc bị động để mô tả khả năng/sự thật hiển nhiên. \"Can be accessed\" có nghĩa là \"có thể được tiếp cận\".\n(A) were: quá khứ (không phù hợp vì đây là thông tin hiện tại).\n(C) had to be: đã phải (nghĩa bắt buộc trong quá khứ, không phù hợp).\n(D) will have been: tương lai hoàn thành (không đúng ngữ cảnh).\n→ Chọn (B)\nDịch câu: \"...những con đường dành cho xe đạp tuyệt vời mà có thể được tiếp cận từ các tuyến xe buýt của chúng tôi.\""}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following article.","passage":"<h3>Corporate Training News</h3><p>Multinational appliance manufacturer Crystal Technologies recently <span class=\"blank\" data-n=\"135\">-------</span> an innovative training program for workers. The program uses what are called “escape rooms” to build teamwork and creative problem-solving skills. A special facility has been built for this purpose within the company’s headquarters in Inverness, Scotland. The facility consists of four rooms, <span class=\"blank\" data-n=\"136\">-------</span> of which is designed to represent a different geographic area that is part of Crystal’s global operations. Working in teams of five, employees must solve a business problem particular to that area to be able to unlock the door and enter the next room. <span class=\"blank\" data-n=\"137\">-------</span>. Crystal plans to install escape rooms in its main production facilities outside of Europe <span class=\"blank\" data-n=\"138\">-------</span>.</p>","vi":"Tin Tức Đào Tạo Doanh Nghiệp\n\nTập đoàn sản xuất thiết bị gia dụng đa quốc gia Crystal Technologies gần đây đã triển khai một chương trình đào tạo sáng tạo dành cho nhân viên. Chương trình này sử dụng cái gọi là “phòng thoát hiểm” để xây dựng tinh thần làm việc nhóm và kỹ năng giải quyết vấn đề sáng tạo. Một cơ sở đặc biệt đã được xây dựng cho mục đích này tại trụ sở chính của công ty ở Inverness, Scotland. Cơ sở này gồm bốn căn phòng, mỗi phòng trong số đó được thiết kế để đại diện cho một khu vực địa lý khác nhau, là một phần trong hoạt động toàn cầu của Crystal. Làm việc theo nhóm năm người, nhân viên phải giải quyết một vấn đề kinh doanh đặc thù của khu vực đó để có thể mở khóa cánh cửa và bước vào căn phòng tiếp theo. Khóa học phải được hoàn thành trong vòng nửa giờ. Crystal dự định cũng sẽ lắp đặt các phòng thoát hiểm tại các cơ sở sản xuất chính của mình bên ngoài châu Âu.","qs":[{"n":135,"opts":["exported","changed","considered","implemented"],"ans":"D","xp":"(D) implemented: triển khai/thực hiện\nGiải thích: Trong ngữ cảnh một công ty bắt đầu áp dụng một chương trình đào tạo (training program), từ implemented là phù hợp nhất.\n(A) exported: xuất khẩu\n(B) changed: thay đổi\n(C) considered: xem xét\n→ Chọn (D)\nDịch câu: \"Công ty sản xuất thiết bị đa quốc gia Crystal Technologies gần đây đã triển khai một chương trình đào tạo đổi mới cho nhân viên.\""},{"n":136,"opts":["each","either","theirs","another"],"ans":"A","xp":"(A) each: mỗi\nGiải thích: Cấu trúc \"each of which\" dùng để chỉ từng cái một trong số những cái đã được nhắc đến trước đó (ở đây là \"four rooms\" - bốn căn phòng).\n(B) either: một trong hai (chỉ dùng khi có 2 đối tượng).\n(C) theirs: của họ (đại từ sở hữu, không hợp ngữ pháp ở đây).\n(D) another: một cái khác (không dùng trong cấu trúc \"another of which\").\n→ Chọn (A)\nDịch câu: \"Cơ sở này bao gồm bốn phòng, mỗi phòng trong số đó được thiết kế để đại diện cho một khu vực địa lý khác nhau...\""},{"n":137,"opts":["Constructing an escape room is surprisingly expensive.","Poor training can be a problem in manufacturing operations.","The course must be completed within a half hour.","The company produces electronics and major home appliances."],"ans":"C","xp":"(C) The course must be completed within a half hour. (Khóa học phải được hoàn thành trong vòng nửa giờ.)\nGiải thích: Câu trước nói về việc các nhóm phải giải quyết vấn đề để mở khóa cửa và sang phòng tiếp theo. Câu (C) bổ sung thông tin về quy tắc thời gian của khóa học này.\n(A) Chi phí xây dựng đắt đỏ (không liên quan đến cách thức hoạt động đang mô tả).\n(B) Đào tạo kém là một vấn đề (quá chung chung, không khớp mạch văn).\n(D) Công ty sản xuất đồ điện tử (thông tin này đã có ở đầu bài, không cần lặp lại).\n→ Chọn (C)"},{"n":138,"opts":["as well","again","after all","at that time"],"ans":"A","xp":"(A) as well: cũng, nữa\nGiải thích: \"As well\" đặt ở cuối câu có nghĩa là \"cũng vậy\" hoặc \"nữa\". Trước đó bài báo nói về cơ sở tại Inverness, Scotland (thuộc châu Âu). Câu cuối nói rằng họ cũng có kế hoạch lắp đặt tại các cơ sở sản xuất ngoài châu Âu nữa.\n(B) again: lại một lần nữa\n(C) after all: sau tất cả/xét cho cùng\n(D) at that time: vào thời điểm đó\n→ Chọn (A)\nDịch câu: \"Crystal có kế hoạch lắp đặt các phòng thoát hiểm tại các cơ sở sản xuất chính của mình bên ngoài châu Âu nữa.\""}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> allclients@yardleyriverdentalgroup.com</p><p><b>From:</b> tliu@yardleyriverdentalgroup.com</p><p><b>Date:</b> 7 January</p><p><b>Subject:</b> Parking area</p></div><p>Dear Clients,</p><p>Yardley River Dental Group will be closing our client parking area next week in order to <span class=\"blank\" data-n=\"139\">-------</span> some needed repairs. <span class=\"blank\" data-n=\"140\">-------</span>. During this time, we request that you park your vehicles in the staff parking area, which is to the left of your usual area. (Staff members will park at a specially arranged off-site location while the repairs are being conducted.) From the staff parking area, you will find a walkway that <span class=\"blank\" data-n=\"141\">-------</span> around the side of the building to our front entrance. We apologize for the <span class=\"blank\" data-n=\"142\">-------</span> and thank you for your patience.</p><p>Tina Liu, Office Manager</p>","vi":"Gửi: allclients@yardleyriverdentalgroup.com\nTừ: tliu@yardleyriverdentalgroup.com\nNgày: 7 tháng 1\nChủ đề: Khu vực đậu xe\n\nKính gửi Quý khách hàng,\n\nPhòng khám Nha khoa Yardley River Dental Group sẽ đóng cửa khu vực đậu xe dành cho khách hàng vào tuần tới nhằm tiến hành một số hạng mục sửa chữa cần thiết. Khu vực này sẽ đóng cửa từ sáng thứ Ba đến hết thứ Sáu. Trong thời gian này, chúng tôi kính đề nghị quý khách đậu xe tại khu vực đậu xe dành cho nhân viên, nằm bên trái khu vực đậu xe thông thường của quý khách. (Các nhân viên sẽ đậu xe tại một địa điểm ngoài khuôn viên đã được sắp xếp đặc biệt trong thời gian tiến hành sửa chữa.) Từ khu vực đậu xe của nhân viên, quý khách sẽ thấy một lối đi chạy vòng quanh bên hông tòa nhà dẫn đến lối vào phía trước của chúng tôi. Chúng tôi xin lỗi vì sự bất tiện này và cảm ơn sự kiên nhẫn của quý khách.\n\nTina Liu, Quản lý văn phòng","qs":[{"n":139,"opts":["carry out","communicate","bring up","label"],"ans":"A","xp":"(A) carry out: tiến hành, thực hiện\nGiải thích: Cụm động từ \"carry out\" thường đi với các danh từ như repairs, research, survey. \"Carry out some needed repairs\" nghĩa là tiến hành một số sửa chữa cần thiết.\n(B) communicate: giao tiếp/thông báo\n(C) bring up: nuôi dưỡng/đề cập một vấn đề\n(D) label: dán nhãn\n→ Chọn (A)"},{"n":140,"opts":["Clients will comment on the uneven pavement in the parking area.","We are located along the bus 11 and bus 27 routes.","It will be closed from Tuesday morning through Friday.","The group recently welcomed several new dentists and hygienists."],"ans":"C","xp":"(C) It will be closed from Tuesday morning through Friday. (Khu vực này sẽ đóng cửa từ sáng thứ Ba đến hết thứ Sáu.)\nGiải thích: Câu trước đề cập đến việc đóng cửa bãi đỗ xe vào \"tuần tới\" (next week). Câu (C) cung cấp thời gian cụ thể bãi đỗ xe bị đóng, tạo liên kết logic; câu sau \"During this time\" cũng khớp.\n(A) Khách hàng sẽ nhận xét về mặt đường không bằng phẳng (không phù hợp).\n(B) Nói về các tuyến xe buýt (không liên quan đến việc đóng bãi đỗ xe).\n(D) Chào đón nha sĩ mới (lạc đề).\n→ Chọn (C)"},{"n":141,"opts":["to lead","leads","leader","was leading"],"ans":"B","xp":"(B) leads: dẫn tới\nGiải thích: Cần một động từ chính cho mệnh đề quan hệ \"that ... around the side of the building\". Chủ ngữ \"a walkway\" là danh từ số ít, nên động từ \"leads\" chia ở hiện tại đơn để mô tả một sự thật/đặc điểm của lối đi.\n(A) to lead: dạng nguyên thể có \"to\", không làm động từ chính sau \"that\".\n(C) leader: danh từ (người lãnh đạo).\n(D) was leading: quá khứ tiếp diễn (không phù hợp với ngữ cảnh hiện tại).\n→ Chọn (B)"},{"n":142,"opts":["inconvenience","addition","error","damage"],"ans":"A","xp":"(A) inconvenience: sự bất tiện\nGiải thích: Cụm rất phổ biến trong thông báo dịch vụ: \"apologize for the inconvenience\" (xin lỗi vì sự bất tiện). Khi một khu vực bị đóng cửa để sửa chữa, nó gây bất tiện cho khách hàng.\n(B) addition: sự thêm vào\n(C) error: lỗi sai\n(D) damage: sự hư hại\n→ Chọn (A)"}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following notice.","passage":"<h3>Attention: All Randall-Humboldt Employees</h3><p>Randall-Humboldt recently experienced a reduction in mail-room staffing. <span class=\"blank\" data-n=\"143\">-------</span>, starting on October 7, mail will no longer be delivered to employees’ desks. Departments will be responsible for picking up and distributing their own mail. Each department <span class=\"blank\" data-n=\"144\">-------</span> one employee to handle mail duties. It is up to the department head to determine how best to assign this responsibility. Mail will be available for pickup by 10:00 A.M. each morning.</p><p>It is strongly recommended <span class=\"blank\" data-n=\"145\">-------</span> employees contact senders of unwanted or junk mail and ask to be removed from those mailing lists. <span class=\"blank\" data-n=\"146\">-------</span>. It will also benefit the environment by reducing waste.</p>","vi":"Thông báo: Gửi toàn thể nhân viên Randall-Humboldt\n\nCông ty Randall-Humboldt gần đây đã trải qua việc cắt giảm nhân sự tại phòng thư. Kết quả là, bắt đầu từ ngày 7 tháng 10, thư từ sẽ không còn được chuyển trực tiếp đến bàn làm việc của nhân viên nữa. Các phòng ban sẽ tự chịu trách nhiệm nhận và phân phát thư từ của mình. Mỗi phòng ban nên chỉ định một nhân viên để phụ trách công việc xử lý thư từ. Trưởng bộ phận sẽ quyết định cách phân công trách nhiệm này sao cho phù hợp nhất. Thư sẽ có sẵn để nhận trước 10:00 sáng mỗi ngày.\n\nChúng tôi đặc biệt khuyến nghị rằng nhân viên liên hệ với người gửi các loại thư không mong muốn hoặc thư rác và yêu cầu được xóa khỏi danh sách gửi thư. Làm như vậy sẽ giúp tinh giản việc phân phối thư. Điều này cũng sẽ giúp bảo vệ môi trường bằng cách giảm thiểu rác thải.","qs":[{"n":143,"opts":["As a result","Instead","Nevertheless","If so"],"ans":"A","xp":"(A) As a result: Kết quả là\nGiải thích: Câu trước nêu nguyên nhân: \"cắt giảm nhân sự phòng thư\" (reduction in mail-room staffing). Câu sau nêu kết quả: thư sẽ không còn được đưa tận bàn. Do đó, trạng từ liên kết As a result là phù hợp nhất để chỉ quan hệ nhân quả.\n(B) Instead: Thay vào đó\n(C) Nevertheless: Tuy nhiên/Dẫu vậy\n(D) If so: Nếu vậy\n→ Chọn (A)\nDịch câu: \"Randall-Humboldt gần đây đã cắt giảm nhân sự phòng thư. Kết quả là, bắt đầu từ ngày 7 tháng 10, thư sẽ không còn được chuyển đến tận bàn làm việc của nhân viên nữa.\""},{"n":144,"opts":["designated","would have designated","should designate","was to designate"],"ans":"C","xp":"(C) should designate: nên chỉ định\nGiải thích: Đây là lời hướng dẫn/đề nghị về trách nhiệm mới của các phòng ban. Cấu trúc should + động từ nguyên mẫu dùng để đưa ra lời khuyên hoặc chỉ dẫn công việc nên làm.\n(A) designated: quá khứ đơn (không phù hợp vì việc này sắp xảy ra).\n(B) would have designated: giả định trong quá khứ.\n(D) was to designate: dự định trong quá khứ.\n→ Chọn (C)\nDịch câu: \"Mỗi bộ phận nên chỉ định một nhân viên để xử lý các công việc liên quan đến thư từ.\""},{"n":145,"opts":["since","that","such as","whoever"],"ans":"B","xp":"(B) that: rằng\nGiải thích: Cấu trúc \"It is recommended that + S + V (nguyên mẫu)\" = khuyến nghị rằng ai đó nên làm gì. Ở đây: \"It is strongly recommended that employees contact senders...\". \"That\" là liên từ mở đầu mệnh đề danh từ, theo sau là mệnh đề đầy đủ \"employees contact...\".\n(A) since: kể từ khi/bởi vì\n(C) such as: ví dụ như\n(D) whoever: bất cứ ai\n→ Chọn (B)\nDịch câu: \"Chúng tôi đặc biệt khuyến nghị rằng nhân viên liên hệ với những người gửi thư rác hoặc thư không mong muốn và yêu cầu được xóa tên khỏi các danh sách gửi thư đó.\"","note":"Đáp án (B) đúng, nhưng lời giải gốc giải thích \"that\" là đại từ quan hệ bổ nghĩa cho \"senders\" — không chính xác. Đây là cấu trúc \"It is recommended that + S + V\" (\"that\" là liên từ). Phần giải thích đã được sửa lại."},{"n":146,"opts":["Doing so will help streamline mail distribution.","Mail is sometimes damaged while in transit.","The mail room can hold no more than four employees at one time.","Direct mail marketing can be an effective way to sell products."],"ans":"A","xp":"(A) Doing so will help streamline mail distribution. (Làm như vậy sẽ giúp tinh giản việc phân phối thư.)\nGiải thích: Câu này liên kết với hành động vừa nhắc ở câu trước (việc hủy đăng ký thư rác). Giảm bớt thư rác giúp việc phân loại và phân phối thư gọn nhẹ hơn (streamline). Câu tiếp theo \"It will also benefit the environment...\" (cũng có lợi cho môi trường) ủng hộ ý này.\n(B) Thư thỉnh thoảng bị hỏng khi vận chuyển (không liên quan đến việc chặn thư rác).\n(C) Phòng thư không chứa quá 4 người (không phù hợp mạch văn).\n(D) Tiếp thị qua thư là cách hiệu quả (ngược với ý muốn giảm thư rác).\n→ Chọn (A)\nDịch câu: \"Làm như vậy sẽ giúp tinh giản việc phân phối thư. Việc này cũng mang lại lợi ích cho môi trường bằng cách giảm thiểu rác thải.\""}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following advertisement.","passages":["<h3>Bumbleberry Farm</h3><p>8715 71st Street NW, Stanfurt, Oregon 97074<br>(971) 555-0144</p><h4>Pick your own blueberries!</h4><p>Bumbleberry Farm is known for its sweet, juicy blueberries. Come and enjoy an afternoon in our blueberry fields picking your own. We cater to families, but everyone is welcome!</p><p>Enjoy fresh blueberries as a healthy snack, or use them in homemade jams and baked goods. They are also great for adding to your favorite cereal in the morning.</p><p>Picking season this year is set to run from July 1 to September 15. Our fields are open Tuesday through Sunday from 10:00 a.m. to 3:00 p.m.</p><p>Admission to the fields is $2.00 per person, with a cost of $2.50 for each half liter of berries picked. Groups of up to 8 persons are welcome. Limit 1 liter per person.</p><p>For more information, visit our Web site at www.bumbleberryfarm.com.</p>"],"vi":"Trang trại Bumbleberry\n8715 71st Street NW, Stanfurt, Oregon 97074\n(971) 555-0144\n\nHái việt quất của riêng bạn!\n\nTrang trại Bumbleberry nổi tiếng với những trái việt quất ngọt và mọng nước. Hãy đến và tận hưởng một buổi chiều tại cánh đồng việt quất của chúng tôi, nơi bạn có thể tự tay hái quả. Chúng tôi phục vụ các gia đình, nhưng tất cả mọi người đều được chào đón!\n\nHãy thưởng thức việt quất tươi như một món ăn nhẹ tốt cho sức khỏe, hoặc dùng chúng để làm mứt tự làm và các món bánh nướng. Việt quất cũng rất tuyệt để thêm vào ngũ cốc ăn sáng yêu thích của bạn.\n\nMùa hái năm nay sẽ diễn ra từ ngày 1 tháng 7 đến ngày 15 tháng 9. Các cánh đồng của chúng tôi mở cửa từ thứ Ba đến Chủ nhật, từ 10:00 sáng đến 3:00 chiều.\n\nPhí vào cánh đồng là 2,00 đô la Mỹ mỗi người, và 2,50 đô la cho mỗi nửa lít việt quất được hái. Chúng tôi chào đón các nhóm tối đa 8 người. Giới hạn 1 lít việt quất cho mỗi người.\n\nĐể biết thêm thông tin, vui lòng truy cập trang web của chúng tôi tại www.bumbleberryfarm.com.","qs":[{"n":147,"q":"What is indicated about Bumbleberry Farm?","qvi":"Điều gì được đề cập về Bumbleberry Farm?","opts":["It is open seven days a week.","It is family-friendly.","It operates a bakery.","It offers group discounts."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"We cater to families, but everyone is welcome!\" (Chúng tôi phục vụ các gia đình, nhưng tất cả mọi người đều được chào đón) → trang trại thân thiện với gia đình. (A) sai vì chỉ mở từ thứ Ba đến Chủ nhật; (D) chỉ nói nhóm tối đa 8 người, không nói giảm giá.\n(A) Trang trại mở cửa bảy ngày một tuần.\n(B) Phù hợp cho cả gia đình.\n(C) Có vận hành một tiệm bánh.\n(D) Có ưu đãi giảm giá cho nhóm đông."},{"n":148,"q":"What is NOT mentioned as a way to enjoy blueberries?","qvi":"Điều nào KHÔNG được nhắc đến về cách thưởng thức quả việt quất?","opts":["In jams","In baked goods","On breakfast cereal","On ice cream"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"use them in homemade jams and baked goods\" (dùng để làm mứt và các món bánh nướng → A, B) và \"great for adding to your favorite cereal in the morning\" (thêm vào ngũ cốc buổi sáng → C). Không nhắc đến kem (ice cream) → chọn D.\n(A) Làm mứt.\n(B) Làm các món nướng.\n(C) Ăn cùng ngũ cốc buổi sáng.\n(D) Ăn kèm kem."}]},{"ns":[149,151],"head":"Questions 149-151 refer to the following news article.","passages":["<h3>Tin Prices May Improve</h3><p>LONDON (12 September)—Prices for tin rose to a record high in August. International inventories are unusually low at this time, and problems with availability persist. The price increases are driven by reduced supply in countries that produce the metal, coupled with increasing worldwide demand for and manufacturing of electronics, whose components are joined together with tin compounds.</p><p>Chilean Smelting, Inc., a major producer, has invested in improved equipment and aims to increase production. As a result, tin traders predict some moderation in prices as supplies rise.</p>"],"vi":"Giá Thiếc Có Thể Cải Thiện\n\nLONDON (ngày 12 tháng 9) — Giá thiếc đã tăng lên mức cao kỷ lục vào tháng Tám. Lượng tồn kho quốc tế hiện nay thấp bất thường, và các vấn đề về nguồn cung vẫn tiếp diễn. Sự gia tăng giá cả này xuất phát từ việc nguồn cung bị giảm tại các quốc gia sản xuất kim loại này, kết hợp với nhu cầu toàn cầu ngày càng tăng đối với việc sản xuất và tiêu thụ các thiết bị điện tử, trong đó các linh kiện được liên kết với nhau bằng các hợp chất của thiếc.\n\nChilean Smelting, Inc., một nhà sản xuất lớn, đã đầu tư vào thiết bị cải tiến và đặt mục tiêu tăng sản lượng. Kết quả là, các nhà giao dịch thiếc dự đoán rằng giá cả sẽ phần nào hạ nhiệt khi nguồn cung tăng lên.","qs":[{"n":149,"q":"According to the article, what is contributing to the demand for tin?","qvi":"Theo bài báo, điều gì làm tăng nhu cầu đối với thiếc?","opts":["Government regulations on tin production","Increased production of electronic goods","Improvements in mining technology","A global rise in the sale of canned foods"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"increasing worldwide demand for and manufacturing of electronics, whose components are joined together with tin compounds\" (nhu cầu toàn cầu ngày càng tăng đối với việc sản xuất thiết bị điện tử, mà linh kiện được nối bằng hợp chất thiếc) → sản xuất đồ điện tử tăng làm tăng nhu cầu thiếc.\n(A) Quy định của chính phủ về sản xuất thiếc.\n(B) Sản lượng thiết bị điện tử tăng.\n(C) Cải tiến trong công nghệ khai thác mỏ.\n(D) Doanh số đồ hộp trên toàn cầu tăng."},{"n":150,"q":"The word “driven” in paragraph 1, line 5, is closest in meaning to","qvi":"Từ “driven” ở đoạn 1, dòng 5 gần nghĩa nhất với","opts":["urged","chased","transported","caused"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"The price increases are driven by reduced supply…\" = Sự gia tăng giá cả xuất phát từ việc thiếu hụt nguồn cung và nhu cầu tăng cao… → \"xuất phát từ / do … gây ra\" = caused. KHÔNG phải urged / chased / transported.\n(A) thúc đẩy\n(B) đuổi theo\n(C) vận chuyển\n(D) gây ra"},{"n":151,"q":"What is indicated about Chilean Smelting, Inc.?","qvi":"Điều gì được đề cập về công ty Chilean Smelting?","opts":["It is a leading supplier of tin.","It recently hired more workers.","It is looking for new investors.","It regularly offers discounted pricing."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"Chilean Smelting, Inc., a major producer, has invested in improved equipment…\" (Chilean Smelting, Inc., một nhà sản xuất lớn…) → a major producer = a leading supplier of tin. Công ty tự đầu tư thiết bị, không nói tuyển người hay tìm nhà đầu tư.\n(A) Là nhà cung cấp thiếc hàng đầu.\n(B) Gần đây đã tuyển thêm công nhân.\n(C) Đang tìm kiếm nhà đầu tư mới.\n(D) Thường xuyên đưa ra giá ưu đãi."}]},{"ns":[152,153],"head":"Questions 152-153 refer to the following letter.","passages":["<p>Langdale Exterior Solutions • 39 Alderson Road • Highfield, Sheffield S2 4UA</p><p>17 September</p><p>Mr. Atharv Chatterjee<br>7 Croft Road<br>Brinsworth, Rotherham S60 5AP</p><p>Hello, Mr. Chatterjee,</p><p>Congratulations on the purchase of your new home! I’d like to introduce Langdale Exterior Solutions. We have worked with clients in the Sheffield area for over 30 years. Our team of experienced professionals makes us the most trusted landscape company in the area.</p><p>We can assist you in finding optimal solutions for your outdoor spaces at reasonable prices. We perform services from lawn maintenance to tree and shrub care. If you are interested in hardscape features such as brick pathways or rustic stone walls, we will provide recommendations on materials and styles that suit your tastes. We will even bring samples directly to you to help you make your design selections.</p><p>Call us today at 0114 496 0101 to schedule a free initial consultation.</p><p>Sincerely,</p><p><i>Tabatha Meyers</i><br>Tabatha Meyers, Owner, Langdale Exterior Solutions</p>"],"vi":"Langdale Exterior Solutions • 39 Alderson Road • Highfield, Sheffield S2 4UA\n\nNgày 17 tháng 9\n\nÔng Atharv Chatterjee\n7 Croft Road\nBrinsworth, Rotherham S60 5AP\n\nXin chào ông Chatterjee,\n\nXin chúc mừng ông nhân dịp mua ngôi nhà mới! Tôi xin giới thiệu Langdale Exterior Solutions. Chúng tôi đã làm việc với khách hàng tại khu vực Sheffield trong hơn 30 năm. Đội ngũ chuyên gia giàu kinh nghiệm của chúng tôi đã giúp chúng tôi trở thành công ty cảnh quan đáng tin cậy nhất trong khu vực.\n\nChúng tôi có thể hỗ trợ ông tìm ra những giải pháp tối ưu cho không gian ngoài trời với mức giá hợp lý. Chúng tôi cung cấp các dịch vụ từ bảo dưỡng bãi cỏ đến chăm sóc cây và bụi cây. Nếu ông quan tâm đến các hạng mục thi công cảnh quan cứng như lối đi lát gạch hoặc tường đá phong cách mộc mạc, chúng tôi sẽ đưa ra khuyến nghị về vật liệu và kiểu dáng phù hợp với sở thích của ông. Chúng tôi thậm chí còn mang mẫu vật trực tiếp đến cho ông để giúp ông đưa ra lựa chọn thiết kế.\n\nHãy gọi cho chúng tôi ngay hôm nay theo số 0114 496 0101 để đặt lịch tư vấn ban đầu miễn phí.\n\nTrân trọng,\nTabatha Meyers\nChủ sở hữu, Langdale Exterior Solutions","qs":[{"n":152,"q":"What is the main purpose of the letter?","qvi":"Mục đích chính của bức thư là gì?","opts":["To offer real estate sales services","To promote a landscaping business","To advertise a line of gardening products","To advise on local construction regulations"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"I’d like to introduce Langdale Exterior Solutions… the most trusted landscape company in the area\" (Tôi xin giới thiệu Langdale Exterior Solutions… công ty cảnh quan đáng tin cậy nhất) → mục đích là quảng bá một doanh nghiệp làm cảnh quan.\n(A) Cung cấp dịch vụ bán bất động sản\n(B) Quảng bá dịch vụ làm cảnh quan sân vườn\n(C) Quảng cáo dòng sản phẩm làm vườn\n(D) Tư vấn về quy định xây dựng của địa phương"},{"n":153,"q":"What is NOT indicated about Langdale Exterior Solutions?","qvi":"Điều nào KHÔNG được đề cập về Langdale Exterior Solutions?","opts":["They bring product samples to customers’ homes.","They do not charge for a first meeting.","They work with clients on design decisions.","They specialize in the construction of houses."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: (A) \"We will even bring samples directly to you\" (mang mẫu vật trực tiếp đến cho ông); (B) \"schedule a free initial consultation\" (tư vấn ban đầu miễn phí); (C) \"we will provide recommendations on materials and styles that suit your tastes… to help you make your design selections\" (đưa ra khuyến nghị, giúp ông lựa chọn thiết kế). Công ty làm cảnh quan, không xây nhà → chọn D.\n(A) Họ mang mẫu sản phẩm đến tận nhà khách hàng.\n(B) Họ không thu phí cho buổi gặp đầu tiên.\n(C) Họ cùng khách hàng đưa ra quyết định thiết kế.\n(D) Họ chuyên xây dựng nhà ở."}]},{"ns":[154,157],"head":"Questions 154-157 refer to the following letter.","passages":["<p>Katsunori Sanu<br>860 Cottonwood Avenue, Apartment 5A<br>Walkerton, ON N0G 2V0</p><p>January 3</p><p>Gisel Valdez<br>3758 Fallon Drive<br>Ottawa, ON K1Z 7B5</p><p>Dear Ms. Valdez,</p><p>Per my lease agreement, this letter constitutes written notice that I will be moving out of my apartment on February 28, the day my lease expires. — <span class=\"pos\">[1]</span> —. I have accepted a job offer in Toronto and will be relocating. Please let me know when I can expect the return of my security deposit.</p><p>— <span class=\"pos\">[2]</span> —. I have enjoyed my three years living here. I will gladly recommend the Cottonwood Apartments to anyone looking to rent in the area. One thing I have really liked is that I have never had to wait long to use a washer or dryer in the laundry room since there are plenty of machines available. — <span class=\"pos\">[3]</span> —. Most impressive, though, is your maintenance service. The crew members quickly addressed all issues, replacing smoke detectors, changing filters in my furnace, and weatherproofing windows before the cold season set in.</p><p>I will let you know my new address as soon as I have one. — <span class=\"pos\">[4]</span> —. You can always reach me on my mobile phone, 613-555-0129.</p><p>Sincerely,</p><p><i>Katsunori Sanu</i><br>Katsunori Sanu</p>"],"vi":"Katsunori Sanu\n860 Cottonwood Avenue, Căn hộ 5A\nWalkerton, ON N0G 2V0\n\nNgày 3 tháng 1\n\nGisel Valdez\n3758 Fallon Drive\nOttawa, ON K1Z 7B5\n\nKính gửi bà Valdez,\n\nTheo thỏa thuận thuê nhà của tôi, lá thư này được xem là thông báo bằng văn bản rằng tôi sẽ chuyển ra khỏi căn hộ vào ngày 28 tháng 2, ngày hợp đồng thuê của tôi hết hạn. — [1] —. Tôi đã nhận được lời mời làm việc tại Toronto và sẽ chuyển đến đó sinh sống. Xin vui lòng cho tôi biết khi nào tôi có thể nhận lại khoản tiền đặt cọc của mình.\n\n— [2] —. Tôi đã rất hài lòng với ba năm sinh sống tại đây. Tôi sẵn sàng giới thiệu Khu căn hộ Cottonwood cho bất kỳ ai đang tìm chỗ thuê trong khu vực. Một điều tôi thực sự thích là chưa bao giờ phải chờ lâu để sử dụng máy giặt hoặc máy sấy trong phòng giặt, vì luôn có nhiều máy sẵn sàng. — [3] —. Tuy nhiên, điều ấn tượng nhất chính là dịch vụ bảo trì của quý vị. Đội ngũ nhân viên đã nhanh chóng xử lý mọi vấn đề, từ thay đầu báo khói, thay bộ lọc lò sưởi, đến chống thấm cửa sổ trước khi mùa lạnh bắt đầu.\n\nTôi sẽ thông báo địa chỉ mới cho bà ngay khi có. — [4] —. Bà luôn có thể liên hệ với tôi qua điện thoại di động theo số 613-555-0129.\n\nTrân trọng,\nKatsunori Sanu","qs":[{"n":154,"q":"Who most likely is Ms. Valdez?","qvi":"Bà Valdez nhiều khả năng là ai?","opts":["Mr. Sanu’s lawyer","Mr. Sanu’s employer","A financial adviser","A property manager"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Per my lease agreement, this letter constitutes written notice that I will be moving out of my apartment\" (Theo thỏa thuận thuê nhà, thư này là thông báo bằng văn bản rằng tôi sẽ chuyển ra khỏi căn hộ) và \"Please let me know when I can expect the return of my security deposit\" (cho tôi biết khi nào nhận lại tiền đặt cọc) → bà Valdez là người quản lý căn hộ cho thuê.\n(A) Luật sư của ông Sanu\n(B) Chủ lao động của ông Sanu\n(C) Cố vấn tài chính\n(D) Quản lý bất động sản"},{"n":155,"q":"What does the letter indicate about the laundry room at Cottonwood Apartments?","qvi":"Bức thư cho biết điều gì về phòng giặt tại chung cư Cottonwood?","opts":["It has several washers and dryers.","It contains an oversized washer.","It is unavailable in the morning hours.","It is available to nonresidents for a fee."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"I have never had to wait long to use a washer or dryer in the laundry room since there are plenty of machines available\" (chưa bao giờ phải chờ lâu để dùng máy giặt hoặc máy sấy vì luôn có nhiều máy sẵn sàng) → plenty of machines = several washers and dryers.\n(A) Có nhiều máy giặt và máy sấy.\n(B) Có một máy giặt cỡ lớn.\n(C) Buổi sáng không sử dụng được.\n(D) Người không sống tại đây có thể dùng với phí riêng."},{"n":156,"q":"What is NOT mentioned about the maintenance crew?","qvi":"Điều gì KHÔNG được nhắc đến về đội bảo trì?","opts":["They repaired kitchen appliances.","They installed smoke detectors.","They put clean filters in the furnaces.","They took extra steps to keep the apartments warm."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"The crew members quickly addressed all issues, replacing smoke detectors (→ B), changing filters in my furnace (→ C), and weatherproofing windows before the cold season set in (→ D)\". Không nhắc đến việc sửa thiết bị nhà bếp → chọn A.\n(A) Họ đã sửa các thiết bị nhà bếp.\n(B) Họ đã lắp đặt máy báo khói.\n(C) Họ đã thay bộ lọc cho lò sưởi.\n(D) Họ đã làm thêm để giữ căn hộ ấm hơn."},{"n":157,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“I also appreciate that the landscaping is always well maintained.”","qvi":"Câu: “Tôi cũng rất trân trọng việc cảnh quan luôn được chăm sóc tốt.” nên đặt ở vị trí nào?","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Trước vị trí [3] có câu \"Một điều tôi thực sự thích là chưa bao giờ phải chờ để sử dụng máy giặt…\". Sau đó có câu: \"Tuy nhiên, điều ấn tượng nhất chính là dịch vụ bảo trì của quý vị.\"\n=> Câu nói về cảnh quan được chăm sóc tốt (\"also\" = cũng) là ý khen thêm, phù hợp ngay sau đoạn nói về các điểm tích cực, trước khi chuyển sang bảo trì.\n=> Đặt ở [3] là mạch văn tự nhiên nhất."}]},{"ns":[158,159],"head":"Questions 158-159 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Saral Malik &lt;smalik@bristek.co.uk&gt;</p><p><b>From:</b> Juna Schirmer &lt;jschirmer@diedrichindustries.de&gt;</p><p><b>Date:</b> 11 May</p><p><b>Subject:</b> RE: Information update</p><p><b>Attachment:</b> Brochure</p></div><p>Dear Mr. Malik:</p><p>Thank you for your e-mail. I can confirm that your shipment is now in transit. I apologise for the longer-than-expected wait. We recently started working with a new packaging supply company, and unfortunately, we experienced a miscommunication with them. The company supplied us with boxes that were too small to fulfill your order.</p><p>Since we have now cleared up the problem, you should receive your items within the next five business days. In addition, I have taken the liberty to attach a brochure of our new products with a detailed price list. I think you may be interested in some of our latest offerings.</p><p>Sincerely,</p><p>Juna Schirmer<br>Diedrich Industries</p>"],"vi":"Gửi: Saral Malik <smalik@bristek.co.uk>\nTừ: Juna Schirmer <jschirmer@diedrichindustries.de>\nNgày: 11 tháng 5\nChủ đề: RE: Cập nhật thông tin\nĐính kèm: Tờ giới thiệu (Brochure)\n\nKính gửi ông Malik,\n\nCảm ơn ông đã gửi email. Tôi xin xác nhận rằng đơn hàng của ông hiện đang được vận chuyển. Tôi xin lỗi vì sự chậm trễ kéo dài hơn dự kiến. Gần đây, chúng tôi đã bắt đầu hợp tác với một công ty cung ứng bao bì mới, và không may là đã xảy ra sự hiểu nhầm trong quá trình trao đổi thông tin. Công ty đó đã cung cấp cho chúng tôi những thùng hàng quá nhỏ, không đáp ứng được yêu cầu đơn hàng của ông.\n\nVì hiện nay chúng tôi đã khắc phục xong vấn đề, ông sẽ nhận được hàng trong vòng năm ngày làm việc tới. Ngoài ra, tôi cũng đính kèm một tập brochure giới thiệu các sản phẩm mới của chúng tôi, kèm theo bảng giá chi tiết. Tôi tin rằng ông có thể sẽ quan tâm đến một số sản phẩm mới nhất của chúng tôi.\n\nTrân trọng,\nJuna Schirmer\nDiedrich Industries","qs":[{"n":158,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của email là gì?","opts":["To explain the cause of a delay","To ask a question about a delivery","To confirm that payment was received","To request information about a product"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"I apologise for the longer-than-expected wait. We recently started working with a new packaging supply company… The company supplied us with boxes that were too small\" (xin lỗi vì chờ lâu hơn dự kiến; nhà cung cấp bao bì mới giao thùng quá nhỏ) → email giải thích nguyên nhân của sự chậm trễ.\n(A) Giải thích nguyên nhân chậm trễ\n(B) Hỏi về tình trạng giao hàng\n(C) Xác nhận đã nhận được thanh toán\n(D) Yêu cầu thông tin về một sản phẩm"},{"n":159,"q":"What did Ms. Schirmer provide with the e-mail?","qvi":"Cô Schirmer gửi kèm điều gì cùng email?","opts":["A checklist for packaging items correctly","A list of new items for purchase","Revised box specifications","Information about a shipping warehouse"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"I have taken the liberty to attach a brochure of our new products with a detailed price list\" (tôi đính kèm brochure giới thiệu các sản phẩm mới, kèm bảng giá chi tiết) → a list of new items for purchase.\n(A) Danh sách cần kiểm tra để đóng gói đúng cách\n(B) Danh sách các sản phẩm mới\n(C) Thông số hộp đã được sửa đổi\n(D) Thông tin về một nhà kho vận chuyển"}]},{"ns":[160,161],"head":"Questions 160-161 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Ervin Porter (10:04 A.M.)</b></p><p>Hello, Mindy. I’m preparing the paperwork for tomorrow’s open house at 431 Oakdale Lane. Is there anything else I need to prepare?</p></div><div class=\"msg\"><p><b>Mindy Warner (10:06 A.M.)</b></p><p>Could you buy the pastries we want to provide to potential buyers? I’ve already bought some bottles of water, but I won’t have time to stop by the bakery tomorrow.</p></div><div class=\"msg\"><p><b>Ervin Porter (10:08 A.M.)</b></p><p>Consider it done.</p></div><div class=\"msg\"><p><b>Mindy Warner (10:09 A.M.)</b></p><p>Thanks! See you tomorrow.</p></div>"],"vi":"Ervin Porter (10:04 sáng):\nChào Mindy. Tôi đang chuẩn bị giấy tờ cho buổi mở cửa tham quan nhà (open house) vào ngày mai tại 431 Oakdale Lane. Có điều gì khác tôi cần chuẩn bị nữa không?\n\nMindy Warner (10:06 sáng):\nBạn có thể mua các loại bánh ngọt mà chúng ta muốn phục vụ cho những người mua tiềm năng không? Tôi đã mua sẵn một số chai nước, nhưng ngày mai tôi sẽ không có thời gian ghé tiệm bánh.\n\nErvin Porter (10:08 sáng):\nCứ để tôi lo.\n\nMindy Warner (10:09 sáng):\nCảm ơn nhé! Hẹn gặp bạn ngày mai.","qs":[{"n":160,"q":"In what industry do Mr. Porter and Ms. Warner most likely work?","qvi":"Ông Porter và cô Warner có khả năng làm việc trong ngành nào?","opts":["Finance","Real estate","Home security","Food distribution"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"I’m preparing the paperwork for tomorrow’s open house at 431 Oakdale Lane\" (chuẩn bị giấy tờ cho buổi mở cửa tham quan nhà ngày mai) và \"potential buyers\" (người mua tiềm năng) → họ làm trong ngành bất động sản.\n(A) Tài chính\n(B) Bất động sản\n(C) An ninh nhà ở\n(D) Phân phối thực phẩm"},{"n":161,"q":"At 10:08 A.M., what does Mr. Porter most likely mean when he writes, “Consider it done”?","qvi":"Lúc 10:08 sáng, khi viết “Consider it done” (Cứ để tôi lo / Coi như xong), ông Porter có ý gì?","opts":["He has already met the buyers.","He has already delivered the bottles of water.","He will purchase some baked goods.","He will help complete some paperwork."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Cô Warner hỏi: \"Could you buy the pastries we want to provide to potential buyers?\" (Bạn có thể mua bánh ngọt để phục vụ người mua tiềm năng không?). Ông Porter trả lời \"Consider it done\" = đồng ý làm việc đó → ông sẽ mua bánh (pastries = baked goods).\n(A) Ông đã gặp người mua.\n(B) Ông đã giao nước uống.\n(C) Ông sẽ mua một số món nướng.\n(D) Ông sẽ giúp hoàn thành giấy tờ."}]},{"ns":[162,164],"head":"Questions 162-164 refer to the following blog post.","passages":["<h3>Games Now Blog</h3><p>A reader recently asked whether any innovations in 3-D printing are pertinent to the board game industry. — <span class=\"pos\">[1]</span> —. In this month’s post, I am happy to report that some of the latest advances do indeed offer exciting possibilities for board game production. Customization is a key benefit. — <span class=\"pos\">[2]</span> —. This allows components with intricate designs to be tailored to specific themes. Innovations in materials that can be loaded into a 3-D printer offer an unprecedented range of textures for game pieces, enhancing players’ tactile experiences. — <span class=\"pos\">[3]</span> —.</p><p>3-D printers are also getting faster. This is particularly relevant to small-batch production of board games. — <span class=\"pos\">[4]</span> —. Small batches are ideal for limited-edition games and new versions of existing games. Companies that exploit these advancements can give themselves an edge in a highly competitive market.</p><p>—Salvador Torres, June 1</p>"],"vi":"Blog Games Now\n\nGần đây, một độc giả đã đặt câu hỏi liệu những cải tiến trong công nghệ in 3D có liên quan đến ngành công nghiệp trò chơi bàn cờ (board game) hay không. — [1] —. Trong bài đăng tháng này, tôi rất vui được chia sẻ rằng một số tiến bộ mới nhất thực sự mang lại những khả năng đầy hứa hẹn cho việc sản xuất board game. Khả năng tùy chỉnh là một lợi ích then chốt. — [2] —. Điều này cho phép các bộ phận trò chơi có thiết kế tinh xảo được điều chỉnh phù hợp với những chủ đề cụ thể. Những đổi mới trong vật liệu có thể nạp vào máy in 3D mang lại một phạm vi kết cấu chưa từng có cho các quân cờ, giúp nâng cao trải nghiệm xúc giác của người chơi. — [3] —.\n\nCác máy in 3D cũng đang trở nên nhanh hơn. Điều này đặc biệt phù hợp với việc sản xuất board game theo lô nhỏ. — [4] —. Các lô nhỏ rất lý tưởng cho những phiên bản giới hạn và các phiên bản mới của những trò chơi hiện có. Những công ty tận dụng được các tiến bộ này có thể tạo cho mình lợi thế trong một thị trường cạnh tranh cao.\n\n— Salvador Torres, ngày 1 tháng 6","qs":[{"n":162,"q":"What is most likely true about Mr. Torres?","qvi":"Điều gì có khả năng đúng nhất về ông Torres?","opts":["He works for a company that makes 3-D printers.","He writes a weekly blog about video game technology.","He began his career as a graphic artist.","He researched the answer to a question about 3-D printing."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"A reader recently asked whether any innovations in 3-D printing are pertinent to the board game industry… In this month’s post, I am happy to report that…\" (Một độc giả hỏi liệu cải tiến in 3D có liên quan đến board game không… Trong bài tháng này tôi vui được chia sẻ…) → ông đã tìm hiểu để trả lời câu hỏi của độc giả. (B) sai: blog hàng tháng (this month’s post) và về board game, không phải video game.\n(A) Ông làm cho công ty sản xuất máy in 3D.\n(B) Ông viết blog hằng tuần về công nghệ game.\n(C) Ông bắt đầu sự nghiệp là họa sĩ đồ họa.\n(D) Ông đã tìm hiểu câu trả lời về công nghệ in 3D."},{"n":163,"q":"What is indicated about the small-batch production of games?","qvi":"Điều gì được đề cập về sản xuất số lượng nhỏ trò chơi?","opts":["It is more common than mass production.","It costs the same with or without 3-D printing.","It is most often used to make children’s games.","It is useful in making multiple versions of a game."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Small batches are ideal for limited-edition games and new versions of existing games\" (Các lô nhỏ rất lý tưởng cho phiên bản giới hạn và phiên bản mới của những trò chơi hiện có) → hữu ích khi làm nhiều phiên bản của một trò chơi.\n(A) Phổ biến hơn sản xuất hàng loạt.\n(B) Chi phí như nhau dù có hay không dùng in 3D.\n(C) Thường dùng để làm đồ chơi trẻ em.\n(D) Hữu ích khi tạo nhiều phiên bản khác nhau."},{"n":164,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Companies can even select materials that are biodegradable.”","qvi":"Câu “Các công ty thậm chí có thể chọn những vật liệu phân hủy sinh học.” nên đặt ở đâu?","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Trước vị trí [3], bài viết nói: \"Những đổi mới trong vật liệu có thể được đưa vào máy in 3D mang lại nhiều lựa chọn về kết cấu cho các mảnh trò chơi, nâng cao trải nghiệm xúc giác của người chơi.\"\nSau đó cần một câu bổ sung cụ thể về vật liệu => hợp lý để thêm: \"Companies can even select materials that are biodegradable.\"\nSau [3], bài chuyển sang tốc độ in 3D & sản xuất lô nhỏ, không còn nói về vật liệu => [3] là vị trí chuẩn nhất."}]},{"ns":[165,168],"head":"Questions 165-168 refer to the following notice.","passages":["<h3>Stay in Style!</h3><p>QRN Airport invites travelers to experience our new Repose Lounge. Just like Repose Lounges in other airports, it offers a peaceful, comfortable space where you can unwind if you have a long layover between flights, have arrived early for a flight, or are dealing with an unexpected delay. The Repose Lounge is open daily between 5:00 A.M. and 8:30 P.M. and features the following amenities.</p><ul><li>✓ A private conference room for meetings and calls</li><li>✓ Printing and copying services</li><li>✓ Wi-Fi and charging stations</li><li>✓ Beverages, baked goods, and snacks</li><li>✓ A selection of current newspapers and magazines</li></ul><p>Repose Lounge passes are available for $180 and are valid for one year from the date of purchase. To access a Repose Lounge, guests must present a government-issued photo ID and a same-day boarding pass.</p><p>To celebrate the grand opening at QRN Airport, we are offering Repose Lounge passes at half price between March 15 and March 30. To obtain a pass or make a reservation, go to www.qrnairport.com/repose or visit the service desk just outside the lounge in terminal B.</p>"],"vi":"Nghỉ Ngơi Phong Cách!\n\nSân bay QRN trân trọng mời hành khách đến trải nghiệm Phòng chờ Repose mới của chúng tôi. Tương tự như các phòng chờ Repose tại những sân bay khác, nơi đây mang đến không gian yên tĩnh và thoải mái, giúp bạn thư giãn nếu phải quá cảnh lâu giữa các chuyến bay, đến sân bay sớm, hoặc gặp phải sự chậm trễ không mong muốn. Phòng chờ Repose mở cửa hằng ngày từ 5:00 sáng đến 8:30 tối và cung cấp các tiện ích sau:\n✓ Phòng họp riêng dành cho các cuộc họp và cuộc gọi\n✓ Dịch vụ in ấn và sao chép\n✓ Wi-Fi và trạm sạc thiết bị\n✓ Đồ uống, bánh nướng và đồ ăn nhẹ\n✓ Bộ sưu tập các báo và tạp chí mới nhất\n\nThẻ sử dụng Phòng chờ Repose có giá 180 đô la Mỹ và có hiệu lực trong vòng một năm kể từ ngày mua. Để vào Phòng chờ Repose, khách cần xuất trình giấy tờ tùy thân có ảnh do chính phủ cấp và thẻ lên máy bay trong ngày.\n\nNhân dịp khai trương tại sân bay QRN, chúng tôi đang giảm giá 50% thẻ Phòng chờ Repose trong khoảng thời gian từ ngày 15 tháng 3 đến ngày 30 tháng 3. Để mua thẻ hoặc đặt chỗ, vui lòng truy cập www.qrnairport.com/repose hoặc đến quầy dịch vụ ngay bên ngoài phòng chờ tại nhà ga B.","qs":[{"n":165,"q":"The word “space” in paragraph 1, line 2, is closest in meaning to","qvi":"Từ “space” ở đoạn 1, dòng 2 gần nghĩa nhất với","opts":["distance","area","condition","vacancy"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"…it offers a peaceful, comfortable space where you can unwind…\" → Ở đây \"space\" mang nghĩa không gian/khu vực để thư giãn, không phải khoảng cách, điều kiện hay chỗ trống.\n(A) khoảng cách\n(B) khu vực\n(C) điều kiện\n(D) khoảng trống / vị trí trống"},{"n":166,"q":"What is indicated about the Repose Lounge at QRN Airport?","qvi":"Điều gì được đề cập về phòng chờ Repose Lounge tại sân bay QRN?","opts":["It is open 24 hours a day.","It is located in an airport hotel.","It is only for travelers flying internationally.","It has printers available."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Trong danh sách tiện ích có \"Printing and copying services\" (Dịch vụ in ấn và sao chép) → phòng chờ có máy in. (A) sai vì chỉ mở từ 5:00 sáng đến 8:30 tối.\n(A) Mở cửa 24/24.\n(B) Nằm trong khách sạn sân bay.\n(C) Chỉ dành cho khách bay quốc tế.\n(D) Có máy in."},{"n":167,"q":"What is offered to Repose Lounge visitors?","qvi":"Du khách tại Repose Lounge được cung cấp gì?","opts":["Refreshments","Books","Movies","Computers"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"Beverages, baked goods, and snacks\" (Đồ uống, bánh nướng và đồ ăn nhẹ) = refreshments. Phòng chờ có báo và tạp chí, không phải sách.\n(A) Đồ ăn/uống nhẹ\n(B) Sách\n(C) Phim\n(D) Máy tính"},{"n":168,"q":"According to the notice, what will happen between March 15 and March 30?","qvi":"Theo thông báo, điều gì sẽ diễn ra từ ngày 15–30 tháng 3?","opts":["Renovations will be completed.","A service-desk representative will be hired.","Terminal B will be closed.","A discount will be offered."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"we are offering Repose Lounge passes at half price between March 15 and March 30\" (chúng tôi giảm giá 50% thẻ Phòng chờ Repose từ ngày 15 đến 30 tháng 3) → half price = a discount.\n(A) Việc cải tạo sẽ hoàn tất.\n(B) Sẽ tuyển một nhân viên quầy dịch vụ.\n(C) Nhà ga B sẽ đóng cửa.\n(D) Có ưu đãi giảm giá."}]},{"ns":[169,171],"head":"Questions 169-171 refer to the following article.","passages":["<h3>Be Green Aware in Misford</h3><p>March 26—The village of Misford will celebrate its annual Green Awareness Week in April. This event is coordinated by the village’s Green Earth Committee and is part of a long-term effort to keep Misford green and clean.</p><p>The activities will start on Sunday, April 1, with a cleanup of the Misford Stream trails. Two teams of volunteers will work on either side of the stream to pick up any rubbish and clear the paths of fallen branches.</p><p>On Monday, residents are encouraged to walk along the trails and take photographs. The Green Earth Committee is accepting digital images and will select the ten best to post to the village Web site.</p><p>On Tuesday and Wednesday, residents who come to the village hall can pick up cloth bags to replace single-use plastic shopping bags, the sale of which will be banned in our county starting next month.</p><p>On Thursday, the Misford Library will host a panel on ways to conserve energy and reduce and recycle waste. These are fundamental goals of the village and its Green Earth Committee. Children are welcome to attend with an adult.</p><p>Finally, on Saturday, 500 tree saplings will be offered to residents free of charge. The trees are native to the region and can be planted in private gardens or in some public areas.</p>"],"vi":"Nâng Cao Ý Thức Xanh tại Misford\n\nNgày 26 tháng 3 — Ngôi làng Misford sẽ tổ chức Tuần lễ Nâng cao Ý thức Xanh thường niên vào tháng Tư. Sự kiện này do Ủy ban Green Earth của làng điều phối và là một phần trong nỗ lực dài hạn nhằm giữ cho Misford luôn xanh và sạch.\n\nCác hoạt động sẽ bắt đầu vào Chủ nhật, ngày 1 tháng 4, với chiến dịch dọn dẹp các tuyến đường mòn của suối Misford. Hai nhóm tình nguyện viên sẽ làm việc ở hai bên bờ suối để nhặt rác và dọn dẹp các cành cây gãy chắn lối đi.\n\nVào thứ Hai, người dân được khuyến khích đi dạo dọc theo các con đường mòn và chụp ảnh. Ủy ban Green Earth sẽ tiếp nhận hình ảnh kỹ thuật số và chọn mười bức ảnh đẹp nhất để đăng lên trang web của làng.\n\nVào thứ Ba và thứ Tư, cư dân đến tòa thị chính có thể nhận các túi vải để thay thế túi nhựa dùng một lần, loại túi sẽ bị cấm bán trong quận của chúng ta kể từ tháng tới.\n\nVào thứ Năm, thư viện Misford sẽ tổ chức một buổi tọa đàm về các cách tiết kiệm năng lượng, giảm thiểu rác thải và tái chế. Đây là những mục tiêu cốt lõi của làng và Ủy ban Green Earth. Trẻ em được chào đón tham dự cùng với người lớn.\n\nCuối cùng, vào thứ Bảy, 500 cây non sẽ được phát miễn phí cho người dân. Những cây này là loài bản địa của khu vực và có thể được trồng trong vườn nhà riêng hoặc tại một số khu vực công cộng.","qs":[{"n":169,"q":"What will be posted to Misford’s Web site?","qvi":"Điều gì sẽ được đăng lên trang web của Misford?","opts":["An event registration page","Maps of Misford’s hiking trails","Photographs of a specified area","A new-resident welcome packet"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"residents are encouraged to walk along the trails and take photographs. The Green Earth Committee is accepting digital images and will select the ten best to post to the village Web site\" (người dân chụp ảnh dọc các con đường mòn; Ủy ban chọn mười bức đẹp nhất đăng lên trang web của làng) → ảnh của một khu vực cụ thể (các đường mòn).\n(A) Trang đăng ký sự kiện\n(B) Bản đồ các đường mòn đi bộ đường dài\n(C) Ảnh của một khu vực cụ thể\n(D) Gói thông tin chào đón cư dân mới"},{"n":170,"q":"What is one goal of the Green Earth Committee?","qvi":"Một mục tiêu của Ủy ban Green Earth là gì?","opts":["To supervise children","To eliminate regulations","To encourage waste reduction","To advise village council members"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"a panel on ways to conserve energy and reduce and recycle waste. These are fundamental goals of the village and its Green Earth Committee\" (các cách tiết kiệm năng lượng, giảm thiểu rác thải và tái chế — đây là những mục tiêu cốt lõi của làng và Ủy ban Green Earth) → khuyến khích giảm rác thải.\n(A) Giám sát trẻ em\n(B) Loại bỏ các quy định\n(C) Khuyến khích giảm rác thải\n(D) Tư vấn cho hội đồng thị trấn"},{"n":171,"q":"What is NOT mentioned as a planned activity during Green Awareness Week?","qvi":"Điều nào KHÔNG được nhắc đến như một hoạt động trong Tuần lễ Nâng cao Ý thức Xanh?","opts":["Planting native trees","Riding bicycles on a trail","Participating in a cleanup effort","Distributing cloth bags"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: (A) \"500 tree saplings will be offered… The trees are native to the region and can be planted…\" (phát cây non bản địa để trồng); (C) \"Two teams of volunteers will work… to pick up any rubbish\" (dọn rác); (D) \"residents… can pick up cloth bags\" (nhận túi vải). Hoạt động trên đường mòn là đi dạo và chụp ảnh, không có đạp xe → chọn B.\n(A) Trồng cây bản địa\n(B) Đạp xe trên đường mòn\n(C) Tham gia dọn rác\n(D) Phát túi vải"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Catherine Radiss [9:12 A.M.]</b></p><p>Good morning, Gina and Jay. Do you have a moment?</p></div><div class=\"msg\"><p><b>Gina Karp [9:13 A.M.]</b></p><p>Sure.</p></div><div class=\"msg\"><p><b>Catherine Radiss [9:14 A.M.]</b></p><p>The department bulletin is going out tomorrow by e-mail. Do you have anything that you would like to add to it? We don’t have a lot of news this month.</p></div><div class=\"msg\"><p><b>Gina Karp [9:15 A.M.]</b></p><p>How soon do you need it?</p></div><div class=\"msg\"><p><b>Jay Nusaputra [9:16 A.M.]</b></p><p>I do have something, Catherine. It’s a quick reminder summarizing the process for requesting vacation time. Nothing else at the moment.</p></div><div class=\"msg\"><p><b>Catherine Radiss [9:17 A.M.]</b></p><p>I’ll need anything you have by the end of the day today.</p></div><div class=\"msg\"><p><b>Gina Karp [9:18 A.M.]</b></p><p>I’m afraid there’s nothing I can get to you that quickly. I’m preparing for a full afternoon of interviews. I’ll be sure to have a report on current projects ready for the next bulletin.</p></div><div class=\"msg\"><p><b>Jay Nusaputra [9:19 A.M.]</b></p><p>I’ll just need an hour or so to finish it up, as I have no client meetings this morning. I can send you the reminder before lunch.</p></div>"],"vi":"Catherine Radiss (9:12 sáng):\nChào buổi sáng, Gina và Jay. Hai bạn có rảnh một chút không?\n\nGina Karp (9:13 sáng):\nCó chứ.\n\nCatherine Radiss (9:14 sáng):\nBản tin của phòng ban sẽ được gửi qua email vào ngày mai. Hai bạn có nội dung nào muốn thêm vào không? Tháng này chúng ta không có nhiều tin tức.\n\nGina Karp (9:15 sáng):\nBạn cần gấp trong bao lâu?\n\nJay Nusaputra (9:16 sáng):\nTôi có một nội dung, Catherine. Đó là một thông báo ngắn tóm tắt quy trình xin nghỉ phép. Hiện tại không có gì thêm.\n\nCatherine Radiss (9:17 sáng):\nTôi cần nhận tất cả nội dung trước khi kết thúc ngày hôm nay.\n\nGina Karp (9:18 sáng):\nTôi e là không có gì có thể gửi cho bạn nhanh như vậy. Tôi đang chuẩn bị cho cả buổi chiều phỏng vấn. Tôi sẽ đảm bảo có một báo cáo về các dự án hiện tại cho bản tin tiếp theo.\n\nJay Nusaputra (9:19 sáng):\nTôi chỉ cần khoảng một giờ để hoàn thành, vì sáng nay tôi không có cuộc họp với khách hàng. Tôi có thể gửi cho bạn bản nhắc nhở trước giờ ăn trưa.","qs":[{"n":172,"q":"What are the writers discussing?","qvi":"Họ đang bàn về vấn đề gì?","opts":["An interview request","An office newsletter","A project evaluation","A vacation itinerary"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"The department bulletin is going out tomorrow by e-mail. Do you have anything that you would like to add to it?\" (Bản tin của phòng ban sẽ được gửi qua email vào ngày mai. Các bạn có nội dung nào muốn thêm vào không?) → department bulletin = an office newsletter.\n(A) Yêu cầu phỏng vấn\n(B) Bản tin nội bộ\n(C) Đánh giá dự án\n(D) Lịch trình kỳ nghỉ"},{"n":173,"q":"At 9:16 A.M., what does Mr. Nusaputra most likely mean when he writes, “I do have something”?","qvi":"Lúc 9:16 sáng, ông Nusaputra có ý gì khi viết: “I do have something” (Tôi có một nội dung đây)?","opts":["He has received a colleague’s reminder.","He must take time off from work.","He can make a contribution.","He has finished an assignment."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Catherine hỏi \"Do you have anything that you would like to add to it?\". Ông Nusaputra trả lời \"I do have something… It’s a quick reminder summarizing the process for requesting vacation time\" (Tôi có một nội dung… là thông báo ngắn tóm tắt quy trình xin nghỉ phép) → ông có thể đóng góp một bài cho bản tin. (D) sai vì lúc 9:19 ông nói vẫn cần khoảng một giờ để hoàn thành.\n(A) Ông nhận được lời nhắc từ đồng nghiệp.\n(B) Ông cần xin nghỉ phép.\n(C) Ông có thể đóng góp một nội dung.\n(D) Ông đã hoàn thành một nhiệm vụ."},{"n":174,"q":"When will Ms. Karp’s report most likely be sent to the staff?","qvi":"Khi nào báo cáo của cô Karp có khả năng sẽ được gửi cho nhân viên?","opts":["In an hour","In a day","In a week","In a month"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Cô Karp: \"I’ll be sure to have a report on current projects ready for the next bulletin\" (sẽ có báo cáo cho bản tin tiếp theo). Catherine: \"We don’t have a lot of news this month\" (Tháng này không có nhiều tin) → bản tin ra hằng tháng, bản tin này gửi ngày mai nên bản tin tiếp theo khoảng một tháng nữa → In a month.\n(A) Trong một giờ nữa\n(B) Trong một ngày\n(C) Trong một tuần\n(D) Trong một tháng"},{"n":175,"q":"What will Mr. Nusaputra probably do next?","qvi":"Ông Nusaputra có lẽ sẽ làm gì tiếp theo?","opts":["Take a lunch break","Meet with a client","Write to Ms. Karp","Finish drafting a reminder"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"I’ll just need an hour or so to finish it up, as I have no client meetings this morning. I can send you the reminder before lunch.\" (Tôi chỉ cần khoảng một giờ để hoàn thành, vì sáng nay không có cuộc họp với khách hàng. Tôi có thể gửi bản nhắc nhở trước giờ ăn trưa.) → việc tiếp theo là hoàn tất bản nhắc nhở. (B) sai vì sáng nay ông không có cuộc họp với khách hàng.\n(A) Nghỉ trưa\n(B) Gặp một khách hàng\n(C) Viết email cho cô Karp\n(D) Hoàn tất bản nhắc nhở"}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following e-mails.","passages":["<div class=\"hdr\"><p><b>To:</b> All Staff</p><p><b>From:</b> Liza Pacurar</p><p><b>Subject:</b> Special issue</p><p><b>Date:</b> November 12</p></div><p>Dear All,</p><p>Once again, I’d like to express my gratitude for the great efforts you have made to help us meet the publication deadline for our annual special issue of <i>Best Design Insights</i> magazine. What follows is a summary of the main points we discussed at today’s meeting.</p><ul><li>Karine Xu reported that advertisers have expressed heightened interest in the issue, so the deadline for submitting advertisements will be extended one week.</li><li>For this issue, we will use our alternate printing service, Sklarr Press, to meet our tight delivery deadline.</li><li>We’ve gotten approval to increase the budget so that Mark Janskee’s team can work overtime to review the pages with special layout components, in particular multiple photographs arranged in a photomontage. Mark will then submit a custom design request to the printer.</li><li>The draft of the special issue is longer than we want. So, we reduced the page total by condensing the text of our interview with animation artist Bret Lusk.</li></ul><p>Liza Pacurar, Editor<br>Best Design Publications</p>","<div class=\"hdr\"><p><b>To:</b> Liza Pacurar</p><p><b>From:</b> Karine Xu</p><p><b>Subject:</b> RE: Special issue</p><p><b>Date:</b> November 14</p></div><p>Hi Liza,</p><p>I’m happy with the plan to use Sklarr Press to print our magazine’s special issue, just as we did last year. I’m confident they can meet our publication deadline. Our customization request will probably incur an extra fee, but any added expense should be offset by the expected boost in advertising revenue.</p><p>Next on my agenda is to remind our subscribers that they have this extra issue to look forward to. I’ll let them know via e-mail.</p><p>Karine Xu, Marketing Coordinator<br>Best Design Publications</p>"],"vi":"EMAIL 1\nGửi: Toàn thể nhân viên\nTừ: Liza Pacurar\nTiêu đề: Số đặc biệt\nNgày: 12 tháng 11\n\nGửi mọi người,\n\nMột lần nữa, tôi xin bày tỏ lời cảm ơn về những nỗ lực tuyệt vời mà các bạn đã thực hiện để giúp chúng ta đáp ứng kịp thời hạn xuất bản cho số đặc biệt thường niên của tạp chí Best Design Insights. Dưới đây là bản tóm tắt những điểm chính mà chúng ta đã thảo luận trong cuộc họp hôm nay.\n\n• Karine Xu báo cáo rằng các nhà quảng cáo đã thể hiện mức độ quan tâm cao hơn đối với số báo này, vì vậy thời hạn nộp quảng cáo sẽ được gia hạn thêm một tuần.\n\n• Đối với số báo này, chúng ta sẽ sử dụng dịch vụ in ấn thay thế là Sklarr Press để đáp ứng thời hạn giao hàng gấp.\n\n• Chúng ta đã nhận được sự phê duyệt để tăng ngân sách, cho phép nhóm của Mark Janskee làm thêm giờ nhằm rà soát các trang có bố cục đặc biệt, đặc biệt là nhiều bức ảnh được sắp xếp theo dạng ảnh ghép (photomontage). Sau đó, Mark sẽ gửi yêu cầu thiết kế tùy chỉnh cho nhà in.\n\n• Bản thảo của số đặc biệt dài hơn mong muốn, vì vậy chúng ta đã giảm tổng số trang bằng cách rút gọn phần nội dung bài phỏng vấn với họa sĩ hoạt hình Bret Lusk.\n\nLiza Pacurar, Biên tập viên\nBest Design Publications\n\nEMAIL 2\nGửi: Liza Pacurar\nTừ: Karine Xu\nTiêu đề: RE: Số đặc biệt\nNgày: 14 tháng 11\n\nChào Liza,\n\nTôi rất hài lòng với kế hoạch sử dụng Sklarr Press để in số đặc biệt của tạp chí, giống như cách chúng ta đã làm vào năm ngoái. Tôi tin tưởng rằng họ có thể đáp ứng đúng thời hạn xuất bản của chúng ta. Yêu cầu tùy chỉnh của chúng ta có thể sẽ phát sinh thêm chi phí, nhưng bất kỳ khoản chi phí tăng thêm nào cũng nên được bù đắp bởi mức tăng doanh thu quảng cáo dự kiến.\n\nViệc tiếp theo trong kế hoạch của tôi là nhắc nhở các độc giả đã đăng ký rằng họ sắp có một số báo bổ sung để mong đợi. Tôi sẽ thông báo cho họ qua email.\n\nKarine Xu, Điều phối viên Marketing\nBest Design Publications","qs":[{"n":176,"q":"What is the purpose of the first e-mail?","qvi":"Mục đích của email đầu tiên là gì?","opts":["To introduce a new staff member","To provide a summary of a meeting","To propose that a project be delayed","To request work samples from an artist"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email 1: \"What follows is a summary of the main points we discussed at today’s meeting.\" (Dưới đây là bản tóm tắt những điểm chính mà chúng ta đã thảo luận trong cuộc họp hôm nay.)\n(A) Giới thiệu nhân viên mới\n(B) Tóm tắt nội dung một cuộc họp\n(C) Đề xuất hoãn dự án\n(D) Yêu cầu mẫu tác phẩm từ một nghệ sĩ"},{"n":177,"q":"In the first e-mail, what is indicated about the magazine’s special issue?","qvi":"Trong email đầu tiên, điều gì được nói về số đặc biệt của tạp chí?","opts":["It will include an interview with an animator.","It will only be available online.","It will reprint articles from previous issues.","It will contain fewer advertisements than expected."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Email 1: \"...condensing the text of our interview with animation artist Bret Lusk.\" (rút gọn phần nội dung bài phỏng vấn với họa sĩ hoạt hình Bret Lusk) → số đặc biệt có bài phỏng vấn một họa sĩ hoạt hình (animation artist = animator). (D) sai: nhà quảng cáo quan tâm nhiều hơn, hạn nộp quảng cáo được gia hạn.\n(A) Sẽ có bài phỏng vấn với một họa sĩ hoạt hình.\n(B) Chỉ được xuất bản trực tuyến.\n(C) Sẽ đăng lại bài của các số trước.\n(D) Sẽ ít quảng cáo hơn dự kiến."},{"n":178,"q":"In the second e-mail, what is mentioned about Sklarr Press?","qvi":"Trong email thứ hai, điều gì được nhắc đến về Sklarr Press?","opts":["It specializes in large orders.","It used to be owned by Ms. Xu.","It has printed issues of Best Design Insights in the past.","It is the oldest print service in the region."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email 2: \"I’m happy with the plan to use Sklarr Press to print our magazine’s special issue, just as we did last year.\" (Tôi rất hài lòng với kế hoạch dùng Sklarr Press để in số đặc biệt, giống như chúng ta đã làm năm ngoái.) → Sklarr Press đã từng in tạp chí này.\n(A) Chuyên nhận đơn hàng lớn.\n(B) Từng thuộc sở hữu của cô Xu.\n(C) Từng in tạp chí Best Design Insights trước đây.\n(D) Là dịch vụ in lâu đời nhất khu vực."},{"n":179,"q":"What most likely will add to the cost of printing this year’s special issue?","qvi":"Điều gì nhiều khả năng sẽ làm tăng chi phí in số đặc biệt năm nay?","opts":["A shortened deadline","An increase in advertisements","The large number of printed pages","The placement of photographs on pages"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp 2 email. Email 1: nhóm của Mark rà soát các trang có bố cục đặc biệt, \"in particular multiple photographs arranged in a photomontage. Mark will then submit a custom design request to the printer.\" Email 2: \"Our customization request will probably incur an extra fee\" (Yêu cầu tùy chỉnh có thể sẽ phát sinh thêm chi phí) → chi phí tăng do cách bố trí ảnh trên trang.\n(A) Hạn chót bị rút ngắn\n(B) Quảng cáo tăng\n(C) Số trang in nhiều\n(D) Cách sắp xếp ảnh trên các trang"},{"n":180,"q":"What will Ms. Xu probably do next?","qvi":"Cô Xu có khả năng sẽ làm gì tiếp theo?","opts":["Send subscribers a reminder","Reduce the length of some articles","Survey staff about preferences for the cover design","Meet with a team of graphic designers"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Email 2: \"Next on my agenda is to remind our subscribers that they have this extra issue to look forward to. I’ll let them know via e-mail.\" (Việc tiếp theo là nhắc các độc giả đã đăng ký... Tôi sẽ thông báo qua email.)\n(A) Gửi lời nhắc cho người đăng ký\n(B) Rút ngắn một số bài viết\n(C) Khảo sát nhân viên về thiết kế bìa\n(D) Họp với nhóm thiết kế đồ họa"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following e-mails.","passages":["<div class=\"hdr\"><p><b>To:</b> Shaan Iqbal</p><p><b>From:</b> Maggie Rosen</p><p><b>Date:</b> July 12</p><p><b>Subject:</b> Office celebration</p></div><p>Dear Shaan,</p><p>As you know, we have planned an office party in honor of Walter Weber for July 28. I was pleased to learn from my assistant that you will be attending, and I was wondering if you would be willing to say a few words about Walter during the event. He founded this firm 25 years ago and has always been an integral part of it. Since you work closely with him in the finance department, I thought you might be well positioned to talk about him as a mentor, worker, and leader. The party will begin at 6 P.M. The speeches will start at 7:30 P.M. and continue for about an hour. I am sure everyone, not just Walter, would love to hear from you! Please let me know as soon as possible.</p><p>Many thanks,</p><p>Maggie Rosen<br>Director of Human Resources<br>Weber Richter Associates</p>","<div class=\"hdr\"><p><b>To:</b> Maggie Rosen</p><p><b>From:</b> Shaan Iqbal</p><p><b>Date:</b> July 12</p><p><b>Subject:</b> Re: Office celebration</p></div><p>Dear Maggie,</p><p>Thanks for thinking of me! I have really been looking forward to Walter’s party, and it would be a tremendous honor for me to speak about him. Walter actually interviewed me when I first applied for a job with the company fifteen years ago. His guidance over the years has been invaluable.</p><p>Please note that I have a meeting with the sales team scheduled for 5 P.M. that day, so I should arrive at the party just as the speeches begin. If you schedule me to deliver one of the later speeches, there should be no problem.</p><p>Sincerely,</p><p>Shaan Iqbal<br>Weber Richter Associates</p>"],"vi":"EMAIL 1\nGửi: Shaan Iqbal\nTừ: Maggie Rosen\nNgày: 12 tháng 7\nTiêu đề: Tiệc mừng tại văn phòng\n\nChào Shaan,\n\nNhư bạn đã biết, chúng ta đã lên kế hoạch tổ chức một buổi tiệc tại văn phòng để vinh danh Walter Weber vào ngày 28 tháng 7. Tôi rất vui khi được biết từ trợ lý của mình rằng bạn sẽ tham dự, và tôi muốn hỏi liệu bạn có sẵn lòng phát biểu vài lời về Walter trong buổi tiệc hay không. Ông ấy đã thành lập công ty này cách đây 25 năm và luôn là một phần không thể thiếu của công ty. Vì bạn làm việc rất gần gũi với ông ấy trong bộ phận tài chính, tôi nghĩ bạn là người rất phù hợp để nói về ông ấy với tư cách là một người cố vấn, một đồng nghiệp và một nhà lãnh đạo. Buổi tiệc sẽ bắt đầu lúc 6 giờ tối. Phần phát biểu sẽ bắt đầu lúc 7 giờ 30 tối và kéo dài khoảng một giờ. Tôi tin chắc rằng mọi người, không chỉ riêng Walter, đều rất mong được nghe bạn chia sẻ. Vui lòng cho tôi biết sớm nhất có thể.\n\nXin cảm ơn rất nhiều,\n\nMaggie Rosen\nGiám đốc Nhân sự\nWeber Richter Associates\n\nEMAIL 2\nGửi: Maggie Rosen\nTừ: Shaan Iqbal\nNgày: 12 tháng 7\nTiêu đề: Re: Tiệc mừng tại văn phòng\n\nChào Maggie,\n\nCảm ơn chị đã nghĩ đến tôi! Tôi thực sự đã rất mong chờ buổi tiệc dành cho Walter, và đối với tôi, được phát biểu về ông ấy là một vinh dự to lớn. Thực tế, Walter là người đã trực tiếp phỏng vấn tôi khi tôi lần đầu nộp đơn xin việc vào công ty cách đây mười lăm năm. Sự chỉ dẫn của ông trong suốt những năm qua là vô cùng quý giá đối với tôi.\n\nXin lưu ý rằng tôi có một cuộc họp với đội ngũ bán hàng được lên lịch vào lúc 5 giờ chiều hôm đó, vì vậy tôi sẽ đến buổi tiệc đúng vào lúc các bài phát biểu bắt đầu. Nếu chị sắp xếp cho tôi phát biểu ở một trong những phần sau, thì sẽ không có vấn đề gì cả.\n\nTrân trọng,\n\nShaan Iqbal\nWeber Richter Associates","qs":[{"n":181,"q":"Why did Ms. Rosen send an e-mail to Mr. Iqbal?","qvi":"Vì sao cô Rosen gửi email cho ông Iqbal?","opts":["To invite him to a celebration","To ask for help organizing a party","To inform him about a colleague’s accomplishments","To ask him to give a speech at an event"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email 1: \"I was wondering if you would be willing to say a few words about Walter during the event.\" (tôi muốn hỏi liệu bạn có sẵn lòng phát biểu vài lời về Walter trong buổi tiệc không). (A) sai: ông Iqbal đã xác nhận tham dự từ trước (\"you will be attending\").\n(A) Mời ông dự tiệc\n(B) Nhờ ông hỗ trợ tổ chức tiệc\n(C) Báo tin về thành tựu của một đồng nghiệp\n(D) Nhờ ông phát biểu tại một sự kiện"},{"n":182,"q":"What is indicated about Mr. Iqbal?","qvi":"Điều gì được nhắc đến về ông Iqbal?","opts":["He regularly gives presentations.","He will reschedule a meeting with the sales team.","He has been with the company for 25 years.","He works in the finance department."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email 1: \"Since you work closely with him in the finance department\" (Vì bạn làm việc rất gần gũi với ông ấy trong bộ phận tài chính). (C) sai: 25 năm là thời gian ông Weber thành lập công ty; ông Iqbal vào công ty 15 năm trước.\n(A) Ông thường xuyên thuyết trình.\n(B) Ông sẽ dời lịch họp với đội bán hàng.\n(C) Ông đã làm ở công ty được 25 năm.\n(D) Ông làm trong bộ phận tài chính."},{"n":183,"q":"What is indicated about Mr. Weber?","qvi":"Điều gì được nói về ông Weber?","opts":["He recently opened a new branch office.","He is planning to sell the company.","He was directly involved with Mr. Iqbal’s hiring.","He will arrive late to the party on July 28."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email 2: \"Walter actually interviewed me when I first applied for a job with the company fifteen years ago.\" (Walter là người đã trực tiếp phỏng vấn tôi khi tôi lần đầu nộp đơn xin việc vào công ty) → ông Weber trực tiếp tham gia tuyển dụng ông Iqbal. (D) sai: người đến muộn là ông Iqbal.\n(A) Gần đây mở chi nhánh mới.\n(B) Đang dự định bán công ty.\n(C) Trực tiếp tham gia vào việc tuyển dụng ông Iqbal.\n(D) Sẽ đến muộn buổi tiệc ngày 28/7."},{"n":184,"q":"In the second e-mail, the word “note” in paragraph 2, line 1, is closest in meaning to","qvi":"Trong email thứ hai, từ “note” ở đoạn 2, dòng 1 gần nghĩa nhất với","opts":["spread out","be aware","show","mention"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email 2: \"Please note that I have a meeting with the sales team...\" (Xin lưu ý rằng tôi có một cuộc họp...) → \"please note\" = hãy lưu ý / nắm được → note = be aware.\n(A) phân tán\n(B) lưu ý, biết\n(C) cho thấy\n(D) đề cập"},{"n":185,"q":"At approximately what time does Mr. Iqbal plan to arrive at the party?","qvi":"Ông Iqbal dự định đến bữa tiệc vào khoảng mấy giờ?","opts":["5:00 P.M.","6:00 P.M.","7:30 P.M.","8:30 P.M."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Kết hợp 2 email. Email 2: \"I should arrive at the party just as the speeches begin.\" (tôi sẽ đến buổi tiệc đúng lúc các bài phát biểu bắt đầu) + Email 1: \"The speeches will start at 7:30 P.M.\" → ông đến khoảng 7:30 tối. (A) 5:00 là giờ họp với đội bán hàng; (B) 6:00 là giờ tiệc bắt đầu.\n(A) 5:00 chiều\n(B) 6:00 tối\n(C) 7:30 tối\n(D) 8:30 tối"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following announcement, e-mail, and Web page.","passages":["<h3>Alamito Botanical Society</h3><p>Submit your home garden to be one of several stops on this year’s Gorgeous Gardens Tour, scheduled for July 3!</p><p>This year’s tour theme is Winged Paradise, with a focus on flowering plants favored by regional birds and butterflies, including the lesser goldfinch and the ringlet butterfly. All proceeds from ticket sales for this year’s tour will go toward replanting the cottonwood forest in Presidio County Park.</p><p>Hosting a tour garden is free for members of the Alamito Botanical Society. Simply complete the form at www.alamitobotanicalsociety.org/gorgeousgardens and submit it with digital photos of your garden by May 20. Gardens selected to participate in the tour must be within Presidio County and include only plants native to the region. If you have questions regarding participating as a tour stop, please send an e-mail to info@alamitobotanicalsociety.org.</p>","<div class=\"hdr\"><p><b>To:</b> info@alamitobotanicalsociety.org</p><p><b>From:</b> rebeccaolton@mailhost.com</p><p><b>Date:</b> May 1</p><p><b>Subject:</b> Question about garden tour</p></div><p>Hello,</p><p>I became a member of the Alamito Botanical Society last year shortly after moving to Presidio County. The society’s Web site, resources, and educational lectures have been helpful regarding my ambitious project: to cover five acres of my land with various native plants that will attract birds and other animals. About one and a half acres of soil have been cultivated so far.</p><p>It would be a privilege to show my work to the public and to meet more people who value gardens as we members of the society do. Thus, I am writing to ask if I may participate in the Gorgeous Gardens Tour. I must admit that beautiful lavender bushes that are not native to the area were already growing on the property before I purchased it. However, lavender is not on the invasive-species list, and I continue to let them grow because the butterflies, bees, and other wildlife love the blooms.</p><p>Thank you,</p><p>Rebecca Olton</p>","<p>https://www.alamitobotanicalsociety.org/education/lectures</p><p>The leaders and members of the Alamito Botanical Society cordially invite the public to attend its educational lectures, held at the horticultural department of Marfa Community College. All lectures occur on the third Wednesday of the month at 7:00 P.M. Advance registration is not required.</p><p><b>February:</b> <u>Schedule Your Salad</u> – Get tips for establishing a planting timetable and for selecting delicious vegetables to grow.<br><b>March:</b> <u>Nourish the Neighbors</u> – Understand how to use plants native to our region to create landscapes that are inviting to wildlife.<br><b>April:</b> <u>Pest Deterrence</u> – Learn natural, pesticide-free techniques that can prevent harmful insects from eating your fruits and vegetables.<br><b>May:</b> <u>Pollen Transportation</u> – No butterflies or bees visiting your garden? No worries. Humans can pollinate certain plants using simple techniques.</p>"],"vi":"THÔNG BÁO\nHội Thực Vật Học Alamito\n\nHãy đăng ký khu vườn tại nhà của bạn để trở thành một trong những điểm dừng của Chuyến tham quan Những Khu Vườn Tuyệt Đẹp (Gorgeous Gardens Tour) năm nay, được tổ chức vào ngày 3 tháng 7!\n\nChủ đề của chuyến tham quan năm nay là “Thiên Đường Có Cánh”, tập trung vào các loài cây có hoa được các loài chim và bướm trong khu vực ưa thích, bao gồm chim sẻ vàng nhỏ (lesser goldfinch) và bướm ringlet. Toàn bộ doanh thu từ việc bán vé của chuyến tham quan năm nay sẽ được dùng để trồng lại rừng cây bông gòn (cottonwood) trong Công viên Quận Presidio.\n\nViệc đăng cai một khu vườn tham quan miễn phí đối với các thành viên của Hội Thực Vật Học Alamito. Chỉ cần hoàn thành mẫu đơn tại www.alamitobotanicalsociety.org/gorgeousgardens và gửi kèm ảnh kỹ thuật số của khu vườn trước ngày 20 tháng 5. Những khu vườn được chọn tham gia chuyến tham quan phải nằm trong Quận Presidio và chỉ bao gồm các loài cây bản địa của khu vực. Nếu bạn có câu hỏi liên quan đến việc tham gia với tư cách là một điểm dừng trong chuyến tham quan, vui lòng gửi email đến info@alamitobotanicalsociety.org.\n\nEMAIL\nGửi đến: info@alamitobotanicalsociety.org\nTừ: rebeccaolton@mailhost.com\nNgày: 1 tháng 5\nChủ đề: Câu hỏi về chuyến tham quan vườn\n\nXin chào,\n\nTôi đã trở thành thành viên của Hội Thực Vật Học Alamito vào năm ngoái, không lâu sau khi chuyển đến Quận Presidio. Trang web, các nguồn tài liệu và những buổi thuyết giảng mang tính giáo dục của hội đã hỗ trợ rất nhiều cho dự án đầy tham vọng của tôi: phủ xanh năm mẫu đất của mình bằng nhiều loại cây bản địa có khả năng thu hút chim chóc và các loài động vật khác. Cho đến nay, khoảng một mẫu rưỡi đất đã được canh tác.\n\nTôi sẽ rất vinh dự nếu được giới thiệu công việc của mình đến công chúng và được gặp gỡ thêm nhiều người có cùng sự trân trọng đối với các khu vườn như các thành viên của hội. Vì vậy, tôi viết email này để hỏi liệu tôi có thể tham gia Chuyến Tham Quan Những Khu Vườn Tuyệt Đẹp hay không. Tôi phải thừa nhận rằng có một số bụi hoa oải hương xinh đẹp không phải là loài bản địa của khu vực này đã được trồng sẵn trên mảnh đất trước khi tôi mua nó. Tuy nhiên, oải hương không nằm trong danh sách các loài xâm lấn, và tôi vẫn tiếp tục để chúng phát triển vì bướm, ong và các loài động vật hoang dã khác rất yêu thích những bông hoa này.\n\nXin cảm ơn,\nRebecca Olton\n\nTRANG WEB\nhttps://www.alamitobotanicalsociety.org/education/lectures\n\nCác lãnh đạo và thành viên của Hội Thực Vật Học Alamito trân trọng kính mời công chúng tham dự các buổi thuyết giảng mang tính giáo dục, được tổ chức tại khoa làm vườn của Trường Cao đẳng Cộng đồng Marfa. Tất cả các buổi thuyết giảng đều diễn ra vào tối thứ Tư tuần thứ ba hằng tháng lúc 7:00 tối. Không cần đăng ký trước.\n\nTháng 2: Schedule Your Salad (Lên lịch cho món salad) – Nhận các mẹo để xây dựng lịch trồng trọt và lựa chọn những loại rau ngon để trồng.\nTháng 3: Nourish the Neighbors (Nuôi dưỡng hàng xóm) – Tìm hiểu cách sử dụng các loài cây bản địa của khu vực để tạo nên cảnh quan thân thiện với động vật hoang dã.\nTháng 4: Pest Deterrence (Ngăn chặn sâu bệnh) – Học các kỹ thuật tự nhiên, không dùng thuốc trừ sâu, giúp ngăn côn trùng gây hại ăn trái cây và rau củ của bạn.\nTháng 5: Pollen Transportation (Vận chuyển phấn hoa) – Không có bướm hay ong ghé thăm khu vườn của bạn ư? Đừng lo. Con người có thể thụ phấn cho một số loài cây bằng các kỹ thuật đơn giản.","qs":[{"n":186,"q":"In the announcement, what is mentioned about the Gorgeous Gardens Tour?","qvi":"Trong thông báo, điều gì được nhắc đến về Gorgeous Gardens Tour?","opts":["Its focus will be on gardens that have a pond.","Profits from ticket sales will go toward planting trees.","One of the featured stops will be in a county park.","It will take place in May."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Thông báo: \"All proceeds from ticket sales for this year’s tour will go toward replanting the cottonwood forest in Presidio County Park.\" (Toàn bộ doanh thu bán vé sẽ dùng để trồng lại rừng cây bông gòn trong Công viên Quận Presidio.) (C) sai: công viên là nơi trồng cây, không phải điểm dừng; (D) sai: tour diễn ra ngày 3/7, 20/5 chỉ là hạn nộp đơn.\n(A) Tập trung vào những khu vườn có ao nước.\n(B) Lợi nhuận bán vé sẽ dành cho việc trồng cây.\n(C) Một điểm dừng sẽ nằm trong công viên quận.\n(D) Sự kiện diễn ra vào tháng Năm."},{"n":187,"q":"What does Ms. Olton mention in her e-mail?","qvi":"Cô Olton đề cập điều gì trong email?","opts":["She would like to join the Alamito Botanical Society.","She plans to donate the land needed for a recreation area.","She wants to meet people who share her interest in plants.","She knows people who want to buy tickets for a tour."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email: \"It would be a privilege to show my work to the public and to meet more people who value gardens as we members of the society do.\" (Tôi sẽ rất vinh dự nếu được... gặp gỡ thêm nhiều người trân trọng các khu vườn như các thành viên của hội.) (A) sai: cô đã là thành viên từ năm ngoái.\n(A) Muốn gia nhập Hội Thực vật học Alamito.\n(B) Định hiến đất cho một khu vui chơi.\n(C) Muốn gặp những người có cùng sở thích về cây cối.\n(D) Biết những người muốn mua vé tham quan."},{"n":188,"q":"What most likely will prevent Ms. Olton’s garden from being selected as a tour stop?","qvi":"Điều gì có khả năng khiến khu vườn của cô Olton không được chọn làm điểm dừng tham quan?","opts":["It includes a plant that comes from another region.","It does not meet the size requirement.","It features trees rather than flowers.","It is located outside the tour area."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Kết hợp thông báo + email. Thông báo: vườn tham gia phải \"include only plants native to the region\" (chỉ gồm các loài cây bản địa). Email: \"beautiful lavender bushes that are not native to the area were already growing on the property\" (có những bụi oải hương không phải loài bản địa) → vườn có cây từ vùng khác. (D) sai: cô sống ở Quận Presidio.\n(A) Có loài cây đến từ vùng khác.\n(B) Không đạt yêu cầu về kích thước.\n(C) Trồng cây thân gỗ thay vì hoa.\n(D) Nằm ngoài khu vực tham quan."},{"n":189,"q":"On the Web page, what is suggested about the lectures?","qvi":"Trên trang web, điều gì được gợi ý về các buổi thuyết giảng?","opts":["They are for Alamito Botanical Society members only.","They require a printed invitation.","They take place every month.","They are given at various locations."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Trang web: \"All lectures occur on the third Wednesday of the month at 7:00 P.M.\" (Tất cả các buổi thuyết giảng diễn ra vào thứ Tư tuần thứ ba hằng tháng) + lịch có bài giảng mỗi tháng (2, 3, 4, 5). (A) sai: mời công chúng; (B) sai: không cần đăng ký trước; (D) sai: đều ở Marfa Community College.\n(A) Chỉ dành cho thành viên Hội Alamito.\n(B) Cần thư mời in giấy.\n(C) Được tổ chức hằng tháng.\n(D) Được tổ chức ở nhiều địa điểm."},{"n":190,"q":"What lecture is Ms. Olton most likely to be interested in?","qvi":"Cô Olton có khả năng quan tâm đến buổi thuyết giảng nào nhất?","opts":["Schedule Your Salad","Nourish the Neighbors","Pest Deterrence","Pollen Transportation"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Kết hợp email + trang web. Email: dự án của cô là \"to cover five acres of my land with various native plants that will attract birds and other animals\" (phủ đất bằng cây bản địa thu hút chim và động vật). Trang web: Nourish the Neighbors – \"use plants native to our region to create landscapes that are inviting to wildlife\" (dùng cây bản địa tạo cảnh quan thân thiện với động vật hoang dã) → phù hợp nhất. (D) sai: vườn cô đã có nhiều bướm, ong.\n(A) Lên lịch cho món salad\n(B) Nuôi dưỡng hàng xóm\n(C) Ngăn chặn sâu bệnh\n(D) Vận chuyển phấn hoa"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following advertisement and e-mails.","passages":["<h3>Opportunity for Landowners</h3><p>Terra Jaunts organizes nature hikes, farm stays, camping trips, athletic competitions, and other activities for company retreats. We are seeking farmers, ranchers, and other landowners who can help us expand our list of destinations. Terra Jaunts pays up to $300 per day to our partners for the daytime use of their property and provides all or most needed equipment.</p><p>Our required criteria are as follows.</p><ol><li>The site is located within 100 kilometers of a medium to large city.</li><li>The site is able to host a retreat one or two days per month.</li><li>The site has adequate parking space for 50 cars or two buses.</li><li>The site can accommodate up to 75 people.</li></ol>","<div class=\"hdr\"><p><b>To:</b> Celia Newsom &lt;cnewsom@pinkridgeranch.com&gt;</p><p><b>From:</b> Oliver Jeong &lt;ojeong@terrajaunts.com&gt;</p><p><b>Date:</b> April 19</p><p><b>Subject:</b> Your application</p></div><p>Dear Ms. Newsom,</p><p>Thank you for applying to be a host. Even though you have less space for vehicles than we normally require, Pink Ridge Ranch might be suitable for our smaller events with fewer than 25 people. We appreciate your having created an illustrated list of all the native flowers and trees growing wild on your property; none of our other hosts offers anything like this. Your list of plants would be a real asset for groups engaged in activities involving the identification of species.</p><p>I would like to arrange a site visit with my associate Peter Cumberland either this week or next. After 1 P.M. on a Thursday or Friday would work best for us, but we will try to accommodate your schedule if you prefer a morning or a different day.</p><p>Sincerely,</p><p>Oliver Jeong<br>Montana Site Coordinator</p>","<div class=\"hdr\"><p><b>To:</b> Oliver Jeong &lt;ojeong@terrajaunts.com&gt;</p><p><b>From:</b> Celia Newsom &lt;cnewsom@pinkridgeranch.com&gt;</p><p><b>Date:</b> May 1</p><p><b>Subject:</b> RE: Your application</p></div><p>Dear Mr. Jeong:</p><p>Thank you for touring my ranch on Thursday. I am glad you were able to follow my complicated written directions for driving to and from the ranch after your GPS app stopped working. It was wonderful to meet you both and have a chance to show you around.</p><p>I received your follow-up voicemail yesterday. After further consideration, I have decided not to pursue this opportunity after all. The hiking paths on my property are quite overgrown, as your partner pointed out. Unfortunately, I do not have the time or staff to ensure that everything is properly groomed throughout the year. If this situation changes, I will reapply.</p><p>Kind regards,</p><p>Celia Newsom, Owner, Pink Ridge Ranch</p>"],"vi":"QUẢNG CÁO\nCơ Hội Dành Cho Chủ Đất\n\nTerra Jaunts tổ chức các chuyến đi bộ khám phá thiên nhiên, lưu trú tại nông trại, các chuyến cắm trại, các cuộc thi thể thao và những hoạt động khác dành cho các kỳ nghỉ tập thể (retreat) của công ty. Chúng tôi đang tìm kiếm nông dân, chủ trang trại chăn nuôi và các chủ đất khác có thể giúp chúng tôi mở rộng danh sách các điểm đến. Terra Jaunts chi trả lên đến 300 đô la Mỹ mỗi ngày cho các đối tác vì việc sử dụng ban ngày khu đất của họ, đồng thời cung cấp toàn bộ hoặc phần lớn các thiết bị cần thiết.\n\nCác tiêu chí bắt buộc như sau:\n1. Khu đất nằm trong phạm vi 100 kilômét từ một thành phố có quy mô trung bình đến lớn.\n2. Khu đất có khả năng đón tiếp một kỳ nghỉ tập thể một đến hai ngày mỗi tháng.\n3. Khu đất có bãi đỗ xe đủ cho 50 xe ô tô hoặc hai xe buýt.\n4. Khu đất có thể tiếp nhận tối đa 75 người.\n\nEMAIL 1\nGửi đến: Celia Newsom <cnewsom@pinkridgeranch.com>\nTừ: Oliver Jeong <ojeong@terrajaunts.com>\nNgày: 19 tháng 4\nChủ đề: Đơn đăng ký của bạn\n\nKính gửi bà Newsom,\n\nCảm ơn bà đã nộp đơn đăng ký trở thành địa điểm tổ chức. Mặc dù khu đất của bà có ít chỗ đậu xe hơn mức chúng tôi thường yêu cầu, Trang trại Pink Ridge vẫn có thể phù hợp cho các sự kiện quy mô nhỏ hơn của chúng tôi với dưới 25 người. Chúng tôi đánh giá cao việc bà đã tạo ra một danh sách minh họa về tất cả các loài hoa và cây bản địa mọc tự nhiên trên khu đất của mình; không có chủ địa điểm nào khác của chúng tôi cung cấp được điều tương tự. Danh sách thực vật của bà sẽ là một lợi thế lớn cho các nhóm tham gia các hoạt động liên quan đến nhận diện loài.\n\nTôi muốn sắp xếp một chuyến thăm thực địa cùng với cộng sự của tôi, Peter Cumberland, vào tuần này hoặc tuần tới. Sau 1 giờ chiều vào thứ Năm hoặc thứ Sáu sẽ phù hợp nhất với chúng tôi, tuy nhiên chúng tôi sẽ cố gắng điều chỉnh theo lịch của bà nếu bà muốn buổi sáng hoặc một ngày khác.\n\nTrân trọng,\nOliver Jeong\nĐiều phối viên địa điểm bang Montana\n\nEMAIL 2\nGửi đến: Oliver Jeong <ojeong@terrajaunts.com>\nTừ: Celia Newsom <cnewsom@pinkridgeranch.com>\nNgày: 1 tháng 5\nChủ đề: RE: Đơn đăng ký của bạn\n\nKính gửi ông Jeong,\n\nCảm ơn ông đã đến tham quan trang trại của tôi vào thứ Năm. Tôi rất vui vì ông đã có thể làm theo chỉ dẫn bằng văn bản khá phức tạp của tôi để lái xe đến và rời khỏi trang trại sau khi ứng dụng GPS của ông ngừng hoạt động. Thật tuyệt khi được gặp cả hai ông và có cơ hội dẫn các ông đi tham quan.\n\nTôi đã nhận được tin nhắn thoại theo dõi của ông vào ngày hôm qua. Sau khi cân nhắc kỹ hơn, tôi đã quyết định không tiếp tục theo đuổi cơ hội này. Các lối đi bộ đường dài trên khu đất của tôi bị mọc um tùm, như cộng sự của ông đã chỉ ra. Đáng tiếc là tôi không có đủ thời gian hoặc nhân sự để đảm bảo mọi thứ được chăm sóc, cắt tỉa đúng cách quanh năm. Nếu tình hình này thay đổi, tôi sẽ nộp đơn lại.\n\nTrân trọng,\nCelia Newsom, Chủ sở hữu, Trang trại Pink Ridge","qs":[{"n":191,"q":"What does the advertisement mention about Terra Jaunts?","qvi":"Quảng cáo cho biết gì về Terra Jaunts?","opts":["It employs 75 people.","It arranges team-building trips for corporate clients.","It hosts monthly retreats for its staff.","It has a service contract with two bus companies."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Quảng cáo: \"Terra Jaunts organizes nature hikes, farm stays, camping trips, athletic competitions, and other activities for company retreats.\" (tổ chức các hoạt động cho các kỳ nghỉ tập thể của công ty) → sắp xếp chuyến đi gắn kết đội nhóm cho khách hàng doanh nghiệp. (A) sai: 75 là số người tối đa khu đất phải chứa được.\n(A) Có 75 nhân viên.\n(B) Tổ chức các chuyến đi gắn kết đội nhóm cho khách hàng doanh nghiệp.\n(C) Tổ chức kỳ nghỉ hằng tháng cho nhân viên của mình.\n(D) Có hợp đồng dịch vụ với hai hãng xe buýt."},{"n":192,"q":"What can be concluded about Pink Ridge Ranch?","qvi":"Có thể kết luận gì về Pink Ridge Ranch?","opts":["It has a reliable wireless network.","It has several large greenhouses.","It earned $300 for hosting a group of hikers.","It is located within 100 kilometers of an urban area."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp quảng cáo + email 1. Quảng cáo: tiêu chí bắt buộc số 1 \"The site is located within 100 kilometers of a medium to large city.\" Email 1: ông Jeong chỉ nêu thiếu chỗ đậu xe nhưng vẫn cho rằng trang trại \"might be suitable\" và muốn đến thăm → trang trại đáp ứng tiêu chí khoảng cách (trong vòng 100 km từ thành phố). (A) sai: GPS của ông Jeong bị mất tín hiệu; (C) sai: trang trại chưa từng tổ chức.\n(A) Có mạng không dây ổn định.\n(B) Có nhiều nhà kính lớn.\n(C) Đã kiếm được 300 đô khi đón một nhóm đi bộ đường dài.\n(D) Nằm trong phạm vi 100 km từ một khu đô thị."},{"n":193,"q":"According to Mr. Jeong, what distinguishes Ms. Newsom from other property owners?","qvi":"Theo ông Jeong, điều gì khiến bà Newsom khác biệt với những chủ đất khác?","opts":["The information that she provides about plants","The variety of flowers she is able to grow","Her flexible schedule","Her interest in art"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Email 1: \"We appreciate your having created an illustrated list of all the native flowers and trees growing wild on your property; none of our other hosts offers anything like this.\" (Chúng tôi đánh giá cao danh sách minh họa các loài hoa và cây bản địa...; không chủ địa điểm nào khác cung cấp được điều này.) (B) sai: cây mọc tự nhiên (growing wild), không phải bà trồng.\n(A) Thông tin bà cung cấp về thực vật\n(B) Sự đa dạng các loài hoa bà trồng được\n(C) Lịch làm việc linh hoạt của bà\n(D) Sở thích nghệ thuật của bà"},{"n":194,"q":"What is suggested about Pink Ridge Ranch?","qvi":"Điều gì được gợi ý về Pink Ridge Ranch?","opts":["It requires an access code to enter.","It recently changed ownership.","It can be difficult to find.","It is a popular hiking destination."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email 2: \"I am glad you were able to follow my complicated written directions for driving to and from the ranch after your GPS app stopped working.\" (Tôi rất vui vì ông đã làm theo được chỉ dẫn khá phức tạp của tôi để lái xe đến và rời trang trại sau khi GPS ngừng hoạt động.) → trang trại khó tìm.\n(A) Cần mã truy cập để vào.\n(B) Mới đổi chủ.\n(C) Có thể khó tìm đường đến.\n(D) Là điểm đi bộ đường dài nổi tiếng."},{"n":195,"q":"What is most likely true about Mr. Cumberland?","qvi":"Điều gì có khả năng đúng nhất về ông Cumberland?","opts":["He does not work on Fridays.","He expressed concern about a set of trails.","He owns an organic farm in Montana.","He left a voicemail for Ms. Newsom on April 22."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Kết hợp email 1 + email 2. Email 1: \"arrange a site visit with my associate Peter Cumberland\" → Cumberland là cộng sự của ông Jeong. Email 2: \"The hiking paths on my property are quite overgrown, as your partner pointed out.\" (Các lối đi bộ bị mọc um tùm, như cộng sự của ông đã chỉ ra) → ông Cumberland đã nêu lo ngại về các lối mòn. (D) sai: thư thoại do ông Jeong gửi, vào ngày 30/4 (hôm qua so với 1/5).\n(A) Ông không làm việc vào thứ Sáu.\n(B) Ông bày tỏ lo ngại về các lối mòn đi bộ.\n(C) Ông sở hữu một trang trại hữu cơ ở Montana.\n(D) Ông để lại thư thoại cho bà Newsom vào ngày 22/4."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following e-mails and schedule.","passages":["<div class=\"hdr\"><p><b>To:</b> Department Managers &lt;managementteam@a-qualityelectronics.com&gt;</p><p><b>From:</b> Eileen Wrenn &lt;ewrenn@a-qualityelectronics.com&gt;</p><p><b>Date:</b> October 7</p><p><b>Subject:</b> Upcoming visit with Kenji Tanaka</p><p><b>Attachment:</b> Draft schedule</p></div><p>Good morning,</p><p>Mr. Harlington has asked me to let all department managers know that Kenji Tanaka, the chief operating officer of our Japanese subsidiary Kanazawa Electronics, will be visiting our corporate headquarters next week. Please let me know as soon as possible whether you will be able to attend the afternoon meeting and dinner on October 14 so I can make the appropriate arrangements.</p><p>A draft schedule is attached to this e-mail. Mr. Tanaka will take the distinguished visitor slot, which Mr. Harlington created last quarter in an effort to reinvigorate our corporate culture.</p><p>Departmental reports will begin promptly at 3:00 P.M., following the presentations by Mr. Harlington and Mr. Tanaka, respectively. Details will be announced soon regarding the information that department managers will present in their status reports.</p><p>Best,</p><p>Eileen Wrenn, Executive Assistant</p>","<h3>DRAFT SCHEDULE</h3><h4>A-Quality Electronics Quarterly Meeting<br>Monday, October 14</h4><table><tr><td>12:00–1:00 P.M.</td><td>All staff</td><td>Catered lunch</td></tr><tr><td>1:00–2:00 P.M.</td><td>President</td><td>Discussion of company goals and performance objectives; status of joint projects</td></tr><tr><td>2:00–3:00 P.M.</td><td>Distinguished visitor</td><td>Update on Kanazawa Electronics: operational successes and challenges faced by the subsidiary in the third quarter</td></tr><tr><td>3:00–5:00 P.M.</td><td>Department managers</td><td>Departmental reports: agenda to be determined</td></tr><tr><td>6:00–9:00 P.M.</td><td>All staff</td><td>Dinner at Mapleton Grill, downtown Mapleton</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> Eileen Wrenn &lt;ewrenn@a-qualityelectronics.com&gt;</p><p><b>From:</b> Deborah Powell &lt;dpowell@a-qualityelectronics.com&gt;</p><p><b>Date:</b> October 7</p><p><b>Subject:</b> Re: Upcoming visit with Kenji Tanaka</p></div><p>Hi Eileen,</p><p>I’m confirming my availability for the meeting with Kenji Tanaka. I plan to update the executives on the marketing team’s activities for the third quarter.</p><p>Question: do you think Mr. Tanaka might like to go to a baseball game after dinner? He enjoyed seeing the Mapleton Ospreys play after he attended the second quarter meeting in July.</p><p>The only problem is that all games in October begin at 8:00 P.M., so we would need to begin dinner at around 5:00 P.M. That would give us enough time to get to the stadium before the game starts. I know this is a lot to ask for, but I think it is worth considering, knowing how much our distinguished visitor enjoyed the Ospreys game and how important he is to the company.</p><p>Let me know what you think so I can secure tickets before his visit. Thanks!</p><p>Deborah Powell</p>"],"vi":"EMAIL 1\nGửi đến: Các Trưởng phòng ban <managementteam@a-qualityelectronics.com>\nTừ: Eileen Wrenn <ewrenn@a-qualityelectronics.com>\nNgày: 7 tháng 10\nChủ đề: Chuyến thăm sắp tới của ông Kenji Tanaka\nTệp đính kèm: Lịch trình dự thảo\n\nChào buổi sáng,\n\nÔng Harlington đã yêu cầu tôi thông báo đến tất cả các trưởng phòng ban rằng ông Kenji Tanaka, Giám đốc điều hành (COO) của công ty con tại Nhật Bản của chúng ta – Kanazawa Electronics, sẽ đến thăm trụ sở chính của công ty vào tuần tới. Vui lòng cho tôi biết sớm nhất có thể liệu anh/chị có thể tham dự cuộc họp buổi chiều và bữa tối vào ngày 14 tháng 10 hay không để tôi có thể sắp xếp phù hợp.\n\nMột bản lịch trình dự thảo được đính kèm trong email này. Ông Tanaka sẽ đảm nhận phần dành cho khách mời danh dự, phần mà ông Harlington đã tạo ra vào quý trước nhằm làm mới văn hóa doanh nghiệp của chúng ta.\n\nCác báo cáo của các phòng ban sẽ bắt đầu đúng 3:00 chiều, sau phần trình bày lần lượt của ông Harlington và ông Tanaka. Thông tin chi tiết về nội dung mà các trưởng phòng ban sẽ trình bày trong báo cáo tình hình công việc sẽ sớm được thông báo.\n\nTrân trọng,\nEileen Wrenn, Trợ lý điều hành\n\nLỊCH TRÌNH DỰ THẢO\nCuộc Họp Hàng Quý của A-Quality Electronics\nThứ Hai, ngày 14 tháng 10\n\n12:00 – 1:00 chiều | Toàn thể nhân viên | Bữa trưa có phục vụ\n1:00 – 2:00 chiều | Chủ tịch | Thảo luận về mục tiêu công ty và mục tiêu hiệu quả hoạt động; tình trạng các dự án hợp tác\n2:00 – 3:00 chiều | Khách mời danh dự | Cập nhật về Kanazawa Electronics: các thành công trong vận hành và những thách thức mà công ty con gặp phải trong quý ba\n3:00 – 5:00 chiều | Các trưởng phòng ban | Báo cáo phòng ban: nội dung sẽ được xác định sau\n6:00 – 9:00 tối | Toàn thể nhân viên | Bữa tối tại Mapleton Grill, khu trung tâm Mapleton\n\nEMAIL 2\nGửi đến: Eileen Wrenn <ewrenn@a-qualityelectronics.com>\nTừ: Deborah Powell <dpowell@a-qualityelectronics.com>\nNgày: 7 tháng 10\nChủ đề: Re: Chuyến thăm sắp tới của ông Kenji Tanaka\n\nChào Eileen,\n\nTôi xác nhận rằng tôi có thể tham dự cuộc họp với ông Kenji Tanaka. Tôi dự định sẽ cập nhật cho ban điều hành về các hoạt động của đội marketing trong quý ba.\n\nTôi có một câu hỏi: bạn có nghĩ ông Tanaka sẽ muốn đi xem một trận bóng chày sau bữa tối không? Ông ấy đã rất thích xem đội Mapleton Ospreys thi đấu sau khi tham dự cuộc họp quý hai vào tháng Bảy.\n\nVấn đề duy nhất là tất cả các trận đấu trong tháng Mười đều bắt đầu lúc 8:00 tối, vì vậy chúng ta sẽ cần bắt đầu bữa tối vào khoảng 5:00 chiều. Như vậy sẽ có đủ thời gian để di chuyển đến sân vận động trước khi trận đấu bắt đầu. Tôi biết đây là một yêu cầu khá nhiều, nhưng tôi nghĩ đáng để cân nhắc, khi biết vị khách mời danh dự của chúng ta rất thích trận đấu của đội Ospreys và ông ấy quan trọng thế nào đối với công ty.\n\nHãy cho tôi biết ý kiến của bạn để tôi có thể đặt vé trước chuyến thăm của ông ấy. Cảm ơn nhé!\n\nDeborah Powell","qs":[{"n":196,"q":"Who most likely is Mr. Harlington?","qvi":"Ông Harlington có khả năng là ai?","opts":["The founder of Kanazawa Electronics","The president of A-Quality Electronics","A department manager","An executive assistant"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Kết hợp email 1 + lịch trình. Email 1: báo cáo phòng ban bắt đầu lúc 3:00 \"following the presentations by Mr. Harlington and Mr. Tanaka, respectively\" (sau phần trình bày lần lượt của ông Harlington và ông Tanaka). Lịch trình: 1:00–2:00 President (Chủ tịch), 2:00–3:00 Distinguished visitor (ông Tanaka) → ông Harlington là Chủ tịch. (D) sai: trợ lý điều hành là Eileen Wrenn.\n(A) Người sáng lập Kanazawa Electronics\n(B) Chủ tịch của A-Quality Electronics\n(C) Một trưởng phòng ban\n(D) Một trợ lý điều hành"},{"n":197,"q":"According to the first e-mail, what should managers do as soon as possible?","qvi":"Theo email đầu tiên, các trưởng phòng cần làm gì sớm nhất có thể?","opts":["Provide feedback on a schedule","Prepare presentations for a meeting","Save a date for lunch","Indicate their availability for a meeting"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email 1: \"Please let me know as soon as possible whether you will be able to attend the afternoon meeting and dinner on October 14\" (Vui lòng cho tôi biết sớm nhất có thể liệu anh/chị có thể tham dự cuộc họp buổi chiều và bữa tối ngày 14/10 không). (B) sai: nội dung báo cáo sẽ được thông báo sau.\n(A) Góp ý về lịch trình\n(B) Chuẩn bị bài thuyết trình cho cuộc họp\n(C) Dành thời gian cho bữa trưa\n(D) Cho biết họ có thể tham dự cuộc họp hay không"},{"n":198,"q":"According to the schedule, what happened in the third quarter?","qvi":"Theo lịch trình, điều gì đã xảy ra trong quý ba?","opts":["New projects were profitable.","Corporate objectives changed.","A subsidiary faced some difficulties.","New operational staff were hired."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Lịch trình (2:00–3:00): \"Update on Kanazawa Electronics: operational successes and challenges faced by the subsidiary in the third quarter\" (những thách thức mà công ty con gặp phải trong quý ba) → challenges = difficulties.\n(A) Các dự án mới có lợi nhuận.\n(B) Mục tiêu công ty thay đổi.\n(C) Một công ty con gặp một số khó khăn.\n(D) Tuyển thêm nhân viên vận hành mới."},{"n":199,"q":"What will Ms. Powell most likely do on October 14?","qvi":"Ngày 14/10, cô Powell có khả năng sẽ làm gì?","opts":["She will join other managers in delivering reports.","She will discuss the marketing department’s goals.","She will purchase some baseball tickets.","She will take Mr. Tanaka out to lunch."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Kết hợp email 1, lịch trình và email 2. Email 1 gửi cho các trưởng phòng ban; cô Powell xác nhận tham dự và viết: \"I plan to update the executives on the marketing team’s activities for the third quarter.\" (cập nhật cho ban điều hành về hoạt động của đội marketing trong quý ba) → đây chính là báo cáo phòng ban (status report). Lịch trình: 3:00–5:00 \"Department managers – Departmental reports\" → cô sẽ cùng các trưởng phòng khác trình bày báo cáo. (B) sai: cô báo cáo hoạt động (activities) quý ba, không phải mục tiêu (goals); phần thảo luận mục tiêu là của Chủ tịch. (C) sai: cô muốn đặt vé trước chuyến thăm, không phải vào ngày 14/10.\n(A) Cùng các trưởng phòng khác trình bày báo cáo.\n(B) Thảo luận về mục tiêu của phòng marketing.\n(C) Mua vé xem bóng chày.\n(D) Đưa ông Tanaka đi ăn trưa.","note":"Ghi chú trong file đáp án của giáo viên (\"Vai trò chuyên môn → thảo luận mục tiêu/hoạt động marketing, không phải báo cáo phòng ban chung\") có vẻ nghiêng về (B). Tuy nhiên theo đề, cô Powell là trưởng phòng (email gửi Department Managers), cô sẽ cập nhật \"hoạt động\" quý ba của đội marketing – đúng phần \"Departmental reports\" của các trưởng phòng lúc 3:00–5:00; còn \"company goals\" là phần của Chủ tịch. Vì vậy chọn (A)."},{"n":200,"q":"What does Ms. Powell request?","qvi":"Cô Powell đề nghị điều gì?","opts":["Moving a meeting date","Asking Mr. Tanaka to speak last","Rescheduling a meal","Arranging transportation to a stadium"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Kết hợp lịch trình + email 2. Lịch trình: bữa tối 6:00–9:00 P.M. Email 2: \"all games in October begin at 8:00 P.M., so we would need to begin dinner at around 5:00 P.M.\" (cần bắt đầu bữa tối vào khoảng 5:00 chiều) → cô đề nghị dời giờ bữa tối.\n(A) Dời ngày họp\n(B) Đề nghị ông Tanaka phát biểu cuối cùng\n(C) Dời giờ một bữa ăn\n(D) Sắp xếp phương tiện đến sân vận động"}]}]}};
